INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22690, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "攻击性", "is_correct": false, "explanation": "语义：“攻击性”指好斗、伤害他人的倾向，与“每天晚上想想自己做得好不好”无关。"}, {"text": "反思性", "is_correct": true, "explanation": "反思性指喜欢反省自己的特点，与“每天晚上想想自己做得好不好”一致。"}, {"text": "随意性", "is_correct": false, "explanation": "语义：“随意性”指做事随便，与“每天晚上都想想自己做得好不好”相矛盾。"}, {"text": "形象性", "is_correct": false, "explanation": "搭配：“形象性”多用于艺术、语言作品，不说人“有形象性”。"}], "explanations": {"攻击性": "语义：“攻击性”指好斗、伤害他人的倾向，与“每天晚上想想自己做得好不好”无关。", "反思性": "反思性指喜欢反省自己的特点，与“每天晚上想想自己做得好不好”一致。", "随意性": "语义：“随意性”指做事随便，与“每天晚上都想想自己做得好不好”相矛盾。", "形象性": "搭配：“形象性”多用于艺术、语言作品，不说人“有形象性”。"}, "sentence_index": 0, "correct_answer": "反思性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个孩子越来越有反思性了，总想赢过同学。", "explanation": "这里应该用〈竞争性〉。竞争性指争胜的特点；反思性指对自己的反省，与“想赢过同学”的意思不符。"}, {"text": "这种反应越来越有反思性了，不需要经过大脑。", "explanation": "这里应该用〈反射性〉。反射性指不经大脑的被动反应，反思性指主动思考，两者不能互换。"}, {"text": "这位评论家越来越有反思性了，专门挑别人作品的毛病。", "explanation": "这里应该用〈批判性〉。批判性指对别人或作品提出质疑，反思性指对自己的反省。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b59260c-a60d-44ae-96a6-595f6763726d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22690, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地方性", "is_correct": false, "explanation": "语义：“地方性”指地域特色，不指一个人的内在特点。"}, {"text": "反思性", "is_correct": true, "explanation": "反思性指反省自己的特点，“提高反思性”是常见搭配，符合句意。"}, {"text": "偶然性", "is_correct": false, "explanation": "语义：“偶然性”指出乎意料的特点，不是人能靠写日记提高的能力。"}, {"text": "衰退性", "is_correct": false, "explanation": "搭配：“提高”是向上的变化，“衰退性”是向下的性质，二者不搭配。"}], "explanations": {"地方性": "语义：“地方性”指地域特色，不指一个人的内在特点。", "反思性": "反思性指反省自己的特点，“提高反思性”是常见搭配，符合句意。", "偶然性": "语义：“偶然性”指出乎意料的特点，不是人能靠写日记提高的能力。", "衰退性": "搭配：“提高”是向上的变化，“衰退性”是向下的性质，二者不搭配。"}, "sentence_index": 6, "correct_answer": "反思性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个旧问题的反思性很强，每年都会重新出现。", "explanation": "这里应该用〈反复性〉。反复性指同样的情况一再出现；反思性指对自己的反省，不能用来说问题。"}, {"text": "这种皮肤的反思性很强，一碰就发红。", "explanation": "这里应该用〈敏感性〉。敏感性指对刺激反应强烈；反思性指人的自省，不能用于皮肤。"}, {"text": "这条消息的反思性很强，今天就过期了。", "explanation": "这里应该用〈时效性〉。时效性指有效的时间长短，消息说的是时效，不是反思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b59260c-a60d-44ae-96a6-595f6763726d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22690, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很有的反思性，做错题后会认真分析原因。", "corrected_sentence": "他很有反思性，做错题后会认真分析原因。", "error_description": "“有”后直接接“的”，“很有的反思性”不成立；应为“很有反思性”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b59260c-a60d-44ae-96a6-595f6763726d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22690, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个班的学生都有很强反思性，遇到问题先找自己。", "corrected_sentence": "这个班的学生都有很强的反思性，遇到问题先找自己。", "error_description": "“很强”作定语修饰名词时，要在修饰语后加“的”，应为“很强的反思性”。漏掉“的”是常见错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b59260c-a60d-44ae-96a6-595f6763726d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
