INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22694, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让别人听你的话，并按照你的要求去做。", "primary_collocate": null, "pronunciation": "guī xùn", "ipa": "kweɪ̯˥ ɕyn˥˩", "syllable_count": 2, "sentences": [{"text": "父母总想规训自己的孩子。", "target_word": "规训", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用严格的规矩规训学生。", "target_word": "规训", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想规训新来的员工，让他们听话。", "target_word": "规训", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不能这样规训别人，大家都有自己的想法。", "target_word": "规训", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教练把队员规训得很听话。", "target_word": "规训", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想用批评来规训丈夫，结果吵了一架。", "target_word": "规训", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板想规训员工，让大家按他的话做。", "target_word": "规训", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷喜欢规训晚辈，什么都要听他的。", "target_word": "规训", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用命令的口气规训同事，大家都不高兴。", "target_word": "规训", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家长不应该用打骂的方法规训孩子。", "target_word": "规训", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "规训了", "label": "体标（了）"}, {"form": "规训过", "label": "体标（过）"}, {"form": "規訓", "label": "繁体"}], "register": "书面", "sense_fingerprint": "让别人听话并照自己的要求行事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dcaf70f6-1c60-4940-ade5-b030778acacc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22694, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "规训", "is_correct": true, "explanation": "正确：“规训”指让人听话、按要求去做，与“父母总想”和“自己的孩子”搭配，句意通顺。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：“翻译”指转换语言，不能用来指父母对孩子的管束，句意不通。"}, {"text": "雕刻", "is_correct": false, "explanation": "搭配：“雕刻”的对象是石头、木材等材料，不能用于“孩子”。"}, {"text": "打印", "is_correct": false, "explanation": "语义：“打印”指输出文件或图片，与父母想让孩子听话的意图无关。"}], "explanations": {"规训": "正确：“规训”指让人听话、按要求去做，与“父母总想”和“自己的孩子”搭配，句意通顺。", "翻译": "语义：“翻译”指转换语言，不能用来指父母对孩子的管束，句意不通。", "雕刻": "搭配：“雕刻”的对象是石头、木材等材料，不能用于“孩子”。", "打印": "语义：“打印”指输出文件或图片，与父母想让孩子听话的意图无关。"}, "sentence_index": 0, "correct_answer": "规训"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "教练每天规训队员的体能。", "explanation": "这里应该用〈训练〉。规训是让人服从要求，锻炼体能要用“训练”。"}, {"text": "他每天早上规训房间。", "explanation": "这里应该用〈打扫〉。规训的对象是人，不能用于整理房间。"}, {"text": "她每天规训衣服。", "explanation": "这里应该用〈缝补〉。规训的对象是人，缝补衣服要用“缝补”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5cc93b5-3c52-41c1-8841-7642119eb5f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22694, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "规训", "is_correct": true, "explanation": "正确：“规训”指让员工服从老板的要求，与“让大家按他的话做”相符。"}, {"text": "饲养", "is_correct": false, "explanation": "搭配：“饲养”用于动物，不说“饲养员工”。"}, {"text": "播种", "is_correct": false, "explanation": "搭配：“播种”用于种子或田地，不能用于员工。"}, {"text": "烘焙", "is_correct": false, "explanation": "语义：“烘焙”指制作面包糕点，与“让大家按他的话做”的语境无关。"}], "explanations": {"规训": "正确：“规训”指让员工服从老板的要求，与“让大家按他的话做”相符。", "饲养": "搭配：“饲养”用于动物，不说“饲养员工”。", "播种": "搭配：“播种”用于种子或田地，不能用于员工。", "烘焙": "语义：“烘焙”指制作面包糕点，与“让大家按他的话做”的语境无关。"}, "sentence_index": 6, "correct_answer": "规训"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈每天规训晚饭。", "explanation": "这里应该用〈烹饪〉。规训的对象是人，不能用于做饭。"}, {"text": "他规训了坏掉的自行车。", "explanation": "这里应该用〈修理〉。规训不能用于机械设备，修车要用“修理”。"}, {"text": "农民每天规训庄稼。", "explanation": "这里应该用〈浇灌〉。规训的对象是人，浇灌庄稼要用“浇灌”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5cc93b5-3c52-41c1-8841-7642119eb5f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22694, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把儿子规训很有礼貌。", "corrected_sentence": "他把儿子规训得很有礼貌。", "error_description": "缺补语标记“得”：动词后接状态补语时要用“得”，应说“规训得很有礼貌”，不能直接说“规训很有礼貌”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5cc93b5-3c52-41c1-8841-7642119eb5f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22694, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他以前规训着新来的员工，让他们听话。", "corrected_sentence": "他以前规训过新来的员工，让他们听话。", "error_description": "体标错误：“以前”指过去的经历，应用经历体“过”，不能用表示持续的“着”，应说“规训过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5cc93b5-3c52-41c1-8841-7642119eb5f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
