INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22696, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5cc93b5-3c52-41c1-8841-7642119eb5f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22696, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人文意思是人类的文化和生活方式。", "primary_collocate": null, "pronunciation": "rén wén", "ipa": "ʐən˧˥ wən˧˥", "syllable_count": 2, "sentences": [{"text": "旅行时，我喜欢了解当地的人文。", "target_word": "人文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子的自然风景和人文都很有名。", "target_word": "人文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外国游客对中国的人文很感兴趣。", "target_word": "人文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "南方和北方的人文很不一样。", "target_word": "人文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条老街保留着很多人文特色。", "target_word": "人文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本杂志介绍世界各地的风景和人文。", "target_word": "人文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们去山区，不但看了风景，还体验了当地人文。", "target_word": "人文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座古城的人文风貌让游客着迷。", "target_word": "人文", "complexity_tier": "T3", "furigana": "zhè zuò gǔ chéng de rén wén fēng mào ràng yóu kè zháo mí", "sentence_source": "generated"}, {"text": "学习语言也是在认识一个国家的人文。", "target_word": "人文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拍了很多照片，记录下小城的人文风情。", "target_word": "人文", "complexity_tier": "T3", "furigana": "tā pāi le hěn duō zhàopiàn jìlù xià xiǎochéng de rén wén fēngqíng", "sentence_source": "generated"}], "morphological_forms": [{"form": "人文主义", "label": "复合"}, {"form": "人文精神", "label": "复合"}, {"form": "人文学科", "label": "复合"}], "register": "书面", "sense_fingerprint": "一个地方或民族的文化与生活方式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dcaf70f6-1c60-4940-ade5-b030778acacc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22696, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "作业", "is_correct": false, "explanation": "语义：“作业”与“旅行时喜欢了解当地”的语境不合，不能说“了解当地的作业”。"}, {"text": "人文", "is_correct": true, "explanation": "“当地的人文”指一地的文化与生活方式，正是旅行时想了解的内容。"}, {"text": "账单", "is_correct": false, "explanation": "语义：“账单”是消费记录，与旅行时了解当地的兴趣不合。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“了解”的对象多是地方或人的情况，“体重”不能作“了解当地的”的宾语。"}], "explanations": {"作业": "语义：“作业”与“旅行时喜欢了解当地”的语境不合，不能说“了解当地的作业”。", "人文": "“当地的人文”指一地的文化与生活方式，正是旅行时想了解的内容。", "账单": "语义：“账单”是消费记录，与旅行时了解当地的兴趣不合。", "体重": "搭配：“了解”的对象多是地方或人的情况，“体重”不能作“了解当地的”的宾语。"}, "sentence_index": 0, "correct_answer": "人文"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个小镇的人文有三万。", "explanation": "这里应该用〈人口〉。“人文”指一地的文化与生活方式，不能用来表示人数。"}, {"text": "这个地方的人文很湿润。", "explanation": "这里应该用〈气候〉。“湿润”形容气候或空气，不能形容文化与生活方式。"}, {"text": "这里的人文很高。", "explanation": "这里应该用〈海拔〉。“人文”不能表示地势的高低，说高低要用“海拔”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5cc93b5-3c52-41c1-8841-7642119eb5f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22696, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "考勤", "is_correct": false, "explanation": "语义：“考勤”是单位的管理制度，与山区旅游的语境不合，不能说“体验了当地考勤”。"}, {"text": "人文", "is_correct": true, "explanation": "“当地人文”是山区的文化与生活方式，与“看了风景”形成对照，是要体验的内容。"}, {"text": "方程", "is_correct": false, "explanation": "语义：“方程”是数学概念，不能被“体验”，与旅行语境不合。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“体验”多接生活、文化、风土等，不说“体验当地工资”。"}], "explanations": {"考勤": "语义：“考勤”是单位的管理制度，与山区旅游的语境不合，不能说“体验了当地考勤”。", "人文": "“当地人文”是山区的文化与生活方式，与“看了风景”形成对照，是要体验的内容。", "方程": "语义：“方程”是数学概念，不能被“体验”，与旅行语境不合。", "工资": "搭配：“体验”多接生活、文化、风土等，不说“体验当地工资”。"}, "sentence_index": 6, "correct_answer": "人文"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这几天的人文很热，大家都想出门。", "explanation": "这里应该用〈天气〉。“天气”指一段时间内的冷暖阴晴，形容天热要用“天气”；“人文”指文化与生活方式，不能形容冷暖。"}, {"text": "他这学期的人文增加了三公斤。", "explanation": "这里应该用〈体重〉。“体重”指人身体的重量，增加几公斤要用“体重”；“人文”指文化与生活方式，不能计算重量。"}, {"text": "这盘菜的人文太咸了。", "explanation": "这里应该用〈味道〉。“味道”指食物的滋味，说咸要用“味道”；“人文”指文化与生活方式，不能形容滋味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5cc93b5-3c52-41c1-8841-7642119eb5f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22696, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在这座城市里感受到一把独特的人文。", "corrected_sentence": "他在这座城市里感受到一种独特的人文。", "error_description": "量词错误：“人文”指一地的文化与生活方式，应用“种”，不能用“把”（“把”用于有柄的器具）。应改为“一种独特的人文”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5cc93b5-3c52-41c1-8841-7642119eb5f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22696, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个古镇的独特地人文很迷人。", "corrected_sentence": "这个古镇的独特的人文很迷人。", "error_description": "结构助词错误：“独特”修饰名词“人文”，应用“的”，不能用“地”（“地”用于动词、形容词作状语的后面）。应改为“独特的人文”，即“这个古镇的独特的人文很迷人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5cc93b5-3c52-41c1-8841-7642119eb5f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22700, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1697b85-2e0f-4e53-8d0e-b40ae68bea44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22700, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1697b85-2e0f-4e53-8d0e-b40ae68bea44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22700, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "温度是表示物体有多热或者多冷的数字。", "primary_collocate": null, "pronunciation": "wēn dù", "ipa": "wən˥ tu˥˩", "syllable_count": 2, "sentences": [{"text": "天气预报说明天温度很低。", "target_word": "温度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水的温度到一百度就会开。", "target_word": "温度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间温度太高了。", "target_word": "温度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道今天的温度是多少吗？", "target_word": "温度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天的温度常常超过三十五度。", "target_word": "温度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰箱里的温度很低。", "target_word": "温度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "温度越高，冰化得越快。", "target_word": "温度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用手机看外面的温度。", "target_word": "温度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天的温度不冷也不热。", "target_word": "温度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗澡水的温度刚刚好。", "target_word": "温度", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "温度计", "label": "复合"}], "register": "中性", "sense_fingerprint": "表示物体热或冷程度的数字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba713f93-d7fe-4309-b531-8a7d0486cb5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22700, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "温度", "is_correct": true, "explanation": "“温度”指冷热的数字，“明天温度很低”说的是气温低，符合语境。"}, {"text": "人气", "is_correct": false, "explanation": "语义：人气指受欢迎的程度，天气预报不会说明人气的高低。"}, {"text": "成绩", "is_correct": false, "explanation": "语义：成绩指学习或比赛的结果，与天气无关。"}, {"text": "面积", "is_correct": false, "explanation": "搭配：“很低”不能修饰“面积”，面积一般说“大小”。"}], "explanations": {"温度": "“温度”指冷热的数字，“明天温度很低”说的是气温低，符合语境。", "人气": "语义：人气指受欢迎的程度，天气预报不会说明人气的高低。", "成绩": "语义：成绩指学习或比赛的结果，与天气无关。", "面积": "搭配：“很低”不能修饰“面积”，面积一般说“大小”。"}, "sentence_index": 0, "correct_answer": "温度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这杯糖水的温度很浓。", "explanation": "这里应该用〈浓度〉。温度只说冷热，溶液的甜淡、浓淡要用浓度，不能说“很浓”。"}, {"text": "这首歌现在的温度是多少呢？", "explanation": "这里应该用〈热度〉。温度不能用来表示歌曲受欢迎的程度。"}, {"text": "这篇文章的温度是多少？", "explanation": "这里应该用〈字数〉。温度不能用来计算文字的多少。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1697b85-2e0f-4e53-8d0e-b40ae68bea44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22700, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "温度", "is_correct": true, "explanation": "“温度越高”说明冷热的程度，温度越高冰化得越快，符合语境。"}, {"text": "亮度", "is_correct": false, "explanation": "语义：亮度指明暗的程度，与冰化的快慢无关。"}, {"text": "音量", "is_correct": false, "explanation": "语义：音量指声音的大小，与冰化无关。"}, {"text": "长度", "is_correct": false, "explanation": "搭配：“长度”通常说“越长”，不说“越高”，“长度越高”不成立。"}], "explanations": {"温度": "“温度越高”说明冷热的程度，温度越高冰化得越快，符合语境。", "亮度": "语义：亮度指明暗的程度，与冰化的快慢无关。", "音量": "语义：音量指声音的大小，与冰化无关。", "长度": "搭配：“长度”通常说“越长”，不说“越高”，“长度越高”不成立。"}, "sentence_index": 6, "correct_answer": "温度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这根绳子的温度很长。", "explanation": "这里应该用〈长度〉。温度只说冷热，绳子的长短要用长度，不能说“很长”。"}, {"text": "这袋米的温度很重。", "explanation": "这里应该用〈重量〉。温度只说冷热，东西的轻重要用重量，不能说“很重”。"}, {"text": "这把椅子的温度很矮。", "explanation": "这里应该用〈高度〉。温度只说冷热，椅子的高矮要用高度，不能说“很矮”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1697b85-2e0f-4e53-8d0e-b40ae68bea44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22700, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "早上的温度是十个。", "corrected_sentence": "早上的温度是十度。", "error_description": "“温度”的数值应使用单位“度”，说“十个”是错误的量词，应改为“十度”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1697b85-2e0f-4e53-8d0e-b40ae68bea44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22700, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "温度降了到零下五度。", "corrected_sentence": "温度降到了零下五度。", "error_description": "“降到”是复合动词，“了”应放在“降到”之后，应说“降到了”，不说“降了到”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1697b85-2e0f-4e53-8d0e-b40ae68bea44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
