INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22702, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "两个人或两个东西吵起来或打起来。", "primary_collocate": null, "pronunciation": "chōng tū", "ipa": "tʂʰʊŋ˥ tʰu˧˥", "syllable_count": 2, "sentences": [{"text": "两个孩子之间发生了冲突。", "target_word": "冲突", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们为了钱发生冲突。", "target_word": "冲突", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想和朋友有冲突。", "target_word": "冲突", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师很快解决了两个同学的冲突。", "target_word": "冲突", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次冲突没有人受伤。", "target_word": "冲突", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了避免冲突，他走开了。", "target_word": "冲突", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察到了以后，冲突就结束了。", "target_word": "冲突", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们俩常常因为小事发生冲突。", "target_word": "冲突", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国之间的冲突越来越多。", "target_word": "冲突", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他和邻居的冲突已经很久了。", "target_word": "冲突", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一场冲突", "label": "量词"}, {"form": "一次冲突", "label": "量词"}, {"form": "衝突", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人与人之间发生的争吵或打斗", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13b584fe-81b3-45c5-b43f-c258eb988e16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22702, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "冲突", "is_correct": true, "explanation": "冲突：双方发生争吵或打斗，放在“发生了”后面最合适。"}, {"text": "奇迹", "is_correct": false, "explanation": "语义：奇迹指非常罕见的好事，两个孩子之间不会“发生奇迹”，与语境不符。"}, {"text": "收获", "is_correct": false, "explanation": "搭配：“收获”一般说“有收获”或“得到收获”，不说“发生收获”。"}, {"text": "火灾", "is_correct": false, "explanation": "语义：火灾与两个孩子之间的关系无关，不能说“发生火灾”。"}], "explanations": {"冲突": "冲突：双方发生争吵或打斗，放在“发生了”后面最合适。", "奇迹": "语义：奇迹指非常罕见的好事，两个孩子之间不会“发生奇迹”，与语境不符。", "收获": "搭配：“收获”一般说“有收获”或“得到收获”，不说“发生收获”。", "火灾": "语义：火灾与两个孩子之间的关系无关，不能说“发生火灾”。"}, "sentence_index": 0, "correct_answer": "冲突"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场金融危机对经济造成了很大冲突。", "explanation": "这里应该用〈冲击〉。冲突指双方互相抵触或打斗，不能用来说危机对经济的作用。"}, {"text": "他的冲突很大，常常不考虑后果就行动。", "explanation": "这里应该用〈冲动〉。冲突指双方吵起来或打起来，形容一时情绪激动、不计后果要说“冲动”。"}, {"text": "他把照片拿去冲突了。", "explanation": "这里应该用〈冲洗〉。冲突指双方吵起来或打起来，照片显影要说“冲洗”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd255a78-aea1-4968-8fb6-1b75f37cd5d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22702, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冲突", "is_correct": true, "explanation": "冲突：双方发生争执，警察到了以后，冲突就结束了，符合语境。"}, {"text": "眼镜", "is_correct": false, "explanation": "语义：眼镜是戴在眼睛上的物品，“就结束了”说不通。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：花瓶是盛放花的器物，不能说“就结束了”，与语境不符。"}, {"text": "病情", "is_correct": false, "explanation": "搭配：“病情”一般说“好转”或“恶化”，不说“结束”。"}], "explanations": {"冲突": "冲突：双方发生争执，警察到了以后，冲突就结束了，符合语境。", "眼镜": "语义：眼镜是戴在眼睛上的物品，“就结束了”说不通。", "花瓶": "语义：花瓶是盛放花的器物，不能说“就结束了”，与语境不符。", "病情": "搭配：“病情”一般说“好转”或“恶化”，不说“结束”。"}, "sentence_index": 6, "correct_answer": "冲突"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他摔倒以后，膝盖冲突了一大块。", "explanation": "这里应该用〈擦伤〉。冲突指双方吵起来或打起来，皮肤蹭破要说“擦伤”。"}, {"text": "最后一圈，他开始冲突，超过了前面的选手。", "explanation": "这里应该用〈冲刺〉。冲突指双方吵起来或打起来，最后加速跑要说“冲刺”。"}, {"text": "这条小路的冲突很平，走起来很轻松。", "explanation": "这里应该用〈路面〉。冲突指双方对立，说路的表面平整要用“路面”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd255a78-aea1-4968-8fb6-1b75f37cd5d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22702, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们昨天在路上发生了一冲突。", "corrected_sentence": "他们昨天在路上发生了一场冲突。", "error_description": "“一”后面要接量词，漏掉量词“场”就错了。应说“一场冲突”，“一冲突”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd255a78-aea1-4968-8fb6-1b75f37cd5d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22702, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们从来没有发生了冲突。", "corrected_sentence": "我们从来没有发生过冲突。", "error_description": "“从来没有……过”表示未有过的经历，动词后要用“过”，不用“了”。应说“发生过冲突”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd255a78-aea1-4968-8fb6-1b75f37cd5d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
