INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22710, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf1db7bd-d73c-42f3-a03b-50f946dbbbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22710, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "表示具有某种性质或特点，且比原来更加明显、更强。", "primary_collocate": null, "pronunciation": "gèng jù", "ipa": "kɤŋ˥˩ tɕy˥˩", "syllable_count": 2, "sentences": [{"text": "这次修改后，文章更具力量。", "target_word": "更具", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经过训练，他的声音更具感染力。", "target_word": "更具", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "换了新教练，球队更具战斗力。", "target_word": "更具", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件旧衣服经过改造，更具个性。", "target_word": "更具", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "加了图片以后，报告更具说服力。", "target_word": "更具", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的主持风格更具亲和力，观众很喜欢。", "target_word": "更具", "complexity_tier": "T3", "furigana": "tā de zhǔ chí fēng gé gèng jù qīn hé lì, guān zhòng hěn xǐ huan", "sentence_source": "generated"}, {"text": "这个城市有了新地铁，更具活力。", "target_word": "更具", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他读了很多书，写的文章更具文采。", "target_word": "更具", "complexity_tier": "T3", "furigana": "tā dú le hěn duō shū, xiě de wén zhāng gèng jù wén cǎi", "sentence_source": "generated"}, {"text": "新的规定让这项工作更具意义。", "target_word": "更具", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "换了新的装修风格，房间更具现代感。", "target_word": "更具", "complexity_tier": "T3", "furigana": "huàn le xīn de zhuāng xiū fēng gé, fáng jiān gèng jù xiàn dài gǎn", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "更具：比原来具有得更多、更强", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3dd671e0-53f7-42b7-bb84-bc75686d43c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22710, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "更具", "is_correct": true, "explanation": "正确：“文章更具力量”，“更具”表示比原来更有力量，与句意相合。"}, {"text": "测量", "is_correct": false, "explanation": "搭配：“测量”用于可计量的对象，不说“测量力量”。"}, {"text": "删除", "is_correct": false, "explanation": "语义：“删除力量”与“修改后”的改进之意相反，句意说不通。"}, {"text": "缩短", "is_correct": false, "explanation": "配价：“缩短”要求带长度或时长类的宾语，不能带“力量”。"}], "explanations": {"更具": "正确：“文章更具力量”，“更具”表示比原来更有力量，与句意相合。", "测量": "搭配：“测量”用于可计量的对象，不说“测量力量”。", "删除": "语义：“删除力量”与“修改后”的改进之意相反，句意说不通。", "缩短": "配价：“缩短”要求带长度或时长类的宾语，不能带“力量”。"}, "sentence_index": 0, "correct_answer": "更具"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家店的顾客更具五成。", "explanation": "这里应该用〈增加〉。更具表示比原来更具有某种特点，人数的增多要用“增加”。"}, {"text": "这次训练更具他的成绩。", "explanation": "这里应该用〈提高〉。更具要带性质或力量类的宾语，成绩的上升要用“提高”。"}, {"text": "这次促销更具价格。", "explanation": "这里应该用〈降低〉。价格的下降要用“降低”，“更具”说的是比原来更具有某种性质。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf1db7bd-d73c-42f3-a03b-50f946dbbbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22710, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "更具", "is_correct": true, "explanation": "正确：“这个城市更具活力”，“更具”表示比原来更有活力，与句意相合。"}, {"text": "收割", "is_correct": false, "explanation": "语义：“收割活力”不成立，“收割”只用于庄稼等。"}, {"text": "计算", "is_correct": false, "explanation": "搭配：“计算”要求带可计量的对象，不说“计算活力”。"}, {"text": "切割", "is_correct": false, "explanation": "语义：“切割”针对实体物件，“切割活力”与句意不符。"}], "explanations": {"更具": "正确：“这个城市更具活力”，“更具”表示比原来更有活力，与句意相合。", "收割": "语义：“收割活力”不成立，“收割”只用于庄稼等。", "计算": "搭配：“计算”要求带可计量的对象，不说“计算活力”。", "切割": "语义：“切割”针对实体物件，“切割活力”与句意不符。"}, "sentence_index": 6, "correct_answer": "更具"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "政府更具治安。", "explanation": "这里应该用〈加强〉。治安力度的增强要用“加强”，“更具”说的是比原来更具有某种力量或特点。"}, {"text": "新路修好后，车程更具一半。", "explanation": "这里应该用〈缩短〉。车程的缩减要用“缩短”，“更具”不能带数量短语。"}, {"text": "新设备更具三成的电费。", "explanation": "这里应该用〈节省〉。电费的减少要用“节省”，“更具”说的是具有某种性质或力量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf1db7bd-d73c-42f3-a03b-50f946dbbbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22710, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这首歌换了新编曲，更具了感染力。", "corrected_sentence": "这首歌换了新编曲，更具感染力。", "error_description": "错误：“更具了感染力”；正确：“更具感染力”。“更具”表示具有某种性质，不能带“了”表示完成，直接说“更具感染力”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf1db7bd-d73c-42f3-a03b-50f946dbbbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22710, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座老城改造以后，街区更具的活力。", "corrected_sentence": "这座老城改造以后，街区更具活力。", "error_description": "错误：“更具的活力”；正确：“更具活力”。“更具”是动词，后面直接带宾语，不能加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf1db7bd-d73c-42f3-a03b-50f946dbbbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
