INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22726, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "网是一种东西，人们用它来捕鱼或捉虫子。", "primary_collocate": null, "pronunciation": "wǎng", "ipa": "wɑŋ˨˩˦", "syllable_count": 1, "sentences": [{"text": "孩子拿着网去捉蝴蝶。", "target_word": "网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸用网捞起了池塘里的鱼。", "target_word": "网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天晚上，我们用网捉萤火虫。", "target_word": "网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "渔夫把网拉上船，里面有很多鱼。", "target_word": "网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小男孩举起网，想捉树上的蝉。", "target_word": "网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张网太大，我一个人拿不动。", "target_word": "网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们带着网到河边捉小虾。", "target_word": "网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用一张小网捉住了飞来飞去的虫子。", "target_word": "网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网湿了，要先晒干再收起来。", "target_word": "网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "渔夫每天早上都要检查网。", "target_word": "网", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "網", "label": "繁体"}, {"form": "渔网", "label": "复合"}], "register": "中性", "sense_fingerprint": "用来捕鱼或捉虫子的网具", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T1: 4 words above tier T1 (max 2): 小男孩 (Zipf 3.91), 举起 (Zipf 3.86), 树上 (Zipf 3.82), 蝉 (Zipf 2.83)','sentence 7 above tier T1: 4 words above tier T1 (max 2): 捉住 (Zipf 3.24), 飞来 (Zipf 3.47), 飞去 (Zipf 3.36), 虫子 (Zipf 3.55)']::text[], '35b9a7f4-0ff9-4ffe-8c7b-041a5c756a90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22726, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "网", "is_correct": true, "explanation": "正确。网（wǎng）指用来捕鱼或捉虫子的网具。"}, {"text": "王", "is_correct": false, "explanation": "wáng（第二声）与 wǎng（第三声）声调不同，意思是国王。"}, {"text": "望", "is_correct": false, "explanation": "wàng（第四声）与 wǎng（第三声）声调不同，意思是看、盼望。"}, {"text": "汪", "is_correct": false, "explanation": "wāng（第一声）与 wǎng（第三声）声调不同，意思是水面宽广的样子。"}, {"text": "晚", "is_correct": false, "explanation": "wǎn 与 wǎng 韵母不同（an 与 ang），意思是晚上。"}], "explanations": {"网": "正确。网（wǎng）指用来捕鱼或捉虫子的网具。", "王": "wáng（第二声）与 wǎng（第三声）声调不同，意思是国王。", "望": "wàng（第四声）与 wǎng（第三声）声调不同，意思是看、盼望。", "汪": "wāng（第一声）与 wǎng（第三声）声调不同，意思是水面宽广的样子。", "晚": "wǎn 与 wǎng 韵母不同（an 与 ang），意思是晚上。"}, "sentence_index": null, "correct_answer": "网"}, "level_3": {"options": [{"text": "网", "is_correct": true, "explanation": "正确。捉蝴蝶要用网，“拿着网”符合语境。"}, {"text": "书", "is_correct": false, "explanation": "语义：书不能用来捉蝴蝶，与句子的语境不符。"}, {"text": "球", "is_correct": false, "explanation": "语义：球不是捉蝴蝶的工具，句子说不通。"}, {"text": "水壶", "is_correct": false, "explanation": "搭配：“捉蝴蝶”需要捕捉工具，“拿着水壶去捉”不搭配。"}], "explanations": {"网": "正确。捉蝴蝶要用网，“拿着网”符合语境。", "书": "语义：书不能用来捉蝴蝶，与句子的语境不符。", "球": "语义：球不是捉蝴蝶的工具，句子说不通。", "水壶": "搭配：“捉蝴蝶”需要捕捉工具，“拿着水壶去捉”不搭配。"}, "sentence_index": 0, "correct_answer": "网"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子用网梳头发。", "explanation": "这里应该用〈梳子〉。梳头要用梳子，网是捉虫或捕鱼用的器具，不能用来梳头。"}, {"text": "这张网很暖和，可以盖在身上。", "explanation": "这里应该用〈被子〉。盖在身上保暖要用被子，网是捕捉用的器具，不能用来保暖。"}, {"text": "孩子用网写了一封信。", "explanation": "这里应该用〈笔〉。写信要用笔，网是捉虫或捕鱼用的器具，不能用来写字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da741986-cdb5-45e2-9005-670934ead580') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22726, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "网", "is_correct": true, "explanation": "正确。网（wǎng）指用来捕鱼或捉虫子的网具。"}, {"text": "忘", "is_correct": false, "explanation": "wàng（第四声）与 wǎng（第三声）声调不同，意思是忘记。"}, {"text": "旺", "is_correct": false, "explanation": "wàng（第四声）与 wǎng（第三声）声调不同，意思是旺盛。"}, {"text": "王", "is_correct": false, "explanation": "wáng（第二声）与 wǎng（第三声）声调不同，意思是国王。"}, {"text": "碗", "is_correct": false, "explanation": "wǎn 与 wǎng 韵母不同（an 与 ang），意思是盛饭菜的器皿。"}], "explanations": {"网": "正确。网（wǎng）指用来捕鱼或捉虫子的网具。", "忘": "wàng（第四声）与 wǎng（第三声）声调不同，意思是忘记。", "旺": "wàng（第四声）与 wǎng（第三声）声调不同，意思是旺盛。", "王": "wáng（第二声）与 wǎng（第三声）声调不同，意思是国王。", "碗": "wǎn 与 wǎng 韵母不同（an 与 ang），意思是盛饭菜的器皿。"}, "sentence_index": null, "correct_answer": "网"}, "level_3": {"options": [{"text": "网", "is_correct": true, "explanation": "正确。带着网到河边，才能捉小虾，网是捕捉工具。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子太大，不能拿到河边去捉小虾。"}, {"text": "电视", "is_correct": false, "explanation": "语义：电视不是捉小虾的工具，也不便带到河边。"}, {"text": "词典", "is_correct": false, "explanation": "搭配：“捉小虾”的工具不是词典，“带着词典”不搭配。"}], "explanations": {"网": "正确。带着网到河边，才能捉小虾，网是捕捉工具。", "桌子": "语义：桌子太大，不能拿到河边去捉小虾。", "电视": "语义：电视不是捉小虾的工具，也不便带到河边。", "词典": "搭配：“捉小虾”的工具不是词典，“带着词典”不搭配。"}, "sentence_index": 6, "correct_answer": "网"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子用网切了一块蛋糕。", "explanation": "这里应该用〈刀〉。切蛋糕要用刀，网是捉虫或捕鱼用的器具，不能用来切东西。"}, {"text": "渔夫用网钓鱼。", "explanation": "这里应该用〈鱼竿〉。钓鱼用鱼竿和鱼钩，网是用来撒或拉的器具，不能说“用网钓鱼”。"}, {"text": "渔夫用网扫地。", "explanation": "这里应该用〈扫帚〉。扫地要用扫帚，网是捕捉用的器具，不能用来扫地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da741986-cdb5-45e2-9005-670934ead580') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22726, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子拿着一只网追蝴蝶。", "corrected_sentence": "孩子拿着一张网追蝴蝶。", "error_description": "量词错误：网是片状器具，应用量词“张”。“一只网”错误，应为“一张网”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da741986-cdb5-45e2-9005-670934ead580') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22726, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "渔夫每天都要检查这网。", "corrected_sentence": "渔夫每天都要检查这张网。", "error_description": "量词缺失：“网”是片状器具，指示代词“这”后应加量词“张”。“这网”错误，应为“这张网”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da741986-cdb5-45e2-9005-670934ead580') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22728, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "自愿", "is_correct": true, "explanation": "「自愿」指出于本人意愿去做，与「强制」（迫使必须做）意思相反。"}, {"text": "拒绝", "is_correct": false, "explanation": "「拒绝」表示不接受，与「强制」的反义关系不成立，只是动作上的对立。"}, {"text": "放弃", "is_correct": false, "explanation": "「放弃」表示停止或舍弃，与「强制」没有反义关系。"}, {"text": "参加", "is_correct": false, "explanation": "「参加」表示加入某活动，与「强制」的意思不构成反义关系。"}], "correct_answer": "自愿", "explanations": {"自愿": "「自愿」指出于本人意愿去做，与「强制」（迫使必须做）意思相反。", "拒绝": "「拒绝」表示不接受，与「强制」的反义关系不成立，只是动作上的对立。", "放弃": "「放弃」表示停止或舍弃，与「强制」没有反义关系。", "参加": "「参加」表示加入某活动，与「强制」的意思不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc0cc312-6c8a-4816-81d1-52075941a40b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22728, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "自愿", "is_correct": true, "explanation": "「自愿」指出于本人意愿去做，与「强制」意思相反。"}, {"text": "同意", "is_correct": false, "explanation": "「同意」表示认可或赞成，与「强制」没有反义关系。"}, {"text": "离开", "is_correct": false, "explanation": "「离开」表示离去，与「强制」的意思不构成反义关系。"}, {"text": "等待", "is_correct": false, "explanation": "「等待」表示停留以待，与「强制」没有反义关系。"}], "correct_answer": "自愿", "explanations": {"自愿": "「自愿」指出于本人意愿去做，与「强制」意思相反。", "同意": "「同意」表示认可或赞成，与「强制」没有反义关系。", "离开": "「离开」表示离去，与「强制」的意思不构成反义关系。", "等待": "「等待」表示停留以待，与「强制」没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc0cc312-6c8a-4816-81d1-52075941a40b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22728, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让人必须去做某事，不能不做。", "primary_collocate": null, "pronunciation": "qiáng zhì", "ipa": "tɕʰjɑŋ˧˥ ʈʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "学校不能强制学生买这本书。", "target_word": "强制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师不强制我们每天写日记。", "target_word": "强制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察强制他离开了现场。", "target_word": "强制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司强制所有人周末加班。", "target_word": "强制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父母不应该强制孩子学钢琴。", "target_word": "强制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律强制司机系安全带。", "target_word": "强制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们强制我签下这份文件。", "target_word": "强制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市强制大家把垃圾分类。", "target_word": "强制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习要靠兴趣，不能强制。", "target_word": "强制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校强制大家戴口罩。", "target_word": "强制", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "强制性", "label": "复合"}, {"form": "强制执行", "label": "复合"}], "register": "书面", "sense_fingerprint": "用权力或压力要求人必须做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d813a3-5c7c-4c35-a022-bcb120b67276') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22728, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "强制", "is_correct": true, "explanation": "「强制」（qiángzhì）指用权力或压力要求人必须去做某事，不能不做。"}, {"text": "墙纸", "is_correct": false, "explanation": "「墙纸」（qiángzhǐ）与「强制」的第二个音节声调不同，意思是贴在墙上的装饰纸。"}, {"text": "枪支", "is_correct": false, "explanation": "「枪支」（qiāngzhī）与「强制」两个音节的声调都不同，意思是枪械。"}, {"text": "潜质", "is_correct": false, "explanation": "「潜质」（qiánzhì）与「强制」第一个音节的韵尾 n 与 ng 不同，意思是潜在的能力。"}, {"text": "强直", "is_correct": false, "explanation": "「强直」（qiángzhí）与「强制」的第二个音节声调不同，意思是肌肉或关节僵硬。"}], "explanations": {"强制": "「强制」（qiángzhì）指用权力或压力要求人必须去做某事，不能不做。", "墙纸": "「墙纸」（qiángzhǐ）与「强制」的第二个音节声调不同，意思是贴在墙上的装饰纸。", "枪支": "「枪支」（qiāngzhī）与「强制」两个音节的声调都不同，意思是枪械。", "潜质": "「潜质」（qiánzhì）与「强制」第一个音节的韵尾 n 与 ng 不同，意思是潜在的能力。", "强直": "「强直」（qiángzhí）与「强制」的第二个音节声调不同，意思是肌肉或关节僵硬。"}, "sentence_index": null, "correct_answer": "强制"}, "level_3": {"options": [{"text": "强制", "is_correct": true, "explanation": "「强制」表示学校用权力要求学生买书，符合句意。"}, {"text": "录取", "is_correct": false, "explanation": "语义：「录取」指接收入学或入职，与「买这本书」无关。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：「参观」的对象是地方或展品，不能带「学生买书」这样的动作宾语。"}, {"text": "签订", "is_correct": false, "explanation": "搭配：「签订」的对象是合同或协议，不能用于「学生买书」。"}], "explanations": {"强制": "「强制」表示学校用权力要求学生买书，符合句意。", "录取": "语义：「录取」指接收入学或入职，与「买这本书」无关。", "参观": "搭配：「参观」的对象是地方或展品，不能带「学生买书」这样的动作宾语。", "签订": "搭配：「签订」的对象是合同或协议，不能用于「学生买书」。"}, "sentence_index": 0, "correct_answer": "强制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他强制长高了一厘米。", "explanation": "这里应该用〈生长〉。「强制」表示迫使别人去做，身高增长是自然过程，不能被强制。"}, {"text": "他强制地爱上了那首歌。", "explanation": "这里应该用〈喜欢〉。「强制」指迫使对方去做某事，爱慕之情不能被强制。"}, {"text": "我们强制欢迎大家来参加。", "explanation": "这里应该用〈邀请〉。「强制」表示迫使对方去做，欢迎是表示善意的接待，不能被强制。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc0cc312-6c8a-4816-81d1-52075941a40b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22728, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "强制", "is_correct": true, "explanation": "「强制」表示他们用权力迫使我签文件，符合句意。"}, {"text": "祝贺", "is_correct": false, "explanation": "语义：「祝贺」表示庆贺，与被迫签文件的语境不符"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：「欣赏」表示赞美或喜爱，与「签下文件」这种被迫行为不符。"}, {"text": "迎接", "is_correct": false, "explanation": "语义：「迎接」表示到来时接待，与「签下这份文件」的动作不搭。"}], "explanations": {"强制": "「强制」表示他们用权力迫使我签文件，符合句意。", "祝贺": "语义：「祝贺」表示庆贺，与被迫签文件的语境不符", "欣赏": "语义：「欣赏」表示赞美或喜爱，与「签下文件」这种被迫行为不符。", "迎接": "语义：「迎接」表示到来时接待，与「签下这份文件」的动作不搭。"}, "sentence_index": 6, "correct_answer": "强制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师强制地强调了这个问题。", "explanation": "这里应该用〈着重〉。「强制」表示迫使别人去做，不能用来表示突出重点。"}, {"text": "政府强制了新的法律。", "explanation": "这里应该用〈制定〉。「强制」指迫使人去做，不能用来指订立法律。"}, {"text": "他强制地解释了这道题。", "explanation": "这里应该用〈讲解〉。「强制」表示迫使别人去做，不能用来形容讲解题目这类说明行为。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc0cc312-6c8a-4816-81d1-52075941a40b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22728, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校很强制学生买这本书。", "corrected_sentence": "学校强制学生买这本书。", "error_description": "错误：「强制」是动词，不能受程度副词「很」修饰。正确：去掉「很」，应为「学校强制学生买这本书」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc0cc312-6c8a-4816-81d1-52075941a40b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22728, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校被强制新生参加军训。", "corrected_sentence": "学校强制新生参加军训。", "error_description": "错误：「被」字句的主语「学校」已是受事，「强制」后却又带了宾语「新生」，结构重复。正确：应直接用「学校强制新生参加军训」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc0cc312-6c8a-4816-81d1-52075941a40b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
