INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22730, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "一起活着，不打架。", "primary_collocate": null, "pronunciation": "gòng cún", "ipa": "kʊŋ˥˩ tsʰwən˧˥", "syllable_count": 2, "sentences": [{"text": "猫和狗在一个家里共存。", "target_word": "共存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个国家要和平共存。", "target_word": "共存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鱼和虾在池塘里共存。", "target_word": "共存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们和邻居共存了很多年。", "target_word": "共存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不同的人要学会共存。", "target_word": "共存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的鸟和松鼠共存得很好。", "target_word": "共存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "狮子和羊不能共存。", "target_word": "共存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的狼和鹿以前没有共存过。", "target_word": "共存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人和年轻人可以在社区里共存。", "target_word": "共存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟和小猫在院子里共存了一个夏天。", "target_word": "共存", "complexity_tier": "T3", "furigana": "gòng cún", "sentence_source": "generated"}], "morphological_forms": [{"form": "共存了", "label": "体标"}, {"form": "共存过", "label": "体标"}, {"form": "和平共存", "label": "复合"}], "register": "中性", "sense_fingerprint": "人或动物一起生活，互不争斗", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9da955b2-9cb2-4719-95b9-57d75913c78c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22730, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "共存", "is_correct": true, "explanation": "共存指一起生活、互不争斗，与“猫和狗在一个家里”的语境相合。"}, {"text": "寄存", "is_correct": false, "explanation": "搭配：“寄存”的对象是行李或物品，不能用于猫和狗。"}, {"text": "缝补", "is_correct": false, "explanation": "语义：缝补指用针线修补衣物，与猫和狗无关。"}, {"text": "烧制", "is_correct": false, "explanation": "语义：烧制指用火加工陶瓷，与猫和狗在家里的情况不符。"}], "explanations": {"共存": "共存指一起生活、互不争斗，与“猫和狗在一个家里”的语境相合。", "寄存": "搭配：“寄存”的对象是行李或物品，不能用于猫和狗。", "缝补": "语义：缝补指用针线修补衣物，与猫和狗无关。", "烧制": "语义：烧制指用火加工陶瓷，与猫和狗在家里的情况不符。"}, "sentence_index": 0, "correct_answer": "共存"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我和爷爷共存去了公园。", "explanation": "这里应该用〈同行〉。共存指彼此并存，不能表示结伴同去某地。"}, {"text": "两人共存走进了房间。", "explanation": "这里应该用〈同时〉。共存指多者并存，不能修饰“走进”这一动作。"}, {"text": "两个班级共存完成了一个项目。", "explanation": "这里应该用〈合作〉。共存指并存，不能表示一起完成任务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07a69b8-3c46-4b8c-98d3-4ca5164bc3a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22730, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "共存", "is_correct": true, "explanation": "“狮子和羊不能共存”指两者不能一起生活、互不争斗，与语境相合。"}, {"text": "装订", "is_correct": false, "explanation": "语义：装订指把纸张装成册，不能用于狮子和羊。"}, {"text": "打印", "is_correct": false, "explanation": "搭配：“打印”的对象是文件，不能用于动物。"}, {"text": "发酵", "is_correct": false, "explanation": "语义：发酵指微生物使食物发生变化，与狮子和羊的关系无关。"}], "explanations": {"共存": "“狮子和羊不能共存”指两者不能一起生活、互不争斗，与语境相合。", "装订": "语义：装订指把纸张装成册，不能用于狮子和羊。", "打印": "搭配：“打印”的对象是文件，不能用于动物。", "发酵": "语义：发酵指微生物使食物发生变化，与狮子和羊的关系无关。"}, "sentence_index": 6, "correct_answer": "共存"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场比赛共存了两个小时。", "explanation": "这里应该用〈持续〉。共存指多者同时并存，不表示时间延续。"}, {"text": "他共存走出了教室。", "explanation": "这里应该用〈立刻〉。共存指并存，不能表示动作马上发生。"}, {"text": "他共存检查了作业。", "explanation": "这里应该用〈反复〉。共存指并存，不能表示多次检查。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07a69b8-3c46-4b8c-98d3-4ca5164bc3a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22730, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两只猫在一个屋子里能把和睦共存。", "corrected_sentence": "这两只猫在一个屋子里能和睦共存。", "error_description": "句法错误：「共存」是不及物动词，不能用「把」字句；去掉「把」，写作「能和睦共存」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07a69b8-3c46-4b8c-98d3-4ca5164bc3a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22730, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们两家人曾经在这条街上共存着。", "corrected_sentence": "我们两家人曾经在这条街上共存过。", "error_description": "表示经历的助词应为“过”，写作“共存过”；“着”表示持续，与“曾经”的经历语境冲突。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07a69b8-3c46-4b8c-98d3-4ca5164bc3a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22732, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "愚蠢", "is_correct": true, "explanation": "正确：“愚蠢”与“智慧”意思相反，指不懂道理、判断糊涂。"}, {"text": "勤劳", "is_correct": false, "explanation": "“勤劳”指肯干、不怕辛苦，与“智慧”不是反义关系。"}, {"text": "善良", "is_correct": false, "explanation": "“善良”指心地好，说的是品性，与“智慧”不构成反义关系。"}, {"text": "热情", "is_correct": false, "explanation": "“热情”指待人友好、积极，与“智慧”不是一组对立的词。"}], "correct_answer": "愚蠢", "explanations": {"愚蠢": "正确：“愚蠢”与“智慧”意思相反，指不懂道理、判断糊涂。", "勤劳": "“勤劳”指肯干、不怕辛苦，与“智慧”不是反义关系。", "善良": "“善良”指心地好，说的是品性，与“智慧”不构成反义关系。", "热情": "“热情”指待人友好、积极，与“智慧”不是一组对立的词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cfe41c9-c431-47c5-a836-2c5ec2a19f1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22732, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "愚蠢", "is_correct": true, "explanation": "正确：“愚蠢”与“智慧”意思相反，指不懂道理、判断糊涂。"}, {"text": "诚实", "is_correct": false, "explanation": "“诚实”指不说假话、不欺骗，与“智慧”不是反义关系。"}, {"text": "大方", "is_correct": false, "explanation": "“大方”指不吝啬，说的是待人接物的态度，与“智慧”无反义关系。"}, {"text": "礼貌", "is_correct": false, "explanation": "“礼貌”指待人有礼节，与“智慧”不构成一组对立的词。"}], "correct_answer": "愚蠢", "explanations": {"愚蠢": "正确：“愚蠢”与“智慧”意思相反，指不懂道理、判断糊涂。", "诚实": "“诚实”指不说假话、不欺骗，与“智慧”不是反义关系。", "大方": "“大方”指不吝啬，说的是待人接物的态度，与“智慧”无反义关系。", "礼貌": "“礼貌”指待人有礼节，与“智慧”不构成一组对立的词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cfe41c9-c431-47c5-a836-2c5ec2a19f1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22732, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "知道怎么做对的事情，很聪明。", "primary_collocate": null, "pronunciation": "zhì huì", "ipa": "tʂɨ˥˩ xwei˥˩", "syllable_count": 2, "sentences": [{"text": "爷爷很有智慧，大家都爱听他的话。", "target_word": "智慧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法让我看到了她的智慧。", "target_word": "智慧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "读书可以让人增长智慧。", "target_word": "智慧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人的智慧来自一生的经验。", "target_word": "智慧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用智慧解决了这个难题。", "target_word": "智慧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书里有很多古人的智慧。", "target_word": "智慧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不但漂亮，而且很有智慧。", "target_word": "智慧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们的智慧常常让大人吃惊。", "target_word": "智慧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要靠大家的智慧做好这件事。", "target_word": "智慧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是个有智慧的人，从不乱发脾气。", "target_word": "智慧", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "智慧：知道怎样做对的事，聪明而有见识的能力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d3283c2-c3c9-456b-a54d-b3cbf61747b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22732, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "心机", "is_correct": false, "explanation": "语义：“心机”指算计、盘算，与后句“大家都爱听他的话”所表达的敬重语气相反。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”说的是体形外貌，与前句要夸的智慧品质不相符。"}, {"text": "耳朵", "is_correct": false, "explanation": "搭配：“耳朵”是身体部位，不能用“很有”来修饰，句意不通。"}, {"text": "智慧", "is_correct": true, "explanation": "“智慧”指懂得处事的道理、判断得当，与句中对爷爷的夸奖相符。"}], "explanations": {"心机": "语义：“心机”指算计、盘算，与后句“大家都爱听他的话”所表达的敬重语气相反。", "身材": "体貌：“身材”说的是体形外貌，与前句要夸的智慧品质不相符。", "耳朵": "搭配：“耳朵”是身体部位，不能用“很有”来修饰，句意不通。", "智慧": "“智慧”指懂得处事的道理、判断得当，与句中对爷爷的夸奖相符。"}, "sentence_index": 0, "correct_answer": "智慧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个运动员的智慧很强，一口气能跑完一百公里。", "explanation": "这里应该用〈体力〉。跑完一百公里靠耐力，要说体力；智慧指判断和处事的能力，不决定耐力。"}, {"text": "他的智慧很大，一下子扛起了两百斤的米袋。", "explanation": "这里应该用〈力气〉。扛米袋靠体力，要用力气；智慧指判断和处事的能力，不能用“大”来形容体力。"}, {"text": "他的智慧很好，一年到头都没生过病。", "explanation": "这里应该用〈身体〉。说身体强健、不生病要用身体；智慧指判断和处事的能力，不指身体状况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cfe41c9-c431-47c5-a836-2c5ec2a19f1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22732, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "缺点", "is_correct": false, "explanation": "语义：“很有缺点”与前句“不但漂亮”的褒扬递进相矛盾。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“有身高”不这样说，描述个子高矮应说“个子高”。"}, {"text": "怨气", "is_correct": false, "explanation": "语义：“很有怨气”与“而且”引出的夸奖语气相反，句意不通。"}, {"text": "智慧", "is_correct": true, "explanation": "“智慧”指聪明而有见识，与“不但漂亮，而且”的褒扬语气相符。"}], "explanations": {"缺点": "语义：“很有缺点”与前句“不但漂亮”的褒扬递进相矛盾。", "身高": "搭配：“有身高”不这样说，描述个子高矮应说“个子高”。", "怨气": "语义：“很有怨气”与“而且”引出的夸奖语气相反，句意不通。", "智慧": "“智慧”指聪明而有见识，与“不但漂亮，而且”的褒扬语气相符。"}, "sentence_index": 6, "correct_answer": "智慧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的智慧很广，去过五十多个国家。", "explanation": "这里应该用〈见识〉。见识是所见所闻的积累，可以说“见识广”；智慧指判断和处事的能力，不说“广”。"}, {"text": "他的智慧很精湛，木雕做得人人夸。", "explanation": "这里应该用〈手艺〉。“精湛”形容技艺，木雕靠手艺；智慧指判断和处事的能力，不说“精湛”。"}, {"text": "他的智慧很帅，走在路上很多人回头看。", "explanation": "这里应该用〈外貌〉。“帅”形容相貌，要用外貌；智慧指判断和处事的能力，不指长相。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cfe41c9-c431-47c5-a836-2c5ec2a19f1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22732, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把智慧需要长时间积累。", "corrected_sentence": "这种智慧需要长时间积累。", "error_description": "量词错误：“智慧”是抽象名词，应用量词“种”，说“这种智慧”；“把”用于有柄的器具，不能用来修饰“智慧”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cfe41c9-c431-47c5-a836-2c5ec2a19f1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22732, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位老奶奶是智慧，遇事总能想出好办法。", "corrected_sentence": "这位老奶奶有智慧，遇事总能想出好办法。", "error_description": "动词误用：表示具有智慧要用“有”，说“有智慧”；“是”不能直接接“智慧”，说“是智慧”不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cfe41c9-c431-47c5-a836-2c5ec2a19f1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
