INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22734, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "action", "definition": "一种节奏轻快的拉丁舞蹈。", "primary_collocate": null, "pronunciation": "qià qià", "ipa": "tɕʰja˥˩ tɕʰja˥˩", "syllable_count": 2, "sentences": [{"text": "周末我和朋友一起学跳恰恰。", "target_word": "恰恰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她跳恰恰时，转了一圈又一圈。", "target_word": "恰恰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "恰恰的音乐很快，大家都跟着转圈。", "target_word": "恰恰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们怎么跳恰恰的转圈动作。", "target_word": "恰恰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他跳恰恰很快地转了一圈，大家都鼓掌。", "target_word": "恰恰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚会上，他们跳了一支恰恰。", "target_word": "恰恰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不会跳恰恰，只会跳慢舞。", "target_word": "恰恰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "跳恰恰要跟着音乐的节奏转圈。", "target_word": "恰恰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶年轻时最爱跳恰恰。", "target_word": "恰恰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "音乐一响，大家就开始跳恰恰。", "target_word": "恰恰", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "恰恰舞", "label": "复合"}], "register": "中性", "sense_fingerprint": "恰恰：一种节奏轻快的拉丁舞名", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '739f0140-8cbc-457e-8526-f10ae4204bc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22734, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "恰恰", "is_correct": true, "explanation": "正确：“学跳恰恰”指学习恰恰舞，“恰恰”是舞名。"}, {"text": "跳蚤", "is_correct": false, "explanation": "语义：“跳蚤”指一种小虫，与舞蹈无关，“学跳跳蚤”不成义。"}, {"text": "跳槽", "is_correct": false, "explanation": "搭配：“跳槽”是动词，不能作“跳”的宾语。"}, {"text": "跳票", "is_correct": false, "explanation": "语义：“跳票”指失约或支票无法兑现，与学习舞蹈无关。"}], "explanations": {"恰恰": "正确：“学跳恰恰”指学习恰恰舞，“恰恰”是舞名。", "跳蚤": "语义：“跳蚤”指一种小虫，与舞蹈无关，“学跳跳蚤”不成义。", "跳槽": "搭配：“跳槽”是动词，不能作“跳”的宾语。", "跳票": "语义：“跳票”指失约或支票无法兑现，与学习舞蹈无关。"}, "sentence_index": 0, "correct_answer": "恰恰"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师教我们怎么吃恰恰的转圈动作。", "explanation": "这里应该用〈跳〉。恰恰是舞蹈，要说“跳恰恰”，不说“吃恰恰”。"}, {"text": "老师教了我们一张恰恰。", "explanation": "这里应该用〈支〉。舞蹈作量词时用“支”，不用“张”。"}, {"text": "我们班的同学都会唱恰恰。", "explanation": "这里应该用〈跳〉。恰恰是舞蹈，要说“跳恰恰”，不说“唱恰恰”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fc5df72-7a7d-450b-9fca-b65c9e8b5d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22734, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "恰恰", "is_correct": true, "explanation": "正确：“我不会跳恰恰，只会跳慢舞”中，“恰恰”指舞蹈名，与“慢舞”形成对比。"}, {"text": "跳板", "is_correct": false, "explanation": "语义：“跳板”指跳水时踏的板子，不是舞蹈，“我不会跳板”不成义。"}, {"text": "跳棋", "is_correct": false, "explanation": "搭配：“跳棋”是游戏名，要说“下跳棋”，不能直接与“跳”搭配。"}, {"text": "跳线", "is_correct": false, "explanation": "语义：“跳线”指电路中的连接线，与舞蹈无关。"}], "explanations": {"恰恰": "正确：“我不会跳恰恰，只会跳慢舞”中，“恰恰”指舞蹈名，与“慢舞”形成对比。", "跳板": "语义：“跳板”指跳水时踏的板子，不是舞蹈，“我不会跳板”不成义。", "跳棋": "搭配：“跳棋”是游戏名，要说“下跳棋”，不能直接与“跳”搭配。", "跳线": "语义：“跳线”指电路中的连接线，与舞蹈无关。"}, "sentence_index": 6, "correct_answer": "恰恰"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "音乐一响，大家就开始写恰恰。", "explanation": "这里应该用〈跳〉。恰恰是舞蹈，要说“跳恰恰”，不说“写恰恰”。"}, {"text": "音乐一响，大家就开始喝恰恰。", "explanation": "这里应该用〈跳〉。恰恰是舞蹈，要说“跳恰恰”，不说“喝恰恰”。"}, {"text": "音乐一响，大家就开始跳一位恰恰。", "explanation": "这里应该用〈支〉。舞蹈作量词时用“支”，不用“位”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fc5df72-7a7d-450b-9fca-b65c9e8b5d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22734, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个周末我们跳了一颗恰恰。", "corrected_sentence": "这个周末我们跳了一支恰恰。", "error_description": "错误：“一颗恰恰”，“颗”用于粒状物，不用于舞蹈；正确：“一支恰恰”，恰恰作舞蹈名时量词用“支”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fc5df72-7a7d-450b-9fca-b65c9e8b5d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22734, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几年她一直很喜欢跳了恰恰。", "corrected_sentence": "这几年她一直很喜欢跳恰恰。", "error_description": "错误：“跳了恰恰”，“了”表示动作已完成，与表示习惯爱好的“一直很喜欢”冲突；应说“喜欢跳恰恰”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fc5df72-7a7d-450b-9fca-b65c9e8b5d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
