INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22736, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让小朋友学习新东西，慢慢长大。", "primary_collocate": null, "pronunciation": "péi yǎng", "ipa": "pʰeɪ˧˥ jɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "妈妈每天培养孩子读书的习惯。", "target_word": "培养", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸想培养儿子对音乐的兴趣。", "target_word": "培养", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师培养小朋友们爱干净的习惯。", "target_word": "培养", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们从小就培养女儿画画。", "target_word": "培养", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要培养孩子自己整理书包的能力。", "target_word": "培养", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷培养了三个孩子，他们都上了大学。", "target_word": "培养", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校培养学生，也注重他们的好品德。", "target_word": "培养", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "培养一个孩子需要很多时间。", "target_word": "培养", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她想把孩子培养成一个快乐的人。", "target_word": "培养", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶培养着小孙子的好习惯。", "target_word": "培养", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "培养了", "label": "体标"}, {"form": "培养着", "label": "体标"}, {"form": "培养过", "label": "体标"}, {"form": "培養", "label": "繁体"}], "register": "中性", "sense_fingerprint": "让孩子学习新东西，慢慢长大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35b9a7f4-0ff9-4ffe-8c7b-041a5c756a90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22736, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”用于场所、物品，不能用于习惯。"}, {"text": "摧毁", "is_correct": false, "explanation": "语义：“摧毁”与“每天”督促孩子形成习惯的做法相反，句意矛盾。"}, {"text": "培养", "is_correct": true, "explanation": "“培养”指让孩子通过长期练习形成习惯，与“孩子读书的习惯”搭配。"}, {"text": "删除", "is_correct": false, "explanation": "搭配：“删除”用于文件、数据，不能用于习惯。"}], "explanations": {"打扫": "搭配：“打扫”用于场所、物品，不能用于习惯。", "摧毁": "语义：“摧毁”与“每天”督促孩子形成习惯的做法相反，句意矛盾。", "培养": "“培养”指让孩子通过长期练习形成习惯，与“孩子读书的习惯”搭配。", "删除": "搭配：“删除”用于文件、数据，不能用于习惯。"}, "sentence_index": 0, "correct_answer": "培养"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工厂培养了很多衣服。", "explanation": "这里应该用〈生产〉。培养用于人的能力、习惯，不用于产品。"}, {"text": "他培养了老爷爷的旧钟。", "explanation": "这里应该用〈修理〉。培养的对象是人，不用于器物。"}, {"text": "他每天培养身体，身体越来越结实。", "explanation": "这里应该用〈锻炼〉。培养指让人学习新东西、慢慢长大，锻炼身体要说锻炼，不说培养。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da741986-cdb5-45e2-9005-670934ead580') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22736, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "驱逐", "is_correct": false, "explanation": "语义：“驱逐”是赶走，与学校教育学生的目的相反，句意矛盾。"}, {"text": "安装", "is_correct": false, "explanation": "搭配：“安装”用于设备、程序，不能说安装学生。"}, {"text": "培养", "is_correct": true, "explanation": "“培养”指使学生的能力、品德逐步形成，与“学校培养学生”的语境相符。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”与学校教育学生的意图不符，句意矛盾。"}], "explanations": {"驱逐": "语义：“驱逐”是赶走，与学校教育学生的目的相反，句意矛盾。", "安装": "搭配：“安装”用于设备、程序，不能说安装学生。", "培养": "“培养”指使学生的能力、品德逐步形成，与“学校培养学生”的语境相符。", "嘲笑": "语义：“嘲笑”与学校教育学生的意图不符，句意矛盾。"}, "sentence_index": 6, "correct_answer": "培养"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人培养了一座大桥。", "explanation": "这里应该用〈建造〉。培养不用于建筑、工程。"}, {"text": "警察培养了那起案件。", "explanation": "这里应该用〈调查〉。培养的对象是人，不用于案件。"}, {"text": "技术员培养了一台电脑。", "explanation": "这里应该用〈组装〉。培养不用于机器、设备。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da741986-cdb5-45e2-9005-670934ead580') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22736, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈把女儿培养了一名歌手。", "corrected_sentence": "妈妈把女儿培养成了一名歌手。", "error_description": "“培养”后缺少补语“成”，“把……培养成……”不能省略“成”，应写作“培养成了一名歌手”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da741986-cdb5-45e2-9005-670934ead580') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22736, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "爷爷培养了出三个好学生。", "corrected_sentence": "爷爷培养出了三个好学生。", "error_description": "“培养出”是动补结构，“了”应放在“出”后，写作“培养出了”，不能写成“培养了出”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da741986-cdb5-45e2-9005-670934ead580') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
