INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22738, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指像水一样流动的时间。", "primary_collocate": null, "pronunciation": "shí liú", "ipa": "ʂɻ̩˧˥ ljoʊ˧˥", "syllable_count": 2, "sentences": [{"text": "河边的钟声里，时流好像慢了下来。", "target_word": "时流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "时流带走了童年，也留下了笑声。", "target_word": "时流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子长大了，我才感到时流真快。", "target_word": "时流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她站在桥上，看着水，想到了时流。", "target_word": "时流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时流向前走，没有人能让它停下。", "target_word": "时流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想在老照片里找回逝去的时流。", "target_word": "时流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夜里很安静，能听到时流的脚步。", "target_word": "时流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这幅画画的是河水，也是时流。", "target_word": "时流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "时流无声，我们却都能感到它。", "target_word": "时流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "人们总说时流太快，其实是自己太忙。", "target_word": "时流", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "文学", "sense_fingerprint": "时流：像水一样流动的时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3dd671e0-53f7-42b7-bb84-bc75686d43c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22738, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "时流", "is_correct": true, "explanation": "时流 shí liú：像水一样流动的时间，是本题的答案。"}, {"text": "石榴", "is_correct": false, "explanation": "石榴 shíliu：第二个音节是轻声，与 liú（阳平）声调不同，意思是一种水果。"}, {"text": "十六", "is_correct": false, "explanation": "十六 shíliù：第二个音节是去声，与 liú（阳平）声调不同，意思是数字十六。"}, {"text": "直流", "is_correct": false, "explanation": "直流 zhí liú：声母是 zh，与 shí 的 sh 不同（声调相同），意思是直流电。"}], "explanations": {"时流": "时流 shí liú：像水一样流动的时间，是本题的答案。", "石榴": "石榴 shíliu：第二个音节是轻声，与 liú（阳平）声调不同，意思是一种水果。", "十六": "十六 shíliù：第二个音节是去声，与 liú（阳平）声调不同，意思是数字十六。", "直流": "直流 zhí liú：声母是 zh，与 shí 的 sh 不同（声调相同），意思是直流电。"}, "sentence_index": null, "correct_answer": "时流"}, "level_3": {"options": [{"text": "时流", "is_correct": true, "explanation": "时流：像水一样流动的时间，“慢下来”正合句中的时间感受。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是静物，没有“慢下来”的运动，与钟声的意境不相合。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不会“慢下来”，这个动作只能用于时间或运动的主体。"}, {"text": "杯子", "is_correct": false, "explanation": "搭配：“杯子慢了下来”搭配不当，“慢”一般不用来修饰器物。"}], "explanations": {"时流": "时流：像水一样流动的时间，“慢下来”正合句中的时间感受。", "石头": "语义：石头是静物，没有“慢下来”的运动，与钟声的意境不相合。", "桌子": "语义：桌子不会“慢下来”，这个动作只能用于时间或运动的主体。", "杯子": "搭配：“杯子慢了下来”搭配不当，“慢”一般不用来修饰器物。"}, "sentence_index": 0, "correct_answer": "时流"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条小溪的时流很急。", "explanation": "这里应该用〈水流〉。时流指像水一样流动的时间，不指溪水的流动；形容溪水湍急，要用“水流”。"}, {"text": "她很会合理分配时流。", "explanation": "这里应该用〈时间〉。“合理分配”的对象是时间、精力等可以安排的东西；时流强调时间像水一样流动，不作可以分配的对象。"}, {"text": "我在老屋里度过了整个童年的时流。", "explanation": "这里应该用〈时光〉。“度过”后接的是时光、岁月，时流强调时间像水一样流动，不宜作为可以度过的时段。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf1db7bd-d73c-42f3-a03b-50f946dbbbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22738, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "时流", "is_correct": true, "explanation": "时流：像水一样流动的时间，指时光悄然前行，符合“夜里能听到”的意境。"}, {"text": "桌椅", "is_correct": false, "explanation": "语义：桌椅没有脚步，也不会“走”，与“听到的脚步”不相合。"}, {"text": "灯泡", "is_correct": false, "explanation": "搭配：“灯泡的脚步”不成立，灯泡不会移动。"}, {"text": "瓷碗", "is_correct": false, "explanation": "语义：瓷碗是静物，不会发出“脚步”，与夜里安静的意境相冲突。"}], "explanations": {"时流": "时流：像水一样流动的时间，指时光悄然前行，符合“夜里能听到”的意境。", "桌椅": "语义：桌椅没有脚步，也不会“走”，与“听到的脚步”不相合。", "灯泡": "搭配：“灯泡的脚步”不成立，灯泡不会移动。", "瓷碗": "语义：瓷碗是静物，不会发出“脚步”，与夜里安静的意境相冲突。"}, "sentence_index": 6, "correct_answer": "时流"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们要抓紧时流学习。", "explanation": "这里应该用〈时间〉。“抓紧”一般搭配时间、机会，时流是流动的时间本身，不能被抓紧。"}, {"text": "他很珍惜时流，从不浪费一分一秒。", "explanation": "这里应该用〈光阴〉。人们说“珍惜光阴”，时流强调流动，不宜作为“珍惜”的对象。"}, {"text": "他虚度了大好的时流。", "explanation": "这里应该用〈年华〉。“虚度”后接年华、光阴，时流是流动的时间本身，不作可以虚度的时段。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf1db7bd-d73c-42f3-a03b-50f946dbbbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22738, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "回想起来，一只时流已经带走了许多旧事。", "corrected_sentence": "回想起来，时流已经带走了许多旧事。", "error_description": "错误：“一只时流”。时流是抽象的流动，不能用“只”（多用于动物或单件物品）计量。正确说法是去掉量词，或用“一股时流”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf1db7bd-d73c-42f3-a03b-50f946dbbbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22738, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "时流过的真快，我们要珍惜每一天。", "corrected_sentence": "时流过得真快，我们要珍惜每一天。", "error_description": "错误：“过的真快”。“过”后的补语要用“得”连接，不用“的”。正确说法是“过得真快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf1db7bd-d73c-42f3-a03b-50f946dbbbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
