INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22744, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "嘴巴张开，吸一口气，再呼出来。", "primary_collocate": null, "pronunciation": "dǎ hā qian", "ipa": "ta²¹⁴ xa⁵⁵ tɕʰjɛn⁰", "syllable_count": 3, "sentences": [{"text": "他一上课就打哈欠。", "target_word": "打哈欠", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "昨晚没睡好，我一直打哈欠。", "target_word": "打哈欠", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看到别人打哈欠，我也想打哈欠。", "target_word": "打哈欠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子困了，开始打哈欠。", "target_word": "打哈欠", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "会议太长，大家都在打哈欠。", "target_word": "打哈欠", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一边打哈欠，一边看书。", "target_word": "打哈欠", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小猫睡醒以后打哈欠。", "target_word": "打哈欠", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师讲得很有意思，没有人打哈欠。", "target_word": "打哈欠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你为什么总是打哈欠？", "target_word": "打哈欠", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸下班回来，一直打哈欠。", "target_word": "打哈欠", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "打了哈欠", "label": "体标"}, {"form": "打个哈欠", "label": "离合形式"}], "register": "口语", "sense_fingerprint": "困或累时张嘴深吸气再呼出", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd8ccd27-d9af-45a9-8d08-de0015174fd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22744, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "打哈欠", "is_correct": true, "explanation": "正确：打哈欠是困倦时张口深吸气，符合“一上课就”的语境。"}, {"text": "下班", "is_correct": false, "explanation": "语义：下班指工作结束后离开，与“一上课”的时间相冲突。"}, {"text": "修改", "is_correct": false, "explanation": "配价：修改是及物动词，要带宾语，不能单独作谓语。"}, {"text": "莅临", "is_correct": false, "explanation": "语域：莅临是书面敬辞，不能用于口语中描述学生的日常行为。"}], "explanations": {"打哈欠": "正确：打哈欠是困倦时张口深吸气，符合“一上课就”的语境。", "下班": "语义：下班指工作结束后离开，与“一上课”的时间相冲突。", "修改": "配价：修改是及物动词，要带宾语，不能单独作谓语。", "莅临": "语域：莅临是书面敬辞，不能用于口语中描述学生的日常行为。"}, "sentence_index": 0, "correct_answer": "打哈欠"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "灰尘吸进鼻子里，他一直打哈欠。", "explanation": "这里应该用〈打喷嚏〉。灰尘刺激鼻腔要打喷嚏，打哈欠是困倦时张口吸气，与鼻腔刺激无关。"}, {"text": "这场比赛太精彩了，观众都在打哈欠。", "explanation": "这里应该用〈欢呼〉。精彩的比赛会让观众欢呼，打哈欠表示困倦，不能用来形容观众在精彩比赛中的反应。"}, {"text": "她被烫到手，猛地打了个哈欠。", "explanation": "这里应该用〈缩手〉。烫到手要缩手，打哈欠表示困倦，与疼痛反应无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee911bcc-5f51-4212-b250-ee73f2686fed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22744, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打哈欠", "is_correct": true, "explanation": "正确：小猫睡醒后会张嘴打哈欠，符合“睡醒以后”的语境。"}, {"text": "投票", "is_correct": false, "explanation": "语义：投票需要有选举权的人，小猫不能投票。"}, {"text": "参观", "is_correct": false, "explanation": "配价：参观需要宾语，要说“参观什么”，不能单独作谓语。"}, {"text": "发言", "is_correct": false, "explanation": "语义：发言指在会议等场合表达意见，小猫睡醒后不会发言。"}], "explanations": {"打哈欠": "正确：小猫睡醒后会张嘴打哈欠，符合“睡醒以后”的语境。", "投票": "语义：投票需要有选举权的人，小猫不能投票。", "参观": "配价：参观需要宾语，要说“参观什么”，不能单独作谓语。", "发言": "语义：发言指在会议等场合表达意见，小猫睡醒后不会发言。"}, "sentence_index": 6, "correct_answer": "打哈欠"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他喉咙里有痰，一直打哈欠。", "explanation": "这里应该用〈咳嗽〉。喉咙有痰要咳嗽把痰排出，打哈欠不能排出痰液。"}, {"text": "阳光太刺眼，他不停地打哈欠。", "explanation": "这里应该用〈眨眼〉。阳光刺眼时眼睛会不停眨动，打哈欠是张口吸气，不是对光的反应。"}, {"text": "他摔伤了腿，忍不住打哈欠。", "explanation": "这里应该用〈呻吟〉。疼痛时人会发出呻吟，打哈欠表示困倦，不能用来表达疼痛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee911bcc-5f51-4212-b250-ee73f2686fed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22744, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一上课就打了哈欠一个。", "corrected_sentence": "他一上课就打了哈欠。", "error_description": "错误：句末的“一个”不能直接跟在“哈欠”后面作补充，数量短语应放在“打了”之后。去掉“一个”即为“他一上课就打了哈欠。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee911bcc-5f51-4212-b250-ee73f2686fed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22744, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "奶奶看书时打了哈欠过。", "corrected_sentence": "奶奶看书时打了哈欠。", "error_description": "错误：“了”表示完成，“过”表示经历，二者不能同时用在同一个动词短语后；句末的“过”多余。去掉“过”即为“奶奶看书时打了哈欠。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee911bcc-5f51-4212-b250-ee73f2686fed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
