INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22748, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "生物学是研究动物、植物和其他生物的科学。", "primary_collocate": null, "pronunciation": "shēng wù xué", "ipa": "ʂɤŋ˥ u˥˩ ɕɥɛ˧˥", "syllable_count": 3, "sentences": [{"text": "我哥哥在大学读生物学。", "target_word": "生物学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生物学研究动物和植物。", "target_word": "生物学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她喜欢生物学，常去森林里看鸟。", "target_word": "生物学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生物学老师带我们用显微镜看细胞。", "target_word": "生物学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生物学是一门研究生命的科学。", "target_word": "生物学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想当医生，所以生物学要学好。", "target_word": "生物学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本生物学书里有很多动物图片。", "target_word": "生物学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的生物学课，我们去了公园看植物。", "target_word": "生物学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想了解花怎么长大，就要读生物学。", "target_word": "生物学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生物学考试那天，我很紧张。", "target_word": "生物学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "生物学家", "label": "复合"}, {"form": "生物学课", "label": "复合"}, {"form": "生物學", "label": "繁体"}], "register": "中性", "sense_fingerprint": "名词：研究生物的学科", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb282ec0-1d20-4008-9f52-5b1110039fdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22748, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "食堂", "is_correct": false, "explanation": "语义：“食堂”是地点，不能作“读”的对象，“读食堂”说不通。"}, {"text": "生物学", "is_correct": true, "explanation": "“生物学”是学科名称，可以作“读”的宾语，与“大学”的语境相符。"}, {"text": "宿舍", "is_correct": false, "explanation": "语义：“宿舍”指住的地方，不是学习的对象，“读宿舍”不通。"}, {"text": "足球", "is_correct": false, "explanation": "搭配：“读”搭配学科或专业，“足球”是体育运动，“读足球”不通。"}], "explanations": {"食堂": "语义：“食堂”是地点，不能作“读”的对象，“读食堂”说不通。", "生物学": "“生物学”是学科名称，可以作“读”的宾语，与“大学”的语境相符。", "宿舍": "语义：“宿舍”指住的地方，不是学习的对象，“读宿舍”不通。", "足球": "搭配：“读”搭配学科或专业，“足球”是体育运动，“读足球”不通。"}, "sentence_index": 0, "correct_answer": "生物学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这片森林里生物学很多。", "explanation": "这里指的是具体的动植物，应该用〈动物〉或〈植物〉。〈生物学〉是研究生物的学科，不指森林里的生物本身。"}, {"text": "他是一位生物学，每天都在实验室工作。", "explanation": "这里应该用〈生物学家〉。〈生物学〉是学科，不能指从事研究的人。"}, {"text": "我这学期选了一条生物学。", "explanation": "这里的量词用错了。〈生物学〉作为学科应该用〈门〉，〈条〉用于细长的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8d474c6-5243-4489-b129-456e059f3fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22748, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "会计", "is_correct": false, "explanation": "语义：“会计”是记账的学科，与“动物图片”不相关，会计书里不会以动物图片为主。"}, {"text": "篮球", "is_correct": false, "explanation": "语义：“篮球”是体育运动，与“动物图片”无关，篮球书不会以动物图片为主。"}, {"text": "生物学", "is_correct": true, "explanation": "“生物学”作“书”的修饰语，指生物学方面的书，与“动物图片”相符。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：“汽车书”讲汽车，与“动物图片”不相关，不会以动物图片为主。"}], "explanations": {"会计": "语义：“会计”是记账的学科，与“动物图片”不相关，会计书里不会以动物图片为主。", "篮球": "语义：“篮球”是体育运动，与“动物图片”无关，篮球书不会以动物图片为主。", "生物学": "“生物学”作“书”的修饰语，指生物学方面的书，与“动物图片”相符。", "汽车": "语义：“汽车书”讲汽车，与“动物图片”不相关，不会以动物图片为主。"}, "sentence_index": 6, "correct_answer": "生物学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我姐姐是一位生物学，每天在医院给病人看病。", "explanation": "这里应该用〈医生〉。〈生物学〉是学科名称，不能指从事医疗工作的人。"}, {"text": "他是一位生物学，专门研究花草。", "explanation": "这里应该用〈植物学家〉。〈生物学〉是学科，不能指研究花草的人。"}, {"text": "那位生物学在沙漠里挖掘恐龙化石。", "explanation": "这里应该用〈考古学家〉。〈生物学〉指学科，不能用来指挖掘化石的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8d474c6-5243-4489-b129-456e059f3fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22748, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她大学的专业是一个生物学。", "corrected_sentence": "她大学的专业是生物学。", "error_description": "错误：在学科名称“生物学”前多加了数量词“一个”。正确：作专业或学科名称时，“生物学”前直接接“是”，不加量词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8d474c6-5243-4489-b129-456e059f3fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22748, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我妹妹学了生物学过。", "corrected_sentence": "我妹妹学了生物学。", "error_description": "错误：“过”表示经历，应紧跟动词，不能放在宾语“生物学”之后（应说“学过生物学”）。此句表示已完成，改为“我妹妹学了生物学”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8d474c6-5243-4489-b129-456e059f3fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
