INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22750, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "想就是在脑子里思考、想象，或惦念不在眼前的人或事。", "primary_collocate": null, "pronunciation": "xiǎng", "ipa": "ɕjaŋ˨˩˦", "syllable_count": 1, "sentences": [{"text": "我常常想我的家人。", "target_word": "想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "闭上眼睛，想一想海边的样子。", "target_word": "想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想一想，十年后你在哪儿？", "target_word": "想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在想明天的考试。", "target_word": "想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我正想着远方的朋友。", "target_word": "想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她常常想那个我们一起去过的小岛。", "target_word": "想", "complexity_tier": "T3", "furigana": "tā cháng cháng xiǎng nà gè wǒ men yì qǐ qù guo de xiǎo dǎo", "sentence_source": "generated"}, {"text": "孩子在想妈妈做的饭。", "target_word": "想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你在想什么？", "target_word": "想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他坐在窗前，想远在北方的母亲。", "target_word": "想", "complexity_tier": "T3", "furigana": "tā zuò zài chuāng qián xiǎng yuǎn zài běi fāng de mǔ qīn", "sentence_source": "generated"}, {"text": "走在雪地上，我想小时候的冬天。", "target_word": "想", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "想了", "label": "体标"}, {"form": "想着", "label": "体标"}, {"form": "想过", "label": "体标"}, {"form": "想想", "label": "重叠"}], "register": "中性", "sense_fingerprint": "在脑子里思考、想象或惦念", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06053499-ed7b-46b4-88c1-4bffbe9831f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22750, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "想", "is_correct": true, "explanation": "正确答案：xiǎng（第三声）是“想”，表示在脑子里思考或惦念。"}, {"text": "向", "is_correct": false, "explanation": "xiàng（第四声）与 xiǎng（第三声）声调不同，意思是“向”。"}, {"text": "像", "is_correct": false, "explanation": "xiàng（第四声）与 xiǎng（第三声）声调不同，意思是“像”。"}, {"text": "香", "is_correct": false, "explanation": "xiāng（第一声）与 xiǎng（第三声）声调不同，意思是“香”。"}, {"text": "相", "is_correct": false, "explanation": "xiāng（第一声）与 xiǎng（第三声）声调不同，意思是“互相”。"}], "explanations": {"想": "正确答案：xiǎng（第三声）是“想”，表示在脑子里思考或惦念。", "向": "xiàng（第四声）与 xiǎng（第三声）声调不同，意思是“向”。", "像": "xiàng（第四声）与 xiǎng（第三声）声调不同，意思是“像”。", "香": "xiāng（第一声）与 xiǎng（第三声）声调不同，意思是“香”。", "相": "xiāng（第一声）与 xiǎng（第三声）声调不同，意思是“互相”。"}, "sentence_index": null, "correct_answer": "想"}, "level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象是食物，家人不能被吃，这个句子读来不通。"}, {"text": "想", "is_correct": true, "explanation": "“想”表示惦念，与“常常想我的家人”相符。"}, {"text": "擦", "is_correct": false, "explanation": "语义：“擦”的对象是表面或物品，不能用来擦家人。"}, {"text": "修", "is_correct": false, "explanation": "搭配：“修”的对象是物品、设备，不说修家人。"}], "explanations": {"吃": "语义：“吃”的对象是食物，家人不能被吃，这个句子读来不通。", "想": "“想”表示惦念，与“常常想我的家人”相符。", "擦": "语义：“擦”的对象是表面或物品，不能用来擦家人。", "修": "搭配：“修”的对象是物品、设备，不说修家人。"}, "sentence_index": 0, "correct_answer": "想"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很想吃那家店的蛋糕。", "explanation": "这里的“想”是“想要、希望”的意思，表示愿望，不是“在脑子里思考或惦念”的意思。"}, {"text": "我想他明天应该会来。", "explanation": "这里的“想”是“认为、觉得”的意思，表示判断，不是“思考或惦念”的意思。"}, {"text": "我走进房间，想一阵温暖。", "explanation": "这里应该用〈感到〉。“想”表示思考或惦念，不能用来表示身体的感受。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a704dd41-623e-44e9-8b48-d1a704de2e07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22750, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "想", "is_correct": true, "explanation": "正确答案：xiǎng（第三声）是“想”，表示在脑子里思考或惦念。"}, {"text": "项", "is_correct": false, "explanation": "xiàng（第四声）与 xiǎng（第三声）声调不同，意思是“项目”。"}, {"text": "详", "is_correct": false, "explanation": "xiáng（第二声）与 xiǎng（第三声）声调不同，意思是“详细”。"}, {"text": "乡", "is_correct": false, "explanation": "xiāng（第一声）与 xiǎng（第三声）声调不同，意思是“乡村”。"}], "explanations": {"想": "正确答案：xiǎng（第三声）是“想”，表示在脑子里思考或惦念。", "项": "xiàng（第四声）与 xiǎng（第三声）声调不同，意思是“项目”。", "详": "xiáng（第二声）与 xiǎng（第三声）声调不同，意思是“详细”。", "乡": "xiāng（第一声）与 xiǎng（第三声）声调不同，意思是“乡村”。"}, "sentence_index": null, "correct_answer": "想"}, "level_3": {"options": [{"text": "发明", "is_correct": false, "explanation": "搭配：“发明”的对象是新事物，不说发明已经做好的饭。"}, {"text": "缝", "is_correct": false, "explanation": "搭配：“缝”的对象是衣物、布料，不能用来缝饭。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”的对象是歌曲，不能用来唱饭，这个句子读来不通。"}, {"text": "想", "is_correct": true, "explanation": "“想”表示惦念、怀念，与“孩子在想妈妈做的饭”相符。"}], "explanations": {"发明": "搭配：“发明”的对象是新事物，不说发明已经做好的饭。", "缝": "搭配：“缝”的对象是衣物、布料，不能用来缝饭。", "唱": "语义：“唱”的对象是歌曲，不能用来唱饭，这个句子读来不通。", "想": "“想”表示惦念、怀念，与“孩子在想妈妈做的饭”相符。"}, "sentence_index": 6, "correct_answer": "想"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他气得一拳想在墙上。", "explanation": "这里应该用〈打〉。“想”不表示击打的动作，应说“一拳打在墙上”。"}, {"text": "我想再来一碗热汤。", "explanation": "这里的“想”是“想要、希望”的意思，表示愿望，不是“在脑子里思考或惦念”的意思。"}, {"text": "我想今年冬天会很冷。", "explanation": "这里的“想”是“认为、推测”的意思，不是“在脑子里思考或惦念”的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a704dd41-623e-44e9-8b48-d1a704de2e07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22750, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想很家，很想回去看看。", "corrected_sentence": "我很想家，很想回去看看。", "error_description": "错误：程度副词“很”要放在“想”前面，应说“我很想家”，“想很”不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a704dd41-623e-44e9-8b48-d1a704de2e07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22750, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他常常起想小时候的冬天。", "corrected_sentence": "他常常想起小时候的冬天。", "error_description": "错误：“想起”中的“起”要紧跟在“想”后面，应说“想起”，不能说“起想”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a704dd41-623e-44e9-8b48-d1a704de2e07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
