INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22752, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "脑袋里用来想事情、记东西的部分。", "primary_collocate": null, "pronunciation": "dà nǎo", "ipa": "ta˥˩ nau˨˩˦", "syllable_count": 2, "sentences": [{"text": "大脑是人身体里很重要的部分。", "target_word": "大脑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡觉可以让大脑好好休息。", "target_word": "大脑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的大脑里有很多好想法。", "target_word": "大脑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "喝咖啡能让大脑更清醒。", "target_word": "大脑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多运动对大脑有好处。", "target_word": "大脑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的大脑长得很快。", "target_word": "大脑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我太累了，大脑一片空白。", "target_word": "大脑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大脑用来想事情，也用来记东西。", "target_word": "大脑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看书能让你的大脑动起来。", "target_word": "大脑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他摔了一跤，大脑受了伤。", "target_word": "大脑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "大脑皮层", "label": "复合"}, {"form": "大脑半球", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词，头里负责思考和记忆的器官", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca85f957-df35-4d8f-af57-1db695739dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22752, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大脑", "is_correct": true, "explanation": "正确答案：大脑 dà nǎo，头部负责思考和记忆的器官。"}, {"text": "大佬", "is_correct": false, "explanation": "大佬 dà lǎo 与 大脑 dà nǎo 第二个音节声母不同（l 与 n），意思是有权势或地位高的人。"}, {"text": "打闹", "is_correct": false, "explanation": "打闹 dǎ nào 与 大脑 dà nǎo 两个音节的声调都不同，意思是嬉戏打闹。"}, {"text": "大闹", "is_correct": false, "explanation": "大闹 dà nào 与 大脑 dà nǎo 第二个音节声调不同（nào 与 nǎo），意思是大吵大闹。"}, {"text": "大难", "is_correct": false, "explanation": "大难 dà nàn 与 大脑 dà nǎo 第二个音节韵母与声调不同，意思是重大灾难。"}], "explanations": {"大脑": "正确答案：大脑 dà nǎo，头部负责思考和记忆的器官。", "大佬": "大佬 dà lǎo 与 大脑 dà nǎo 第二个音节声母不同（l 与 n），意思是有权势或地位高的人。", "打闹": "打闹 dǎ nào 与 大脑 dà nǎo 两个音节的声调都不同，意思是嬉戏打闹。", "大闹": "大闹 dà nào 与 大脑 dà nǎo 第二个音节声调不同（nào 与 nǎo），意思是大吵大闹。", "大难": "大难 dà nàn 与 大脑 dà nǎo 第二个音节韵母与声调不同，意思是重大灾难。"}, "sentence_index": null, "correct_answer": "大脑"}, "level_3": {"options": [{"text": "大脑", "is_correct": true, "explanation": "正确：大脑是身体里很重要的器官，符合句子的语境。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不是人身体的器官，“汽车是身体里很重要的部分”不合事实。"}, {"text": "时间", "is_correct": false, "explanation": "语义：时间不是身体的一部分，不能放在“身体里”。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：颜色不是器官，“身体里的颜色”不能作“部分”的同位语。"}], "explanations": {"大脑": "正确：大脑是身体里很重要的器官，符合句子的语境。", "汽车": "语义：汽车不是人身体的器官，“汽车是身体里很重要的部分”不合事实。", "时间": "语义：时间不是身体的一部分，不能放在“身体里”。", "颜色": "搭配：颜色不是器官，“身体里的颜色”不能作“部分”的同位语。"}, "sentence_index": 0, "correct_answer": "大脑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生在手术中取出了一只大脑。", "explanation": "这里应该用〈个〉。大脑是器官，计量用“个”，“只”多用于动物或某些成对的东西。"}, {"text": "他紧张极了，大脑跳得很快。", "explanation": "这里应该用〈心脏〉。跳动是心脏的功能，大脑负责思考和记忆，不说“大脑跳”。"}, {"text": "他饿得厉害，大脑咕咕直叫。", "explanation": "这里应该用〈肚子〉。咕咕叫是肚子饿时发出的声音，大脑不会这样叫。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c290b81d-0dcb-45a5-b379-91fe24a99a2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22752, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大脑", "is_correct": true, "explanation": "正确：“一片空白”形容头脑里什么也想不起来，符合疲劳时的语境。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会有思维状态，“石头一片空白”不能形容这种疲劳。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子没有思维，“房子一片空白”不能形容“我太累了”的感受。"}, {"text": "手指", "is_correct": false, "explanation": "搭配：“一片空白”不能用来形容手指，手指没有“空白”的状态。"}], "explanations": {"大脑": "正确：“一片空白”形容头脑里什么也想不起来，符合疲劳时的语境。", "石头": "语义：石头不会有思维状态，“石头一片空白”不能形容这种疲劳。", "房子": "语义：房子没有思维，“房子一片空白”不能形容“我太累了”的感受。", "手指": "搭配：“一片空白”不能用来形容手指，手指没有“空白”的状态。"}, "sentence_index": 6, "correct_answer": "大脑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他喊了一整天，大脑哑了。", "explanation": "这里应该用〈嗓子〉。哑是嗓子的状态，大脑不会哑。"}, {"text": "他摔了一跤，大脑断了。", "explanation": "这里应该用〈骨头〉。断是骨头的变化，大脑是器官，不会断。"}, {"text": "他的大脑很甜。", "explanation": "“甜”只用于食物的味道，大脑不是食物，不能说“很甜”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c290b81d-0dcb-45a5-b379-91fe24a99a2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22752, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "医生用仪器检查了他的一只大脑。", "corrected_sentence": "医生用仪器检查了他的大脑。", "error_description": "“大脑”指人的器官，不用“只”计量，这里应去掉量词“一只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c290b81d-0dcb-45a5-b379-91fe24a99a2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22752, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的大脑们累了。", "corrected_sentence": "我的大脑累了。", "error_description": "错误：“们”只用于人或拟人对象，“大脑”是器官，不能加“们”表示复数。应说“我的大脑累了。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c290b81d-0dcb-45a5-b379-91fe24a99a2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
