INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22754, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指一段时间或某个时间点。", "primary_collocate": null, "pronunciation": "shí hou", "ipa": "ʂɻ̩˧˥ xou˩", "syllable_count": 2, "sentences": [{"text": "你什么时候有空？", "target_word": "时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我吃饭的时候不看手机。", "target_word": "时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在是什么时候了？", "target_word": "时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨的时候，我常在家看书。", "target_word": "时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个时候，我还不会说中文。", "target_word": "时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他回家的时候，妈妈正在做饭。", "target_word": "时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天是花开的时候。", "target_word": "时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不知道他什么时候来。", "target_word": "时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子睡觉的时候，请小声说话。", "target_word": "时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学汉语的时候，我喜欢听歌。", "target_word": "时候", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "什么时候", "label": "复合"}, {"form": "的时候", "label": "复合"}, {"form": "小时候", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词，表示某一段时间或某个时间点，常说“……的时候”“什么时候”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca85f957-df35-4d8f-af57-1db695739dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22754, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "时候", "is_correct": true, "explanation": "正确答案：时候 shí hou，指某个时间点或一段时间。"}, {"text": "石头", "is_correct": false, "explanation": "石头 shí tou 与 时候 shí hou 第二个音节声母不同（t 与 h），意思是石块。"}, {"text": "事后", "is_correct": false, "explanation": "事后 shì hòu 与 时候 shí hou 两个音节的声调都不同，意思是事情发生之后。"}, {"text": "十号", "is_correct": false, "explanation": "十号 shí hào 第二个音节的韵母与声调不同（hào 与 hou），意思是第十号。"}, {"text": "十楼", "is_correct": false, "explanation": "十楼 shí lóu 第二个音节的声母与声调不同（lóu 与 hou），意思是第十层楼。"}], "explanations": {"时候": "正确答案：时候 shí hou，指某个时间点或一段时间。", "石头": "石头 shí tou 与 时候 shí hou 第二个音节声母不同（t 与 h），意思是石块。", "事后": "事后 shì hòu 与 时候 shí hou 两个音节的声调都不同，意思是事情发生之后。", "十号": "十号 shí hào 第二个音节的韵母与声调不同（hào 与 hou），意思是第十号。", "十楼": "十楼 shí lóu 第二个音节的声母与声调不同（lóu 与 hou），意思是第十层楼。"}, "sentence_index": null, "correct_answer": "时候"}, "level_3": {"options": [{"text": "时候", "is_correct": true, "explanation": "正确：“什么时候”问的是时间点，符合“有空”的语境。"}, {"text": "地方", "is_correct": false, "explanation": "语义：“地方”指场所，这里问的是时间，“什么地方有空”说不通。"}, {"text": "东西", "is_correct": false, "explanation": "搭配：“有空”的主语应是人，不能说“东西有空”。"}, {"text": "原因", "is_correct": false, "explanation": "语义：“原因”指事情的起因，“什么原因有空”没有意义，这里问的是时间。"}], "explanations": {"时候": "正确：“什么时候”问的是时间点，符合“有空”的语境。", "地方": "语义：“地方”指场所，这里问的是时间，“什么地方有空”说不通。", "东西": "搭配：“有空”的主语应是人，不能说“东西有空”。", "原因": "语义：“原因”指事情的起因，“什么原因有空”没有意义，这里问的是时间。"}, "sentence_index": 0, "correct_answer": "时候"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们的时候很充足，不用着急。", "explanation": "这里应该用〈时间〉。时候指某个时点或时段，不表示可以支配的时间总量，应说“时间很充足”。"}, {"text": "我时候很饿，想吃午饭。", "explanation": "这里应直说“我很饿”。时候是时间点，不能作“我”的饥饿状态的主语。"}, {"text": "他的时候很高，像一棵树。", "explanation": "这里应该用〈个子〉。时候只表示时间点或时段，不能用来描述人的高矮，应说“个子很高”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c290b81d-0dcb-45a5-b379-91fe24a99a2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22754, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "时候", "is_correct": true, "explanation": "正确：“花开的时候”指一个时间点或时段，符合语境。"}, {"text": "位置", "is_correct": false, "explanation": "语义：“位置”指空间方位，“花开的位置”说不通，句子说的是时间。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”指岁数，“春天是花开的年龄”没有意义，这里说的是时间。"}, {"text": "钱包", "is_correct": false, "explanation": "语义：“钱包”是装钱的东西，“春天是花开的钱包”没有意义，与句子表示时间的语义不合。"}], "explanations": {"时候": "正确：“花开的时候”指一个时间点或时段，符合语境。", "位置": "语义：“位置”指空间方位，“花开的位置”说不通，句子说的是时间。", "年龄": "语义：“年龄”指岁数，“春天是花开的年龄”没有意义，这里说的是时间。", "钱包": "语义：“钱包”是装钱的东西，“春天是花开的钱包”没有意义，与句子表示时间的语义不合。"}, "sentence_index": 6, "correct_answer": "时候"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "在信息时候，我们要不断学习新知识。", "explanation": "这里应该用〈时代〉。时候只指一个时间点或时段，泛指一个历史阶段要说“时代”，“信息时候”不这么用。"}, {"text": "我在图书馆待了三个时候。", "explanation": "这里应该用〈小时〉。时候可以指一段时间，但不作计时单位，计算时长要说“小时”或“天”，应说“待了三个小时”。"}, {"text": "时候飞逝，转眼一年过去了。", "explanation": "这里应该用〈时光〉。“时光飞逝”是固定说法，时候只指某个时点或一段时段，不表示时间的流逝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c290b81d-0dcb-45a5-b379-91fe24a99a2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22754, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "哪个时候，我常去公园。", "corrected_sentence": "那个时候，我常去公园。", "error_description": "“那个时候”是指示词“那”加“时候”，指过去的某段时间。“哪个”是疑问词，陈述句中不能用，应改为“那个时候”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c290b81d-0dcb-45a5-b379-91fe24a99a2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22754, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你明天怎么时候来？", "corrected_sentence": "你明天什么时候来？", "error_description": "“怎么”用来问方式或原因，不能用来问时间。问时间要用“什么时候”，“怎么时候”是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c290b81d-0dcb-45a5-b379-91fe24a99a2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22756, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "变热", "is_correct": true, "explanation": "正确：变热指温度由低变高，与“变凉”的温度变化方向相反，是其反义词。"}, {"text": "缩小", "is_correct": false, "explanation": "缩小指范围或体积变小，与“变凉”没有反义关系。"}, {"text": "飞翔", "is_correct": false, "explanation": "飞翔指在空中飞行，与“变凉”没有反义关系。"}, {"text": "收获", "is_correct": false, "explanation": "收获指获得成果，与“变凉”没有反义关系。"}], "correct_answer": "变热", "explanations": {"变热": "正确：变热指温度由低变高，与“变凉”的温度变化方向相反，是其反义词。", "缩小": "缩小指范围或体积变小，与“变凉”没有反义关系。", "飞翔": "飞翔指在空中飞行，与“变凉”没有反义关系。", "收获": "收获指获得成果，与“变凉”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6613ce0-ba69-401c-9059-36a04fcd6251') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22756, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "变热", "is_correct": true, "explanation": "正确：变热指温度由低变高，与“变凉”的温度变化方向相反，是其反义词。"}, {"text": "放大", "is_correct": false, "explanation": "放大指使东西变大，与“变凉”没有反义关系。"}, {"text": "集中", "is_correct": false, "explanation": "集中指聚在一起，与“变凉”没有反义关系。"}, {"text": "站立", "is_correct": false, "explanation": "站立指身体直立，与“变凉”没有反义关系。"}], "correct_answer": "变热", "explanations": {"变热": "正确：变热指温度由低变高，与“变凉”的温度变化方向相反，是其反义词。", "放大": "放大指使东西变大，与“变凉”没有反义关系。", "集中": "集中指聚在一起，与“变凉”没有反义关系。", "站立": "站立指身体直立，与“变凉”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6613ce0-ba69-401c-9059-36a04fcd6251') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22756, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不再热了，变得凉凉的。", "primary_collocate": null, "pronunciation": "biàn liáng", "ipa": "pjɛn˥˩ ljɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "太阳下山后，天气慢慢变凉了。", "target_word": "变凉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "热汤放一会儿就变凉了。", "target_word": "变凉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "秋天到了，早上的风变凉了。", "target_word": "变凉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你快喝吧，不然茶就要变凉了。", "target_word": "变凉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨以后，空气变凉了很多。", "target_word": "变凉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夜里，房间里的温度慢慢变凉。", "target_word": "变凉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "咖啡放太久，已经变凉了。", "target_word": "变凉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "洗完澡，水很快就变凉了。", "target_word": "变凉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他站在窗边，觉得身体慢慢变凉。", "target_word": "变凉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天晚上，湖边的风会变凉。", "target_word": "变凉", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "变凉了", "label": "体标"}, {"form": "變涼", "label": "繁体"}], "register": "中性", "sense_fingerprint": "通俗说法：东西或天气不再热，变得凉凉的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e78e7629-b941-480b-9bbb-59f93d1c33f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22756, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "变凉", "is_correct": true, "explanation": "正确：变凉指东西或天气不再热，变得凉凉的。"}, {"text": "变亮", "is_correct": false, "explanation": "liàng（第四声）与 liáng（第二声）声调不同，变亮意思是变得明亮，不是变凉。"}, {"text": "变量", "is_correct": false, "explanation": "liàng（第四声）与 liáng（第二声）声调不同，变量指可以变化的量，与温度无关。"}, {"text": "变蓝", "is_correct": false, "explanation": "lán 与 liáng 韵母不同（-an 与 -ang），变蓝意思是颜色变成蓝色。"}], "explanations": {"变凉": "正确：变凉指东西或天气不再热，变得凉凉的。", "变亮": "liàng（第四声）与 liáng（第二声）声调不同，变亮意思是变得明亮，不是变凉。", "变量": "liàng（第四声）与 liáng（第二声）声调不同，变量指可以变化的量，与温度无关。", "变蓝": "lán 与 liáng 韵母不同（-an 与 -ang），变蓝意思是颜色变成蓝色。"}, "sentence_index": null, "correct_answer": "变凉"}, "level_3": {"options": [{"text": "变凉", "is_correct": true, "explanation": "正确：太阳下山后天气转凉，只有“变凉”符合句意。"}, {"text": "变热", "is_correct": false, "explanation": "语义：太阳下山后天气转凉，“变热”与句意相反。"}, {"text": "变宽", "is_correct": false, "explanation": "搭配：“变宽”用于空间或物体，天气不能说变宽。"}, {"text": "变暖", "is_correct": false, "explanation": "语义：“变暖”与太阳下山后的降温方向相反。"}], "explanations": {"变凉": "正确：太阳下山后天气转凉，只有“变凉”符合句意。", "变热": "语义：太阳下山后天气转凉，“变热”与句意相反。", "变宽": "搭配：“变宽”用于空间或物体，天气不能说变宽。", "变暖": "语义：“变暖”与太阳下山后的降温方向相反。"}, "sentence_index": 0, "correct_answer": "变凉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "火车的速度变凉了。", "explanation": "这里应该用〈加快〉。变凉只指温度下降；速度变快要说“加快”。"}, {"text": "这个孩子长了两年，已经变凉了。", "explanation": "这里应该用〈变高〉。身高增加要说“变高”，变凉只指温度下降，不能用于身高。"}, {"text": "他的水平变凉了。", "explanation": "这里应该用〈提高〉。水平上升要说“提高”，变凉不能用于水平。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6613ce0-ba69-401c-9059-36a04fcd6251') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22756, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "变凉", "is_correct": true, "explanation": "正确：咖啡放久后温度降低，只有“变凉”符合句意。"}, {"text": "变软", "is_correct": false, "explanation": "搭配：“变软”说质地，咖啡放久不会变软。"}, {"text": "变长", "is_correct": false, "explanation": "搭配：“变长”用于长度，咖啡不能说变长。"}, {"text": "变高", "is_correct": false, "explanation": "语义：咖啡放久后变化的是温度，不是高度。"}], "explanations": {"变凉": "正确：咖啡放久后温度降低，只有“变凉”符合句意。", "变软": "搭配：“变软”说质地，咖啡放久不会变软。", "变长": "搭配：“变长”用于长度，咖啡不能说变长。", "变高": "语义：咖啡放久后变化的是温度，不是高度。"}, "sentence_index": 6, "correct_answer": "变凉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这棵树苗一天天变凉了。", "explanation": "这里应该用〈增长〉。植物长高变大要说“增长”，变凉只指温度下降，不能用于植物。"}, {"text": "这家公司的规模变凉了。", "explanation": "这里应该用〈扩大〉。规模变大要说“扩大”，变凉不能用于规模。"}, {"text": "比赛的时间变凉了。", "explanation": "这里应该用〈延长〉。时间拉长要说“延长”，变凉不能用于时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6613ce0-ba69-401c-9059-36a04fcd6251') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22756, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "晚饭做好以后，汤慢慢就很变凉了。", "corrected_sentence": "晚饭做好以后，汤慢慢就变凉了。", "error_description": "错误：“很变凉”；正确：“变凉了”。“很”是程度副词，只能修饰形容词，不能直接修饰动词“变凉”，应去掉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6613ce0-ba69-401c-9059-36a04fcd6251') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22756, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜里风慢慢被变凉了。", "corrected_sentence": "夜里风慢慢变凉了。", "error_description": "错误：“变凉”是表示变化的不及物动词，不能用“被”字句，应去掉“被”。正确：“夜里风慢慢变凉了。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6613ce0-ba69-401c-9059-36a04fcd6251') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
