INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22758, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86635e38-5915-4314-90db-e832f39de107') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22758, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "神经学是研究大脑和神经怎么让人动、让人想东西的学问。", "primary_collocate": null, "pronunciation": "shén jīng xué", "ipa": "ʂən˧˥ tɕiŋ˥ ɕɥɛ˧˥", "syllable_count": 3, "sentences": [{"text": "神经学是研究神经的学问。", "target_word": "神经学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她大学学的是神经学。", "target_word": "神经学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "神经学老师讲了大脑怎么工作。", "target_word": "神经学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对神经学很感兴趣，想知道人为什么会记东西。", "target_word": "神经学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥在大学里教神经学。", "target_word": "神经学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习神经学能帮医生了解病人的大脑。", "target_word": "神经学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书讲的是神经学，里面有很多大脑的图片。", "target_word": "神经学", "complexity_tier": "T3", "furigana": "zhè běn shū jiǎng de shì shénjīngxué, lǐmiàn yǒu hěn duō dànǎo de túpiàn.", "sentence_source": "generated"}, {"text": "神经学研究人的手脚为什么听大脑的话。", "target_word": "神经学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要学好神经学，先要认识大脑的各个部分。", "target_word": "神经学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想把神经学和电脑放在一起研究。", "target_word": "神经学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "神經學", "label": "繁体"}, {"form": "神经学家", "label": "复合"}], "register": "书面", "sense_fingerprint": "神经学：研究大脑和神经系统的学科", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cff4beb-2454-4408-ae79-6e87aa30b10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22758, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "美学", "is_correct": false, "explanation": "语义：美学研究美与审美，不研究神经。"}, {"text": "神经学", "is_correct": true, "explanation": "神经学：研究神经系统的学科，正好是句中的主语。"}, {"text": "天文学", "is_correct": false, "explanation": "语义：天文学研究天体和宇宙，与神经无关。"}, {"text": "神经病", "is_correct": false, "explanation": "语域：「神经病」是口语中骂人的话，不能用来定义一门学科。"}], "explanations": {"美学": "语义：美学研究美与审美，不研究神经。", "神经学": "神经学：研究神经系统的学科，正好是句中的主语。", "天文学": "语义：天文学研究天体和宇宙，与神经无关。", "神经病": "语域：「神经病」是口语中骂人的话，不能用来定义一门学科。"}, "sentence_index": 0, "correct_answer": "神经学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我大学时选修了一本神经学，觉得很有意思。", "explanation": "这里应该用〈门〉。学科类名称用「门」，「本」用于书籍。"}, {"text": "他是一位神经学，专门治疗大脑的病人。", "explanation": "这里应该用〈神经学家〉。神经学是学科名称，指人要说「神经学家」。"}, {"text": "他的手受伤后，神经学受到了损伤。", "explanation": "这里应该用〈神经〉。神经学是研究神经的学科，不指神经组织本身。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86635e38-5915-4314-90db-e832f39de107') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22758, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "美食", "is_correct": false, "explanation": "语义：美食与大脑的图片无关，书中不会讲美食。"}, {"text": "神经学", "is_correct": true, "explanation": "神经学：研究大脑和神经系统的学科，与句中的大脑图片相符。"}, {"text": "园艺", "is_correct": false, "explanation": "语义：园艺讲的是种植花草，和大脑图片不相关。"}, {"text": "八卦", "is_correct": false, "explanation": "语域：「八卦」是口语中的闲话，不能用来说一本讲学科的书。"}], "explanations": {"美食": "语义：美食与大脑的图片无关，书中不会讲美食。", "神经学": "神经学：研究大脑和神经系统的学科，与句中的大脑图片相符。", "园艺": "语义：园艺讲的是种植花草，和大脑图片不相关。", "八卦": "语域：「八卦」是口语中的闲话，不能用来说一本讲学科的书。"}, "sentence_index": 6, "correct_answer": "神经学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他这次因为头疼，去医院挂了神经学的号。", "explanation": "这里应该用〈神经内科〉。神经学是学科，不是医院科室，挂号要说「神经内科」。"}, {"text": "他患了神经学，需要吃药治疗。", "explanation": "这里应该用〈神经炎〉。神经学是学科名称，不是疾病，不能说「患了神经学」。"}, {"text": "神经学之间通过突触传递信号。", "explanation": "这里应该用〈神经元〉。神经学是学科，不能作为细胞之间传递信号的主体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86635e38-5915-4314-90db-e832f39de107') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22758, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他打算学习一门很难神经学。", "corrected_sentence": "他打算学习一门很难的神经学。", "error_description": "错误形式是「很难神经学」，正确形式是「很难的神经学」。「很难」修饰名词时中间要加「的」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86635e38-5915-4314-90db-e832f39de107') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22758, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她对把神经学很感兴趣。", "corrected_sentence": "她对神经学很感兴趣。", "error_description": "错误形式是「把神经学很感兴趣」，正确形式是「对神经学很感兴趣」：引出感兴趣的对象要用介词「对」，「把」字句不能与「感兴趣」搭配。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86635e38-5915-4314-90db-e832f39de107') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
