INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22762, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人或动物的整个躯体，也指身体的健康状况。", "primary_collocate": null, "pronunciation": "shēn tǐ", "ipa": "ʂən˥ tʰi˨˩˦", "syllable_count": 2, "sentences": [{"text": "运动对身体很好。", "target_word": "身体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的身体很健康。", "target_word": "身体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我今天身体不太舒服。", "target_word": "身体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人的身体有头、手和脚。", "target_word": "身体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷年纪大了，要注意身体。", "target_word": "身体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说她的身体需要休息。", "target_word": "身体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游泳可以让身体更强壮。", "target_word": "身体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他冷得身体直发抖。", "target_word": "身体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请照顾好自己的身体。", "target_word": "身体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的身体长得很快。", "target_word": "身体", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "身体健康", "label": "复合"}, {"form": "身体素质", "label": "复合"}, {"form": "副", "label": "量词"}], "register": "中性", "sense_fingerprint": "人或动物的整个躯体，也指健康状况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b76edc4-0981-45f9-b40b-13826adb3d03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22762, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "身体", "is_correct": true, "explanation": "正确：“身体”指人的整个躯体，“运动对身体很好”正合句意。"}, {"text": "食物", "is_correct": false, "explanation": "语义：运动不能对“食物”产生好坏影响，“对食物很好”句意不通。"}, {"text": "音乐", "is_correct": false, "explanation": "搭配：“对……很好”搭配的是人或健康，不能说“对音乐很好”。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”指价钱，运动与价钱的好坏没有关系，句意不通。"}], "explanations": {"身体": "正确：“身体”指人的整个躯体，“运动对身体很好”正合句意。", "食物": "语义：运动不能对“食物”产生好坏影响，“对食物很好”句意不通。", "音乐": "搭配：“对……很好”搭配的是人或健康，不能说“对音乐很好”。", "价格": "语义：“价格”指价钱，运动与价钱的好坏没有关系，句意不通。"}, "sentence_index": 0, "correct_answer": "身体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的身体有一米八，非常高。", "explanation": "这里应该用〈身高〉。说人的高矮要用“身高”，“身体”指整个躯体和健康状况。"}, {"text": "她的身体今天要去上学。", "explanation": "这里应该用〈她〉。身体不能去上学，要说人去上学。"}, {"text": "我发烧了，身体是三十九度。", "explanation": "这里应该用〈体温〉。三十九度是体温的数值，“身体”不能用来表示温度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7df9bc8-1bcf-43c8-be31-eb6336a223a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22762, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "身体", "is_correct": true, "explanation": "正确：“身体”指人体，“让身体更强壮”正合句意。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“强壮”用于人或动植物，不修饰房子，房子只能说“坚固”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是人，游泳无法让天气“强壮”，句意不通。"}, {"text": "声音", "is_correct": false, "explanation": "语义：“声音”不能用“强壮”来形容，“让声音更强壮”句意不通。"}], "explanations": {"身体": "正确：“身体”指人体，“让身体更强壮”正合句意。", "房子": "搭配：“强壮”用于人或动植物，不修饰房子，房子只能说“坚固”。", "天气": "语义：“天气”不是人，游泳无法让天气“强壮”，句意不通。", "声音": "语义：“声音”不能用“强壮”来形容，“让声音更强壮”句意不通。"}, "sentence_index": 6, "correct_answer": "身体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他有一本身体，很强壮。", "explanation": "这里应该用〈个〉。“本”用于书籍，不能用来量身体。"}, {"text": "她的一张身体很漂亮。", "explanation": "这里应该用〈个〉。“张”用于平面的东西，不能用来量身体。"}, {"text": "孩子有一条身体，长得很快。", "explanation": "这里应该用〈个〉。“条”用于细长的东西，不能用来量身体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7df9bc8-1bcf-43c8-be31-eb6336a223a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22762, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他最近一个身体不太好。", "corrected_sentence": "他最近身体不太好。", "error_description": "「身体」指人的整个躯体或健康状况，是整体概念，不能直接用数量短语「一个」修饰。应删去「一个」，说「身体不太好」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7df9bc8-1bcf-43c8-be31-eb6336a223a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22762, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每天锻炼一个身体。", "corrected_sentence": "他每天锻炼身体。", "error_description": "“锻炼身体”是固定的动宾搭配，“身体”前面不宜插入数量短语“一个”，应说“锻炼身体”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7df9bc8-1bcf-43c8-be31-eb6336a223a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
