INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22768, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事情的样子，能被看到或感受到。", "primary_collocate": null, "pronunciation": "xiàn xiàng", "ipa": "ɕiɛn⁵¹ ɕiɑŋ⁵¹", "syllable_count": 2, "sentences": [{"text": "冬天下雪是一种自然现象。", "target_word": "现象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个现象很有意思。", "target_word": "现象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们看了一个奇怪的现象。", "target_word": "现象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早上有雾是常见的现象。", "target_word": "现象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要找出这个现象的原因。", "target_word": "现象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在很多人玩手机，这个现象很普遍。", "target_word": "现象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨前蚂蚁搬家是有意思的现象。", "target_word": "现象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种现象在大城市很多。", "target_word": "现象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "闪电和打雷是一起出现的现象。", "target_word": "现象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人看书看得久，眼睛会累，这是正常现象。", "target_word": "现象", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "种", "label": "量词"}, {"form": "自然现象", "label": "复合"}, {"form": "社会现象", "label": "复合"}], "register": "中性", "sense_fingerprint": "能看到或感受到的事情的样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89604cde-aa36-49a3-b834-19b3606a7411') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22768, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "现象", "is_correct": true, "explanation": "“现象”指事情的样子，能被看到或感受到，是正确答案。"}, {"text": "险象", "is_correct": false, "explanation": "xiǎnxiàng 与 xiànxiàng 第一个音节声调不同（第三声与第四声），“险象”指危险的情况。"}, {"text": "线香", "is_correct": false, "explanation": "xiànxiāng 与 xiànxiàng 第二个音节声调不同（第一声与第四声），“线香”指点燃的细香。"}, {"text": "鲜香", "is_correct": false, "explanation": "xiānxiāng 与 xiànxiàng 两个音节声调都不同，“鲜香”形容食物鲜美香气。"}], "explanations": {"现象": "“现象”指事情的样子，能被看到或感受到，是正确答案。", "险象": "xiǎnxiàng 与 xiànxiàng 第一个音节声调不同（第三声与第四声），“险象”指危险的情况。", "线香": "xiànxiāng 与 xiànxiàng 第二个音节声调不同（第一声与第四声），“线香”指点燃的细香。", "鲜香": "xiānxiāng 与 xiànxiàng 两个音节声调都不同，“鲜香”形容食物鲜美香气。"}, "sentence_index": null, "correct_answer": "现象"}, "level_3": {"options": [{"text": "现象", "is_correct": true, "explanation": "“自然现象”指自然界发生的事情，与句意相符，通顺。"}, {"text": "动物", "is_correct": false, "explanation": "语义：下雪是自然现象，不是动物，句意不通。"}, {"text": "教室", "is_correct": false, "explanation": "搭配：“自然”修饰现象、物质，不修饰教室。"}, {"text": "思想", "is_correct": false, "explanation": "语义：下雪不是思想，“自然思想”说不通。"}], "explanations": {"现象": "“自然现象”指自然界发生的事情，与句意相符，通顺。", "动物": "语义：下雪是自然现象，不是动物，句意不通。", "教室": "搭配：“自然”修饰现象、物质，不修饰教室。", "思想": "语义：下雪不是思想，“自然思想”说不通。"}, "sentence_index": 0, "correct_answer": "现象"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "街上的现象很热闹，人很多。", "explanation": "这里应该用〈场面〉。“热闹”形容场面、场合，现象是事情的样子，不能这样形容。"}, {"text": "我在河边看见了一座现象。", "explanation": "这里的量词用错了。“座”用于山、桥、建筑，现象不能这样数，应该用“种”或“个”。"}, {"text": "他的现象很外向，爱交朋友。", "explanation": "这里应该用〈性格〉。“外向”形容人的性格，现象指事情的样子，不能这样形容人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe6a8d1c-091f-4a38-8fae-b32d42373c35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22768, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "现象", "is_correct": true, "explanation": "“有意思的现象”指值得注意的自然情况，蚂蚁搬家属于这种现象，通顺。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“有意思”形容事物或事情，不能用于年龄。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“有意思”不能形容体重，句意不通。"}, {"text": "距离", "is_correct": false, "explanation": "搭配：“有意思”不用于距离，距离只说远近。"}], "explanations": {"现象": "“有意思的现象”指值得注意的自然情况，蚂蚁搬家属于这种现象，通顺。", "年龄": "搭配：“有意思”形容事物或事情，不能用于年龄。", "体重": "语义：“有意思”不能形容体重，句意不通。", "距离": "搭配：“有意思”不用于距离，距离只说远近。"}, "sentence_index": 6, "correct_answer": "现象"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的现象需要吃药，不能拖。", "explanation": "这里应该用〈症状〉。“现象”指事情的样子，需要吃药的情况要说症状。"}, {"text": "我昨天在公园看见一片现象。", "explanation": "这里的量词用错了。“片”用于成片的东西，现象不能这样数，应该用“种”或“个”。"}, {"text": "会议室里的现象很紧张。", "explanation": "这里应该用〈气氛〉。“紧张”形容气氛，现象不这样形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe6a8d1c-091f-4a38-8fae-b32d42373c35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22768, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一座很少见的现象。", "corrected_sentence": "这是一种很少见的现象。", "error_description": "错误形式：“一座现象”。正确形式：“一种现象”。“座”用于山、桥、建筑，不能用来计量“现象”，可以用量词“种”或“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe6a8d1c-091f-4a38-8fae-b32d42373c35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22768, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "现在很多人玩手机，这是一种普遍地现象。", "corrected_sentence": "现在很多人玩手机，这是一种普遍的现象。", "error_description": "错误形式：“普遍地现象”。正确形式：“普遍的现象”。“现象”是名词，修饰它的成分要用“的”，“地”用于修饰动词或形容词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe6a8d1c-091f-4a38-8fae-b32d42373c35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
