INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22770, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手或工具碰一下东西。", "primary_collocate": null, "pronunciation": "dǎ", "ipa": "tɑ˨˩˦", "syllable_count": 1, "sentences": [{"text": "他用手轻轻打了一下桌子。", "target_word": "打", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈打了一下我的手，让我别吃。", "target_word": "打", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她用扇子打了一下蚊子。", "target_word": "打", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用棍子打了一下树，树叶掉了下来。", "target_word": "打", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用尺子轻轻打了一下黑板。", "target_word": "打", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小猫用爪子打了一下杯子。", "target_word": "打", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用锤子轻轻打了一下钉子。", "target_word": "打", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友笑着打了一下我的肩膀。", "target_word": "打", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他伸手打了一下我的胳膊，示意我别说话。", "target_word": "打", "complexity_tier": "T3", "furigana": "tā shēn shǒu dǎ le yí xià wǒ de gēbo, shìyì wǒ bié shuō huà", "sentence_source": "generated"}, {"text": "他用笔轻轻打了一下本子。", "target_word": "打", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "打了", "label": "体标（了）"}, {"form": "打过", "label": "体标（过）"}, {"form": "打着", "label": "体标（着）"}, {"form": "打打", "label": "重叠"}], "register": "口语", "sense_fingerprint": "打：用手或工具轻碰、轻拍一下", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T1: 3 words above tier T1 (max 2): 小猫 (Zipf 3.7), 爪子 (Zipf 3.3), 杯子 (Zipf 3.82)','sentence 8 above tier T1: 3 words above tier T1 (max 2): 伸手 (Zipf 3.8), 胳膊 (Zipf 3.85), 示意 (Zipf 3.45)']::text[], 'bcd5bd62-667b-408b-99e4-5d930ae38128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22770, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "打", "is_correct": true, "explanation": "正确：打（dǎ），表示用手或工具轻碰、轻拍一下。"}, {"text": "大", "is_correct": false, "explanation": "dà（第四声）与 dǎ（第三声）声调不同，意思是“大”。"}, {"text": "答", "is_correct": false, "explanation": "dá（第二声）与 dǎ 声调不同，意思是“回答”。"}, {"text": "塔", "is_correct": false, "explanation": "tǎ 与 dǎ 声母不同（t 与 d），意思是“塔”。"}, {"text": "胆", "is_correct": false, "explanation": "dǎn 与 dǎ 韵尾不同（多一个 -n），意思是“胆子”。"}], "explanations": {"打": "正确：打（dǎ），表示用手或工具轻碰、轻拍一下。", "大": "dà（第四声）与 dǎ（第三声）声调不同，意思是“大”。", "答": "dá（第二声）与 dǎ 声调不同，意思是“回答”。", "塔": "tǎ 与 dǎ 声母不同（t 与 d），意思是“塔”。", "胆": "dǎn 与 dǎ 韵尾不同（多一个 -n），意思是“胆子”。"}, "sentence_index": null, "correct_answer": "打"}, "level_3": {"options": [{"text": "打", "is_correct": true, "explanation": "正确：“轻轻打了一下桌子”，表示用手轻碰一下，语义通顺。"}, {"text": "咬", "is_correct": false, "explanation": "搭配：“咬”要用牙齿，与“用手”不搭配。"}, {"text": "踩", "is_correct": false, "explanation": "搭配：“踩”要用脚，与“用手”不搭配。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱歌与轻碰桌子无关，句意不通。"}], "explanations": {"打": "正确：“轻轻打了一下桌子”，表示用手轻碰一下，语义通顺。", "咬": "搭配：“咬”要用牙齿，与“用手”不搭配。", "踩": "搭配：“踩”要用脚，与“用手”不搭配。", "唱": "语义：唱歌与轻碰桌子无关，句意不通。"}, "sentence_index": 0, "correct_answer": "打"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我下班后给妈妈打电话。", "explanation": "这里“打”表示拨打（电话），不表示用手或工具轻碰东西。"}, {"text": "她打了一个哈欠。", "explanation": "这里“打”表示发出（哈欠），不是轻碰、轻拍。"}, {"text": "我们每天打篮球。", "explanation": "这里“打”表示进行篮球运动，不表示轻碰、轻拍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92090941-8504-467c-8bd8-eb8dff2db2c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22770, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "打", "is_correct": true, "explanation": "正确：打（dǎ），表示用手或工具轻碰、轻拍一下。"}, {"text": "把", "is_correct": false, "explanation": "bǎ 与 dǎ 声母不同（b 与 d），声调相同，意思是“把”。"}, {"text": "哪", "is_correct": false, "explanation": "nǎ 与 dǎ 声母不同（n 与 d），声调相同，意思是“哪”。"}, {"text": "达", "is_correct": false, "explanation": "dá（第二声）与 dǎ 声调不同，意思是“到达”。"}, {"text": "搭", "is_correct": false, "explanation": "dā（第一声）与 dǎ 声调不同，意思是“搭建”。"}], "explanations": {"打": "正确：打（dǎ），表示用手或工具轻碰、轻拍一下。", "把": "bǎ 与 dǎ 声母不同（b 与 d），声调相同，意思是“把”。", "哪": "nǎ 与 dǎ 声母不同（n 与 d），声调相同，意思是“哪”。", "达": "dá（第二声）与 dǎ 声调不同，意思是“到达”。", "搭": "dā（第一声）与 dǎ 声调不同，意思是“搭建”。"}, "sentence_index": null, "correct_answer": "打"}, "level_3": {"options": [{"text": "打", "is_correct": true, "explanation": "正确：“轻轻打了一下钉子”，表示用锤子轻碰一下，语义通顺。"}, {"text": "涂", "is_correct": false, "explanation": "搭配：“涂”要用颜料或刷子，不能用锤子涂钉子。"}, {"text": "写", "is_correct": false, "explanation": "语义：用锤子写字与钉子无关，句意不通。"}, {"text": "吹", "is_correct": false, "explanation": "搭配：“吹”要用嘴或风，与“用锤子”不搭配。"}], "explanations": {"打": "正确：“轻轻打了一下钉子”，表示用锤子轻碰一下，语义通顺。", "涂": "搭配：“涂”要用颜料或刷子，不能用锤子涂钉子。", "写": "语义：用锤子写字与钉子无关，句意不通。", "吹": "搭配：“吹”要用嘴或风，与“用锤子”不搭配。"}, "sentence_index": 6, "correct_answer": "打"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她每个冬天都给爸爸打毛衣。", "explanation": "这里“打”表示编织（毛衣），不表示用手或工具轻碰东西。"}, {"text": "他每天早上去井边打水。", "explanation": "这里“打”表示取（水），与轻碰、轻拍无关。"}, {"text": "护士给病人打了一针。", "explanation": "这里“打”表示注射，与轻碰、轻拍的意思无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92090941-8504-467c-8bd8-eb8dff2db2c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22770, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他用手轻轻打着一下窗户。", "corrected_sentence": "他用手轻轻打了一下窗户。", "error_description": "体标错误：动作已经完成应用“了”，“着”表示动作持续，不能与“一下”连用，应说“打了一下窗户”，不能说“打着一下窗户”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92090941-8504-467c-8bd8-eb8dff2db2c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22770, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他用笔轻轻打了一个下书包。", "corrected_sentence": "他用笔轻轻打了一下书包。", "error_description": "量词错误：动量词“下”前面不能再加“个”，应说“打了一下”，不能说“打了一个下”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92090941-8504-467c-8bd8-eb8dff2db2c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
