INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22788, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用眼睛看见人、东西或地方。", "primary_collocate": null, "pronunciation": "kàn dào", "ipa": "kʰan˥˩ taʊ˥˩", "syllable_count": 2, "sentences": [{"text": "我在路上看到一只小狗。", "target_word": "看到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看到我的书了吗？", "target_word": "看到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在窗外看到了雪。", "target_word": "看到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们看到老师就跑过去。", "target_word": "看到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天我看到你妈妈了。", "target_word": "看到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从山上能看到很远的地方。", "target_word": "看到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没看到他进来。", "target_word": "看到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看到蛋糕，高兴极了。", "target_word": "看到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在地铁里，我看到过一位明星。", "target_word": "看到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋里太黑，我没看到路。", "target_word": "看到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "看到了", "label": "完成体"}, {"form": "看到过", "label": "经历体"}, {"form": "看不到", "label": "否定可能式"}], "register": "中性", "sense_fingerprint": "眼睛看见了人、东西或地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b76edc4-0981-45f9-b40b-13826adb3d03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22788, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "看到", "is_correct": true, "explanation": "正确：“看到”表示眼睛看见，“在路上看到一只小狗”正合句意。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”是烹饪，小狗不能被煮，句子说的是看见，句意不通。"}, {"text": "打印", "is_correct": false, "explanation": "搭配：“打印”只用于文件、照片等，不能说“打印一只小狗”。"}, {"text": "拆开", "is_correct": false, "explanation": "语义：“拆开”指打开包装，用于一只小狗不合常理，句子不通。"}], "explanations": {"看到": "正确：“看到”表示眼睛看见，“在路上看到一只小狗”正合句意。", "煮": "语义：“煮”是烹饪，小狗不能被煮，句子说的是看见，句意不通。", "打印": "搭配：“打印”只用于文件、照片等，不能说“打印一只小狗”。", "拆开": "语义：“拆开”指打开包装，用于一只小狗不合常理，句子不通。"}, "sentence_index": 0, "correct_answer": "看到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天晚上都看到一阵暖意。", "explanation": "这里应该用〈感到〉。暖意是身体的感觉，不能用看到。"}, {"text": "我看到了一段美妙的音乐。", "explanation": "这里应该用〈听到〉。音乐要用耳朵听，“看到”只用于视觉对象。"}, {"text": "我看到了饭菜的香味。", "explanation": "这里应该用〈闻到〉。香味要用鼻子闻，不能说看到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7df9bc8-1bcf-43c8-be31-eb6336a223a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22788, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "看到", "is_correct": true, "explanation": "正确：“看到”表示眼睛看见，“我没看到他进来”正合句意。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：“打扫”是清理，不能表示看见他进门，句子不通。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：“翻译”是转换语言，与看见他进门无关，句意不通。"}, {"text": "批评", "is_correct": false, "explanation": "搭配：“批评”是指出别人的错误，不能与“进来”组合表示感知。"}], "explanations": {"看到": "正确：“看到”表示眼睛看见，“我没看到他进来”正合句意。", "打扫": "语义：“打扫”是清理，不能表示看见他进门，句子不通。", "翻译": "语义：“翻译”是转换语言，与看见他进门无关，句意不通。", "批评": "搭配：“批评”是指出别人的错误，不能与“进来”组合表示感知。"}, "sentence_index": 6, "correct_answer": "看到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道菜，我看到了甜味。", "explanation": "这里应该用〈尝到〉。甜味要靠舌头品尝，不能说看到。"}, {"text": "花园里，我看到了花香。", "explanation": "这里应该用〈嗅到〉。花香要用鼻子嗅，不能说看到。"}, {"text": "风吹过来，我看到了一阵凉意。", "explanation": "这里应该用〈感到〉。凉意是身体的感觉，不能用看到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7df9bc8-1bcf-43c8-be31-eb6336a223a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22788, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在超市看到了了一个熟人。", "corrected_sentence": "我在超市看到了一个熟人。", "error_description": "“看到了”后面不能再加一个“了”，应为「看到了一个熟人」，只用一个“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7df9bc8-1bcf-43c8-be31-eb6336a223a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22788, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我昨天不看到那辆车。", "corrected_sentence": "我昨天没看到那辆车。", "error_description": "表示已经发生的“没看见”要用否定词“没”，说“没看到”，不能用“不”，应为「我没看到那辆车」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7df9bc8-1bcf-43c8-be31-eb6336a223a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
