INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22790, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "身体里像线一样的东西，用来传递信息，让身体能感觉和动。", "primary_collocate": null, "pronunciation": "shén jīng", "ipa": "ʂən³⁵ tɕiŋ⁵⁵", "syllable_count": 2, "sentences": [{"text": "神经把信息传给大脑。", "target_word": "神经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手上的神经受伤了，他拿不住杯子。", "target_word": "神经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人的身体里有很多神经。", "target_word": "神经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生检查了我的神经。", "target_word": "神经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "神经让我们的手能感觉到冷和热。", "target_word": "神经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "眼睛里的神经很细。", "target_word": "神经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药对神经有好处。", "target_word": "神经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的腿神经受了伤，走路很疼。", "target_word": "神经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "神经坏了，手就感觉不到东西。", "target_word": "神经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大脑和神经一起管着身体。", "target_word": "神经", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "神经系统", "label": "复合"}, {"form": "神经细胞", "label": "复合"}], "register": "中性", "sense_fingerprint": "身体里传递信息、管感觉和动作的细线", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89604cde-aa36-49a3-b834-19b3606a7411') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22790, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "神经", "is_correct": true, "explanation": "“神经”是传递信息的组织，与“把信息传给大脑”搭配，句意通顺。"}, {"text": "心脏", "is_correct": false, "explanation": "语义：心脏负责输送血液，不传递信息，句子说的“把信息传给大脑”不合。"}, {"text": "血管", "is_correct": false, "explanation": "语义：血管运送血液，不负责传递信息，句意不通。"}, {"text": "肌肉", "is_correct": false, "explanation": "搭配：“把信息传给大脑”要用能传递信息的器官，“肌肉”不这样搭配。"}], "explanations": {"神经": "“神经”是传递信息的组织，与“把信息传给大脑”搭配，句意通顺。", "心脏": "语义：心脏负责输送血液，不传递信息，句子说的“把信息传给大脑”不合。", "血管": "语义：血管运送血液，不负责传递信息，句意不通。", "肌肉": "搭配：“把信息传给大脑”要用能传递信息的器官，“肌肉”不这样搭配。"}, "sentence_index": 0, "correct_answer": "神经"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的神经很结实，每天都锻炼身体。", "explanation": "这里应该用〈肌肉〉。“结实”形容肌肉、骨头，神经不这样形容。"}, {"text": "他手臂受伤了，血从神经里一直流出来。", "explanation": "这里应该用〈血管〉。神经传递信息，血液要在血管里流，不能说“血从神经里流”。"}, {"text": "他手上受伤的是一只神经。", "explanation": "这里的量词用错了。“只”用于动物，神经细长，应该用“根”或“条”来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe6a8d1c-091f-4a38-8fae-b32d42373c35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22790, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "神经", "is_correct": true, "explanation": "“神经”是身体里传递信息的组织，药物对神经有好处，句意通顺。"}, {"text": "石头", "is_correct": false, "explanation": "语义：药物对人和动植物有益，对石头没有好处，句意不通。"}, {"text": "手机", "is_correct": false, "explanation": "语义：药不能对手机起作用，“有好处”一般指生物。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“对……有好处”一般接人或生物，不接房子。"}], "explanations": {"神经": "“神经”是身体里传递信息的组织，药物对神经有好处，句意通顺。", "石头": "语义：药物对人和动植物有益，对石头没有好处，句意不通。", "手机": "语义：药不能对手机起作用，“有好处”一般指生物。", "房子": "搭配：“对……有好处”一般接人或生物，不接房子。"}, "sentence_index": 6, "correct_answer": "神经"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在书上读到一颗神经。", "explanation": "这里的量词用错了。“颗”用于圆粒状的东西，神经细长，应该用“根”或“条”。"}, {"text": "他的神经堵住了，呼吸很困难。", "explanation": "这里应该用〈气管〉。神经传递信息，不会堵塞；呼吸困难是气管堵住了，应该说气管。"}, {"text": "他的神经很聪明，学习很快。", "explanation": "这里应该用〈大脑〉。“聪明”形容大脑的思考能力，神经不能这样形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe6a8d1c-091f-4a38-8fae-b32d42373c35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22790, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "医生在手术中小心地保护了这只神经。", "corrected_sentence": "医生在手术中小心地保护了这根神经。", "error_description": "错误形式：“这只神经”。正确形式：“这根神经”。“只”多用于动物，神经细长如线，应该用量词“根”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe6a8d1c-091f-4a38-8fae-b32d42373c35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22790, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个病人的一块神经小得很。", "corrected_sentence": "这个病人的一根神经小得很。", "error_description": "错误形式：“一块神经”。正确形式：“一根神经”。“块”用于成块的东西，神经细长如线，应该用量词“根”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe6a8d1c-091f-4a38-8fae-b32d42373c35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
