INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22794, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "根据外表或迹象来判断，给人的样子或印象是怎样的。", "primary_collocate": null, "pronunciation": "kàn qǐ lái", "ipa": "kʰan˥˩ tɕʰi˨˩˦ lai˧˥", "syllable_count": 3, "sentences": [{"text": "他看起来很累，我们让他休息吧。", "target_word": "看起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天天气看起来不太好。", "target_word": "看起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个蛋糕看起来很好吃。", "target_word": "看起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看起来比我小几岁。", "target_word": "看起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看起来有点不高兴，怎么了？", "target_word": "看起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事看起来很容易，做起来很难。", "target_word": "看起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家饭馆看起来很干净。", "target_word": "看起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看起来明天会下雨，带上伞吧。", "target_word": "看起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗看起来很饿，一直看着我。", "target_word": "看起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看起来像个老师，其实是医生。", "target_word": "看起来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "看起来：根据外表或迹象判断，给人的样子是某种情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d3283c2-c3c9-456b-a54d-b3cbf61747b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22794, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "摸起来", "is_correct": false, "explanation": "语义：“摸起来”指用手触摸的感觉，用来说人“很累”不合逻辑。"}, {"text": "吃起来", "is_correct": false, "explanation": "搭配：“吃起来”多用于食物的口感，不用来说人的状态。"}, {"text": "闻起来", "is_correct": false, "explanation": "语义：“闻起来”指通过气味来判断，与“很累”无关。"}, {"text": "看起来", "is_correct": true, "explanation": "“看起来”指根据外表判断给人的样子，与“他很累”的判断相符。"}], "explanations": {"摸起来": "语义：“摸起来”指用手触摸的感觉，用来说人“很累”不合逻辑。", "吃起来": "搭配：“吃起来”多用于食物的口感，不用来说人的状态。", "闻起来": "语义：“闻起来”指通过气味来判断，与“很累”无关。", "看起来": "“看起来”指根据外表判断给人的样子，与“他很累”的判断相符。"}, "sentence_index": 0, "correct_answer": "看起来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌看起来很好听。", "explanation": "这里应该用〈听起来〉。判断声音好不好听要用听起来；看起来只用于说外表或样子。"}, {"text": "这双袜子看起来很臭。", "explanation": "这里应该用〈闻起来〉。“臭”要靠气味判断，应说闻起来；看起来只能判断外表。"}, {"text": "这段音乐看起来很悦耳。", "explanation": "这里应该用〈听起来〉。“悦耳”说的是声音，要靠听来判断；看起来只用于说外表或样子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cfe41c9-c431-47c5-a836-2c5ec2a19f1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22794, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "尝起来", "is_correct": false, "explanation": "搭配：“尝起来”多用于食物的味道，不用来说饭馆干净与否。"}, {"text": "走起来", "is_correct": false, "explanation": "语义：“走起来”指行走时的感觉，与饭馆的干净不相干。"}, {"text": "跑起来", "is_correct": false, "explanation": "语义：“跑起来”指奔跑时的状态，与“很干净”的判断无关。"}, {"text": "看起来", "is_correct": true, "explanation": "“看起来”指根据外表判断饭馆给人的样子，与“很干净”相符。"}], "explanations": {"尝起来": "搭配：“尝起来”多用于食物的味道，不用来说饭馆干净与否。", "走起来": "语义：“走起来”指行走时的感觉，与饭馆的干净不相干。", "跑起来": "语义：“跑起来”指奔跑时的状态，与“很干净”的判断无关。", "看起来": "“看起来”指根据外表判断饭馆给人的样子，与“很干净”相符。"}, "sentence_index": 6, "correct_answer": "看起来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这段旋律看起来很动人。", "explanation": "这里应该用〈唱起来〉。判断旋律、歌声动不动人要用唱起来；看起来只用于外表或样子。"}, {"text": "这条鱼看起来很腥。", "explanation": "这里应该用〈吃起来〉。“腥”要靠嗅觉或味觉判断，应说吃起来；看起来不能用来判断气味。"}, {"text": "这台收音机看起来很响。", "explanation": "这里应该用〈听起来〉。判断声音响不响要用听起来；看起来只用于说外表或样子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cfe41c9-c431-47c5-a836-2c5ec2a19f1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22794, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这间屋子看起来了很干净，像是刚打扫过。", "corrected_sentence": "这间屋子看起来很干净，像是刚打扫过。", "error_description": "体标误用：“看起来”后不能加“了”，应说“这间屋子看起来很干净”，“了”误加在“看起来”后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cfe41c9-c431-47c5-a836-2c5ec2a19f1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22794, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈看起来了很开心，今天买了新衣服。", "corrected_sentence": "妈妈看起来很开心，今天买了新衣服。", "error_description": "体标误用：“看起来”后不能加“了”，应说“看起来很开心”，“了”误加在“看起来”后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cfe41c9-c431-47c5-a836-2c5ec2a19f1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
