INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22796, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "闭上眼睛休息，让身体和大脑休息。", "primary_collocate": null, "pronunciation": "shuì jiào", "ipa": "ʂweɪ̯˥˩ tɕiɑʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "睡觉可以让大脑好好休息。", "target_word": "睡觉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他闭上眼睛睡觉，想让身体休息一下。", "target_word": "睡觉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，睡觉对身体很重要。", "target_word": "睡觉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我想在家好好睡觉。", "target_word": "睡觉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "午饭后我太困了，想睡觉。", "target_word": "睡觉", "complexity_tier": "T3", "furigana": "shuì jiào", "sentence_source": "generated"}, {"text": "他晚上睡觉睡不好，白天就没有精神。", "target_word": "睡觉", "complexity_tier": "T3", "furigana": "shuì jiào", "sentence_source": "generated"}, {"text": "他睡觉的时候，大脑也在休息。", "target_word": "睡觉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上太吵，我没法睡觉。", "target_word": "睡觉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡觉前别喝咖啡，不然睡不好。", "target_word": "睡觉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她需要睡觉，让身体慢慢恢复。", "target_word": "睡觉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "睡了觉", "label": "离合形式"}, {"form": "睡一觉", "label": "离合形式"}, {"form": "睡个觉", "label": "离合形式"}, {"form": "睡觉了", "label": "体标"}], "register": "口语", "sense_fingerprint": "闭眼休息，让身体和大脑得到休息", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '083cdca7-e95f-4d69-a9ce-e0c89f00c055') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22796, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "睡觉", "is_correct": true, "explanation": "“睡觉”表示闭眼休息，让大脑得到休息，与句中的“休息”意思一致。"}, {"text": "工作", "is_correct": false, "explanation": "语义：工作会消耗精力，与“让大脑好好休息”的说法相反。"}, {"text": "生气", "is_correct": false, "explanation": "语义：生气会使大脑紧张，与“让大脑好好休息”的说法相反。"}, {"text": "考试", "is_correct": false, "explanation": "语义：“考试”会让大脑紧张，与“让大脑好好休息”的说法相反。"}], "explanations": {"睡觉": "“睡觉”表示闭眼休息，让大脑得到休息，与句中的“休息”意思一致。", "工作": "语义：工作会消耗精力，与“让大脑好好休息”的说法相反。", "生气": "语义：生气会使大脑紧张，与“让大脑好好休息”的说法相反。", "考试": "语义：“考试”会让大脑紧张，与“让大脑好好休息”的说法相反。"}, "sentence_index": 0, "correct_answer": "睡觉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一边吃饭，一边睡觉。", "explanation": "这里的〈睡觉〉表示闭眼休息，不能与“吃饭”同时进行；边吃边做的事应说〈工作〉之类的清醒活动，此句前后矛盾。"}, {"text": "他在操场上睡觉，比赛跑得很快。", "explanation": "这里应该用〈跑步〉。“睡觉”表示闭眼休息，与“比赛跑得很快”矛盾。"}, {"text": "我们一边散步，一边睡觉。", "explanation": "这里的〈睡觉〉表示闭眼休息，与边走边进行的清醒活动互相矛盾；应改用〈聊天〉之类能边走边做的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea446f59-d316-414f-b217-3d6539674177') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22796, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "睡觉", "is_correct": true, "explanation": "“睡觉”表示闭眼休息，与“他……的时候”搭配，指他睡着时大脑也在休息。"}, {"text": "思考", "is_correct": false, "explanation": "语义：思考需要大脑活动，与“大脑也在休息”的意思矛盾。"}, {"text": "吵架", "is_correct": false, "explanation": "语义：吵架让大脑非常活跃，与“大脑也在休息”矛盾。"}, {"text": "学习", "is_correct": false, "explanation": "语义：学习需要大脑持续工作，与“大脑也在休息”的意思矛盾。"}], "explanations": {"睡觉": "“睡觉”表示闭眼休息，与“他……的时候”搭配，指他睡着时大脑也在休息。", "思考": "语义：思考需要大脑活动，与“大脑也在休息”的意思矛盾。", "吵架": "语义：吵架让大脑非常活跃，与“大脑也在休息”矛盾。", "学习": "语义：学习需要大脑持续工作，与“大脑也在休息”的意思矛盾。"}, "sentence_index": 6, "correct_answer": "睡觉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她晚饭后出去睡觉，回来后洗了澡。", "explanation": "这里应该用〈散步〉。“睡觉”表示闭眼休息，不能说“出去睡觉”。"}, {"text": "他每天靠睡觉来锻炼身体。", "explanation": "这里应该用〈跑步〉。“睡觉”表示闭眼休息，不能作为锻炼身体的方式。"}, {"text": "她一边做饭，一边睡觉。", "explanation": "这里应该用〈唱歌〉。“睡觉”表示闭眼休息，不能与“做饭”同时进行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea446f59-d316-414f-b217-3d6539674177') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22796, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我午饭后睡觉了一觉。", "corrected_sentence": "我午饭后睡了一觉。", "error_description": "错误在于离合词“睡觉”的重复：“觉”已包含在“睡”中，后面不能再加“觉”。应为“睡了一觉”。正确句：“我午饭后睡了一觉。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea446f59-d316-414f-b217-3d6539674177') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22796, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她想睡了一下觉，恢复一下精神。", "corrected_sentence": "她想睡一下觉，恢复一下精神。", "error_description": "错误在于体标“了”的误用：“想”表示打算，后面的动作尚未发生，不能加“了”。应为“她想睡一下觉，恢复一下精神。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea446f59-d316-414f-b217-3d6539674177') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22798, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "精神", "is_correct": true, "explanation": "正确：困指想睡、没精神，精神指精力充沛，两者是反义关系。"}, {"text": "饿", "is_correct": false, "explanation": "与“困”无反义关系，饿指想吃东西。"}, {"text": "冷", "is_correct": false, "explanation": "与“困”无反义关系，冷指温度低。"}, {"text": "高兴", "is_correct": false, "explanation": "与“困”无反义关系，高兴指心情愉快。"}], "correct_answer": "精神", "explanations": {"精神": "正确：困指想睡、没精神，精神指精力充沛，两者是反义关系。", "饿": "与“困”无反义关系，饿指想吃东西。", "冷": "与“困”无反义关系，冷指温度低。", "高兴": "与“困”无反义关系，高兴指心情愉快。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cfad29-f526-4989-a5f1-bff446e93f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22798, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "清醒", "is_correct": true, "explanation": "正确：困指想睡，清醒指头脑清楚、不困，两者是反义关系。"}, {"text": "忙", "is_correct": false, "explanation": "与“困”无反义关系，忙指事情多、没有空闲。"}, {"text": "疼", "is_correct": false, "explanation": "与“困”无反义关系，疼指身体某部位感到痛。"}, {"text": "漂亮", "is_correct": false, "explanation": "与“困”无反义关系，漂亮指外表好看。"}], "correct_answer": "清醒", "explanations": {"清醒": "正确：困指想睡，清醒指头脑清楚、不困，两者是反义关系。", "忙": "与“困”无反义关系，忙指事情多、没有空闲。", "疼": "与“困”无反义关系，疼指身体某部位感到痛。", "漂亮": "与“困”无反义关系，漂亮指外表好看。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cfad29-f526-4989-a5f1-bff446e93f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22798, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "想睡觉，没有力气。", "primary_collocate": null, "pronunciation": "kùn", "ipa": "kʰuən˥˩", "syllable_count": 1, "sentences": [{"text": "吃完午饭，大家都觉得有点困。", "target_word": "困", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我昨晚只睡了四个小时，现在好困。", "target_word": "困", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听了半个小时的报告，他困极了。", "target_word": "困", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宝宝困了，一直在揉眼睛。", "target_word": "困", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你看起来很困，是不是没睡好？", "target_word": "困", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不困，还想再看一会儿书。", "target_word": "困", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开了一整天的车，他又累又困。", "target_word": "困", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气暖和的时候，人总是容易困。", "target_word": "困", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要是困了，就别再玩手机了。", "target_word": "困", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师讲课太慢，同学们都困了。", "target_word": "困", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "犯困", "label": "复合"}, {"form": "困倦", "label": "复合"}, {"form": "困意", "label": "复合"}], "register": "口语", "sense_fingerprint": "想睡觉且没力气的状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '411da9e4-51a0-498e-b4c5-a2af973994ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22798, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "困", "is_correct": true, "explanation": "正确：困，kùn（第四声），指想睡觉、没有力气。"}, {"text": "捆", "is_correct": false, "explanation": "kǔn（第三声）与 kùn（第四声）声调不同，意思是捆绑。"}, {"text": "混", "is_correct": false, "explanation": "hùn 与 kùn 声母不同（h 与 k），意思是混合。"}, {"text": "棍", "is_correct": false, "explanation": "gùn 与 kùn 声母不同（g 与 k），意思是棍子。"}, {"text": "肯", "is_correct": false, "explanation": "kěn 与 kùn 韵母和声调都不同（e 与 u），意思是愿意、肯定。"}], "explanations": {"困": "正确：困，kùn（第四声），指想睡觉、没有力气。", "捆": "kǔn（第三声）与 kùn（第四声）声调不同，意思是捆绑。", "混": "hùn 与 kùn 声母不同（h 与 k），意思是混合。", "棍": "gùn 与 kùn 声母不同（g 与 k），意思是棍子。", "肯": "kěn 与 kùn 韵母和声调都不同（e 与 u），意思是愿意、肯定。"}, "sentence_index": null, "correct_answer": "困"}, "level_3": {"options": [{"text": "困", "is_correct": true, "explanation": "正确：困指想睡觉、没有力气，符合吃完饭后的状态。"}, {"text": "漂亮", "is_correct": false, "explanation": "语义：“漂亮”形容外貌好看，用来说吃完饭后的感受不通，与句意不符。"}, {"text": "矮", "is_correct": false, "explanation": "语义：“矮”指身高或位置低，与吃完午饭后的感受无关。"}, {"text": "薄", "is_correct": false, "explanation": "语义：“薄”形容厚度小，不能用来说大家的感觉，句意不通。"}], "explanations": {"困": "正确：困指想睡觉、没有力气，符合吃完饭后的状态。", "漂亮": "语义：“漂亮”形容外貌好看，用来说吃完饭后的感受不通，与句意不符。", "矮": "语义：“矮”指身高或位置低，与吃完午饭后的感受无关。", "薄": "语义：“薄”形容厚度小，不能用来说大家的感觉，句意不通。"}, "sentence_index": 0, "correct_answer": "困"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道题太困了，我做不出来。", "explanation": "这里应该用〈难〉。困指想睡或没力气，不能用来形容题目难。"}, {"text": "听到这个好消息，他困得跳了起来。", "explanation": "这里应该用〈兴奋〉。困表示想睡、没精神，不能用来形容激动的情绪。"}, {"text": "听完这个笑话，大家都困得笑个不停。", "explanation": "这里应该用〈好笑〉。困指想睡、没力气，不能用来形容笑话让人发笑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cfad29-f526-4989-a5f1-bff446e93f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22798, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "困", "is_correct": true, "explanation": "正确：困，kùn（第四声），指想睡觉、没有力气。"}, {"text": "滚", "is_correct": false, "explanation": "gǔn（第三声）与 kùn（第四声）声母和声调都不同，意思是翻滚。"}, {"text": "看", "is_correct": false, "explanation": "kàn 与 kùn 韵母不同（a 与 u），意思是看见。"}, {"text": "顿", "is_correct": false, "explanation": "dùn 与 kùn 声母不同（d 与 k），意思是一顿（饭）。"}], "explanations": {"困": "正确：困，kùn（第四声），指想睡觉、没有力气。", "滚": "gǔn（第三声）与 kùn（第四声）声母和声调都不同，意思是翻滚。", "看": "kàn 与 kùn 韵母不同（a 与 u），意思是看见。", "顿": "dùn 与 kùn 声母不同（d 与 k），意思是一顿（饭）。"}, "sentence_index": null, "correct_answer": "困"}, "level_3": {"options": [{"text": "困", "is_correct": true, "explanation": "正确：困指想睡觉、没有力气，与“又累又”的语境相符。"}, {"text": "醉", "is_correct": false, "explanation": "语义：开了一整天的车，司机不能处于醉酒状态，与“开车”的语境冲突。"}, {"text": "亮", "is_correct": false, "explanation": "搭配：“亮”形容光线或颜色，不用来形容人的身体状态。"}, {"text": "厚", "is_correct": false, "explanation": "搭配：“厚”形容物体的厚度，不能用来形容人。"}], "explanations": {"困": "正确：困指想睡觉、没有力气，与“又累又”的语境相符。", "醉": "语义：开了一整天的车，司机不能处于醉酒状态，与“开车”的语境冲突。", "亮": "搭配：“亮”形容光线或颜色，不用来形容人的身体状态。", "厚": "搭配：“厚”形容物体的厚度，不能用来形容人。"}, "sentence_index": 6, "correct_answer": "困"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他听完批评，困得把门摔上了。", "explanation": "这里应该用〈生气〉。困指想睡、没精神，不能用来表示发脾气。"}, {"text": "她在台上困得脸都红了。", "explanation": "这里应该用〈害羞〉。困指想睡觉，与脸红的情绪无关。"}, {"text": "考试前，他困得手心直冒汗。", "explanation": "这里应该用〈紧张〉。困不表示焦虑，也不会引起出汗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cfad29-f526-4989-a5f1-bff446e93f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22798, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹妹困着了，靠在沙发上睡着了。", "corrected_sentence": "妹妹困了，靠在沙发上睡着了。", "error_description": "错误形式：“困着了”；正确形式：“困了”。表示状态出现要用“了”，不能用“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cfad29-f526-4989-a5f1-bff446e93f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22798, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他困地要死，趴在桌上睡着了。", "corrected_sentence": "他困得要死，趴在桌上睡着了。", "error_description": "错误形式：“困地要死”；正确形式：“困得要死”。“地”用于动词前修饰动作，“困”后接程度补语要用“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cfad29-f526-4989-a5f1-bff446e93f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
