INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22800, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西讲清楚，让别人明白。", "primary_collocate": null, "pronunciation": "shuō míng", "ipa": "ʂwo˥ miŋ˧˥", "syllable_count": 2, "sentences": [{"text": "老师向我们说明了考试的时间。", "target_word": "说明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你说明一下这个词怎么用。", "target_word": "说明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没说明为什么不来。", "target_word": "说明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板把工作的要求向大家说明了。", "target_word": "说明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想向你说明一下当时的情况。", "target_word": "说明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用一个小例子说明了这个词的用法。", "target_word": "说明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先说明你的问题，再问老师。", "target_word": "说明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导游说明了参观的路线。", "target_word": "说明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说明了迟到的原因，老师就没生气。", "target_word": "说明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你得向客人说明这个菜怎么吃。", "target_word": "说明", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "说明了", "label": "体标"}, {"form": "说明过", "label": "体标"}, {"form": "说明说明", "label": "重叠"}], "register": "中性", "sense_fingerprint": "把情况、用法、原因等讲清楚，让别人明白", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0206ebc3-9f0d-4d6a-8d06-0de5f27ec0c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22800, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "说明", "is_correct": true, "explanation": "正确：“向我们说明了考试的时间”表示把时间讲清楚，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，“老师向我们吃了考试的时间”不通。"}, {"text": "认为", "is_correct": false, "explanation": "配价：“认为”后接的是观点或小句，不能接“考试的时间”这样的名词宾语。"}, {"text": "挂", "is_correct": false, "explanation": "搭配：“挂”不能与“考试的时间”搭配，不能用来传达信息。"}], "explanations": {"说明": "正确：“向我们说明了考试的时间”表示把时间讲清楚，符合句意。", "吃": "语义：“吃”指进食，“老师向我们吃了考试的时间”不通。", "认为": "配价：“认为”后接的是观点或小句，不能接“考试的时间”这样的名词宾语。", "挂": "搭配：“挂”不能与“考试的时间”搭配，不能用来传达信息。"}, "sentence_index": 0, "correct_answer": "说明"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她说明了一首好听的歌。", "explanation": "这里应该用〈唱〉。“说明”的宾语是道理、情况、方法，不能是歌曲；唱歌要用“唱”。"}, {"text": "他说明了一双新鞋。", "explanation": "这里应该用〈买〉。“说明”的宾语是道理、情况、方法，不能是鞋子这类物品；买东西要用“买”。"}, {"text": "妈妈用糖果说明了弟弟，弟弟就不哭了。", "explanation": "这里应该用〈哄〉。“说明”是讲清道理，不能用糖果去“说明”人；哄人不哭要用“哄”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f66d64-b0b4-42ac-a4f3-dce521f26445') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22800, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "说明", "is_correct": true, "explanation": "正确：“请先说明你的问题”表示先把问题讲清楚，再去提问，符合句意。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指歌唱，“请先唱你的问题”与句意不符。"}, {"text": "打", "is_correct": false, "explanation": "搭配：“打”不能与“问题”搭配，“打你的问题”句子不成立。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，不能带“你的问题”作宾语。"}], "explanations": {"说明": "正确：“请先说明你的问题”表示先把问题讲清楚，再去提问，符合句意。", "唱": "语义：“唱”指歌唱，“请先唱你的问题”与句意不符。", "打": "搭配：“打”不能与“问题”搭配，“打你的问题”句子不成立。", "睡": "配价：“睡”是不及物动词，不能带“你的问题”作宾语。"}, "sentence_index": 6, "correct_answer": "说明"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他说明了一个很有趣的笑话。", "explanation": "这里应该用〈讲〉。“说明”的宾语是道理、情况、方法，不能是笑话；讲笑话要用“讲”。"}, {"text": "妈妈说明我别忘带伞。", "explanation": "这里应该用〈提醒〉。“说明”是讲清道理、情况，提醒别人注意某件事要用“提醒”。"}, {"text": "他说明了一场很精彩的电影。", "explanation": "这里应该用〈看〉。“说明”的宾语是道理、情况、方法，不能是电影；看电影要用“看”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f66d64-b0b4-42ac-a4f3-dce521f26445') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22800, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我他说明了这个用法。", "corrected_sentence": "我向他说明了这个用法。", "error_description": "错误：介词“向”漏掉了，“他”变成了多余的成分。正确：“向他说明了这个用法”，要用介词“向”引出说明的对象。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f66d64-b0b4-42ac-a4f3-dce521f26445') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22800, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个步骤我已经说明很清楚了。", "corrected_sentence": "这个步骤我已经说明得很清楚了。", "error_description": "错误：“说明”后缺少补语标记“得”。正确：“说明得很清楚”，“得”引出补语，不能省略。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f66d64-b0b4-42ac-a4f3-dce521f26445') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
