INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22802, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "原因就是为什么事情会发生。", "primary_collocate": null, "pronunciation": "yuán yīn", "ipa": "ɥɛn˧˥ in˥", "syllable_count": 2, "sentences": [{"text": "你知道他迟到的原因吗？", "target_word": "原因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事故的原因还不清楚。", "target_word": "原因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没来，一定有原因。", "target_word": "原因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问我为什么哭，我说不出原因。", "target_word": "原因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气是比赛取消的原因。", "target_word": "原因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡不好有很多原因。", "target_word": "原因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生正在找生病的原因。", "target_word": "原因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个原因很简单，他太累了。", "target_word": "原因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出于健康原因，他不再喝酒了。", "target_word": "原因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请告诉我你选择这里的原因。", "target_word": "原因", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "种", "label": "量词"}, {"form": "原因分析", "label": "复合"}], "register": "中性", "sense_fingerprint": "事情发生的理由", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b76edc4-0981-45f9-b40b-13826adb3d03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22802, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "原因", "is_correct": true, "explanation": "正确：“原因”指事情发生的缘由，“他迟到的原因”正合句意。"}, {"text": "地点", "is_correct": false, "explanation": "语义：“地点”指场所，“迟到”说的是晚到，不能说“迟到的地点”。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”与迟到无关，句子问的是他迟到的缘故，句意不通。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”指岁数，与迟到无关，句意不通。"}], "explanations": {"原因": "正确：“原因”指事情发生的缘由，“他迟到的原因”正合句意。", "地点": "语义：“地点”指场所，“迟到”说的是晚到，不能说“迟到的地点”。", "颜色": "语义：“颜色”与迟到无关，句子问的是他迟到的缘故，句意不通。", "年龄": "语义：“年龄”指岁数，与迟到无关，句意不通。"}, "sentence_index": 0, "correct_answer": "原因"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次实验的原因很理想。", "explanation": "这里应该用〈结果〉。“理想”用来评价结果，原因说的是引起事情的缘由，不能用来评价好坏。"}, {"text": "考试的原因是带身份证。", "explanation": "这里应该用〈条件〉。“带身份证”是必须具备的前提，原因指已经发生的事情的缘由。"}, {"text": "他想到了一个解决问题的原因。", "explanation": "这里应该用〈方法〉。“解决问题的方法”指做事的办法，原因说明事情为何发生，不能指办法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7df9bc8-1bcf-43c8-be31-eb6336a223a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22802, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "原因", "is_correct": true, "explanation": "正确：“原因”指致病的缘由，“找生病的原因”正合句意。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”指价钱，医生要找的是致病的缘由，不是价钱。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”指滋味或气味，与寻找致病的缘由没有关系。"}, {"text": "声音", "is_correct": false, "explanation": "语义：“声音”是听觉对象，不能作为“生病的”所指的病因，句子不通。"}], "explanations": {"原因": "正确：“原因”指致病的缘由，“找生病的原因”正合句意。", "价格": "语义：“价格”指价钱，医生要找的是致病的缘由，不是价钱。", "味道": "语义：“味道”指滋味或气味，与寻找致病的缘由没有关系。", "声音": "语义：“声音”是听觉对象，不能作为“生病的”所指的病因，句子不通。"}, "sentence_index": 6, "correct_answer": "原因"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他没来，一定有一座原因。", "explanation": "这里应该用〈个〉。“座”用于山、房屋等大型固定的物体，不能用来量抽象的原因。"}, {"text": "她迟到的一条原因是堵车。", "explanation": "这里应该用〈个〉。“条”用于细长的物体，不能用来量原因。"}, {"text": "我们有一台原因需要讨论。", "explanation": "这里应该用〈个〉。“台”用于机器、演出等，不能用来量原因。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7df9bc8-1bcf-43c8-be31-eb6336a223a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22802, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想知道他迟到原因。", "corrected_sentence": "我想知道他迟到的原因。", "error_description": "“原因”前面是修饰语“迟到”，中间要加“的”，应说“他迟到的原因”。漏掉“的”，说“他迟到原因”不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7df9bc8-1bcf-43c8-be31-eb6336a223a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22802, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这原因我们还不清楚。", "corrected_sentence": "这个原因我们还不清楚。", "error_description": "指示词“这”后面要加量词，应说“这个原因”。直接说“这原因”不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7df9bc8-1bcf-43c8-be31-eb6336a223a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22804, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "睡觉", "is_correct": true, "explanation": "正确：“起床”指睡醒后从床上起来，“睡觉”指入睡躺下，二者意思相反。"}, {"text": "刷牙", "is_correct": false, "explanation": "无反义关系：“刷牙”是起床后的活动，与“起床”不是相对的意义。"}, {"text": "吃早饭", "is_correct": false, "explanation": "无反义关系：“吃早饭”是起床之后的事，与“起床”并不相对。"}, {"text": "出门", "is_correct": false, "explanation": "无反义关系：“出门”是起床后的行动，与“起床”不构成反义。"}], "correct_answer": "睡觉", "explanations": {"睡觉": "正确：“起床”指睡醒后从床上起来，“睡觉”指入睡躺下，二者意思相反。", "刷牙": "无反义关系：“刷牙”是起床后的活动，与“起床”不是相对的意义。", "吃早饭": "无反义关系：“吃早饭”是起床之后的事，与“起床”并不相对。", "出门": "无反义关系：“出门”是起床后的行动，与“起床”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f66d64-b0b4-42ac-a4f3-dce521f26445') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22804, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "睡觉", "is_correct": true, "explanation": "正确：“起床”指睡醒后从床上起来，“睡觉”指入睡躺下，二者意思相反。"}, {"text": "写字", "is_correct": false, "explanation": "无反义关系：“写字”与“起床”没有相对的意义关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "无反义关系：“唱歌”是一种活动，与“起床”并不构成反义。"}, {"text": "打球", "is_correct": false, "explanation": "无反义关系：“打球”是一种运动，与“起床”不是相对的意义。"}], "correct_answer": "睡觉", "explanations": {"睡觉": "正确：“起床”指睡醒后从床上起来，“睡觉”指入睡躺下，二者意思相反。", "写字": "无反义关系：“写字”与“起床”没有相对的意义关系。", "唱歌": "无反义关系：“唱歌”是一种活动，与“起床”并不构成反义。", "打球": "无反义关系：“打球”是一种运动，与“起床”不是相对的意义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f66d64-b0b4-42ac-a4f3-dce521f26445') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22804, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "睡醒后从床上起来。", "primary_collocate": null, "pronunciation": "qǐ chuáng", "ipa": "tɕʰi˨˩ ʈʂʰwaŋ˧˥", "syllable_count": 2, "sentences": [{"text": "明天有考试，我要六点起床。", "target_word": "起床", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸起床以后先看报纸。", "target_word": "起床", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳出来了，快起床吧。", "target_word": "起床", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你每天几点起床？", "target_word": "起床", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "星期天他十点才起床。", "target_word": "起床", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我起床后马上刷牙洗脸。", "target_word": "起床", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她病好了，今天能自己起床了。", "target_word": "起床", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥每天都比我早起床。", "target_word": "起床", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到电话响，他马上起床去开门。", "target_word": "起床", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们六点半起床，七点吃早饭。", "target_word": "起床", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "起床了", "label": "体标"}, {"form": "起床气", "label": "复合"}], "register": "中性", "sense_fingerprint": "睡醒后从床上起来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0206ebc3-9f0d-4d6a-8d06-0de5f27ec0c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22804, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "起床", "is_correct": true, "explanation": "正确：“明天有考试，我要六点起床”，指早上醒来离开床铺，符合语境。"}, {"text": "放假", "is_correct": false, "explanation": "语义：“放假”指假期开始，不能指某个钟点，句意不通。"}, {"text": "交卷", "is_correct": false, "explanation": "搭配：“交卷”是考试结束时的动作，不能与“明天”提前说的“六点”搭配。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：“结婚”与“明天有考试”的语境矛盾，句意不合。"}], "explanations": {"起床": "正确：“明天有考试，我要六点起床”，指早上醒来离开床铺，符合语境。", "放假": "语义：“放假”指假期开始，不能指某个钟点，句意不通。", "交卷": "搭配：“交卷”是考试结束时的动作，不能与“明天”提前说的“六点”搭配。", "结婚": "语义：“结婚”与“明天有考试”的语境矛盾，句意不合。"}, "sentence_index": 0, "correct_answer": "起床"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他醒来后在床上起床，揉了揉眼睛。", "explanation": "这里应该用〈坐起〉。“起床”指离开床铺，只是在床上坐起来要用“坐起”。"}, {"text": "火车到站了，大家纷纷起床下车。", "explanation": "这里应该用〈下车〉。“起床”只指睡醒后离开床铺，从车上离开要用“下车”。"}, {"text": "妈妈每天晚上九点就催我起床。", "explanation": "这里应该用〈上床〉。“起床”指早上醒来离开床铺，晚上要睡觉时应说“上床”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f66d64-b0b4-42ac-a4f3-dce521f26445') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22804, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "起床", "is_correct": true, "explanation": "正确：“她病好了，今天能自己起床了”，表示病好后能离开床铺，符合句意。"}, {"text": "住院", "is_correct": false, "explanation": "语义：“住院”表示因病入院治疗，与“病好了”矛盾，句意不通。"}, {"text": "送", "is_correct": false, "explanation": "配价：“送”需要宾语（送给谁或送什么），“能自己送了”缺少宾语，不成立。"}, {"text": "生病", "is_correct": false, "explanation": "语义：“生病”与“病好了”直接矛盾，句意不合。"}], "explanations": {"起床": "正确：“她病好了，今天能自己起床了”，表示病好后能离开床铺，符合句意。", "住院": "语义：“住院”表示因病入院治疗，与“病好了”矛盾，句意不通。", "送": "配价：“送”需要宾语（送给谁或送什么），“能自己送了”缺少宾语，不成立。", "生病": "语义：“生病”与“病好了”直接矛盾，句意不合。"}, "sentence_index": 6, "correct_answer": "起床"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "听到老师叫名字，他马上起床回答问题。", "explanation": "这里应该用〈站起〉。“起床”指离开床铺，在座位上听到叫名字后站起来要用“站起”。"}, {"text": "他摔倒在地上，过了一会儿才起床。", "explanation": "这里应该用〈爬起〉。摔倒后从地上重新站起来要用“爬起”，“起床”只指离开床铺。"}, {"text": "他坐在办公室里，突然起床去开会。", "explanation": "这里应该用〈起身〉。“起床”指离开床铺，从椅子上站起来要用“起身”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f66d64-b0b4-42ac-a4f3-dce521f26445') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22804, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我每天七点了起床。", "corrected_sentence": "我每天七点起床。", "error_description": "错误：“了”不能放在“起床”之前。正确：“每天七点起床”，句中不需要“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f66d64-b0b4-42ac-a4f3-dce521f26445') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22804, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一般八点才了起床。", "corrected_sentence": "他一般八点才起床。", "error_description": "错误：“了”不能放在副词“才”之后、动词“起床”之前。正确：“八点才起床”，句中不需要“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f66d64-b0b4-42ac-a4f3-dce521f26445') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
