INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22806, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "身体各部分做的事情，比如呼吸、心跳。", "primary_collocate": null, "pronunciation": "shēng lǐ gōng néng", "ipa": "ʂəŋ˥ li˨˩ kʊŋ˥ nɤŋ˧˥", "syllable_count": 4, "sentences": [{"text": "呼吸是我们最基本的生理功能之一。", "target_word": "生理功能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "睡眠不足会影响人的生理功能。", "target_word": "生理功能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "出汗也是一种生理功能。", "target_word": "生理功能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子的生理功能还没有发育完全。", "target_word": "生理功能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "心脏有让血液流动的生理功能。", "target_word": "生理功能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人的生理功能比年轻人差一些。", "target_word": "生理功能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他受伤以后，一些生理功能受到了影响。", "target_word": "生理功能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃饭、喝水都和身体的生理功能有关。", "target_word": "生理功能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说他的生理功能很正常。", "target_word": "生理功能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要多运动，保护好身体的生理功能。", "target_word": "生理功能", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "项", "label": "量词"}, {"form": "生理现象", "label": "复合"}, {"form": "生理需求", "label": "复合"}], "register": "书面", "sense_fingerprint": "身体各部分的作用如呼吸心跳", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '411da9e4-51a0-498e-b4c5-a2af973994ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22806, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生理功能", "is_correct": true, "explanation": "正确：生理功能指身体各部分的作用，如呼吸、心跳，符合句意。"}, {"text": "语言", "is_correct": false, "explanation": "语义：呼吸不是语言，句意不通。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：呼吸不是乐器，与句意不符。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：饮料是可以喝的东西，呼吸不是饮料，句意不通。"}], "explanations": {"生理功能": "正确：生理功能指身体各部分的作用，如呼吸、心跳，符合句意。", "语言": "语义：呼吸不是语言，句意不通。", "乐器": "语义：呼吸不是乐器，与句意不符。", "饮料": "语义：饮料是可以喝的东西，呼吸不是饮料，句意不通。"}, "sentence_index": 0, "correct_answer": "生理功能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "心脏是人体最重要的生理功能。", "explanation": "这里应该用〈器官〉。生理功能指作用，不是身体部位，心脏是器官。"}, {"text": "早睡早起是一个好生理功能。", "explanation": "这里应该用〈习惯〉。生理功能指身体的作用，不能用来说生活习惯。"}, {"text": "这份合同的生理功能很完善。", "explanation": "这里应该用〈条款〉。生理功能只指生物体的作用，合同没有生理功能，应说条款完善。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cfad29-f526-4989-a5f1-bff446e93f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22806, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生理功能", "is_correct": true, "explanation": "正确：生理功能指身体各部分的作用，受伤后会受到影响，符合句意。"}, {"text": "天气", "is_correct": false, "explanation": "语义：一个人受伤不会影响天气，句意不通。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是建筑构件，不是身体的功能，受伤后不会影响窗户，句意不通。"}, {"text": "天空", "is_correct": false, "explanation": "语义：一个人受伤不会影响天空，句意冲突。"}], "explanations": {"生理功能": "正确：生理功能指身体各部分的作用，受伤后会受到影响，符合句意。", "天气": "语义：一个人受伤不会影响天气，句意不通。", "窗户": "语义：窗户是建筑构件，不是身体的功能，受伤后不会影响窗户，句意不通。", "天空": "语义：一个人受伤不会影响天空，句意冲突。"}, "sentence_index": 6, "correct_answer": "生理功能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这套房子的生理功能很完善。", "explanation": "这里应该用〈用途〉。生理功能只指生物体的作用，房子没有生理功能，说房子的用途才合适。"}, {"text": "数学是一门重要的生理功能。", "explanation": "这里应该用〈学科〉。生理功能指生物体的作用，数学不能用它来说。"}, {"text": "这部小说是一部优秀的生理功能。", "explanation": "这里应该用〈作品〉。小说不是生物体，不能说生理功能。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cfad29-f526-4989-a5f1-bff446e93f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22806, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "呼吸和消化都属于人体地生理功能。", "corrected_sentence": "呼吸和消化都属于人体的生理功能。", "error_description": "错误形式：“人体地生理功能”；正确形式：“人体的生理功能”。“地”用于修饰动词或形容词，修饰名词“生理功能”时应用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cfad29-f526-4989-a5f1-bff446e93f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22806, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的各种生理功能们都在慢慢恢复。", "corrected_sentence": "他的各种生理功能都在慢慢恢复。", "error_description": "错误形式：“生理功能们”；正确形式：“生理功能”。“生理功能”是抽象名词，不能加“们”表示复数，“各种”已经表示多样。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cfad29-f526-4989-a5f1-bff446e93f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
