INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22814, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "信号是告诉我们要做什么事情的消息或记号。", "primary_collocate": null, "pronunciation": "xìn hào", "ipa": "ɕin⁵¹ xaʊ⁵¹", "syllable_count": 2, "sentences": [{"text": "红灯亮了，这是让车停下来的信号。", "target_word": "信号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师举起手，这是请大家安静的信号。", "target_word": "信号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哨声一响，这就是比赛开始的信号。", "target_word": "信号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船上的人用旗子发出求救信号。", "target_word": "信号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他点点头，给了我们出发的信号。", "target_word": "信号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察用手做出停车的信号。", "target_word": "信号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "绿灯是可以走的信号。", "target_word": "信号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "铃声是下课的信号。", "target_word": "信号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他眨了眨眼睛，给我一个信号。", "target_word": "信号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到信号，司机慢慢把车停下来。", "target_word": "信号", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个信号", "label": "量词"}, {"form": "信号灯", "label": "复合"}, {"form": "信号弹", "label": "复合"}], "register": "中性", "sense_fingerprint": "用声音、灯光、动作等传达行动指示的消息或记号", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f995feb-01f2-46a0-bd0f-015ea5999b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22814, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "信号", "is_correct": true, "explanation": "正确：“让车停下来的信号”指传达行动指示的记号，与红灯的语境相符。"}, {"text": "食物", "is_correct": false, "explanation": "语义：食物不是传达行动指示的记号，不能让车停下来。"}, {"text": "螺丝", "is_correct": false, "explanation": "搭配：“让车停下来的”修饰螺丝不搭配，螺丝不是指示行动的记号。"}, {"text": "歌谣", "is_correct": false, "explanation": "语义：歌谣是口头作品，不能作为让车停下的指示。"}], "explanations": {"信号": "正确：“让车停下来的信号”指传达行动指示的记号，与红灯的语境相符。", "食物": "语义：食物不是传达行动指示的记号，不能让车停下来。", "螺丝": "搭配：“让车停下来的”修饰螺丝不搭配，螺丝不是指示行动的记号。", "歌谣": "语义：歌谣是口头作品，不能作为让车停下的指示。"}, "sentence_index": 0, "correct_answer": "信号"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一口气吃掉了那个信号。", "explanation": "这里应该用〈饼干〉。信号是传达行动指示的消息或记号，不能被吃掉，应说〈饼干〉。"}, {"text": "工人把信号铺在了客厅里。", "explanation": "这里应该用〈地毯〉。信号是传达行动指示的消息或记号，不能铺在地上，应说〈地毯〉。"}, {"text": "他用信号炒了一盘菜。", "explanation": "这里应该用〈青椒〉。信号是消息或记号，不能当作食材炒菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c895ac1-e207-45a0-ac6b-c297a5c07b84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22814, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "信号", "is_correct": true, "explanation": "正确：绿灯是允许行走的记号，“可以走的信号”与语境相符。"}, {"text": "作业", "is_correct": false, "explanation": "语义：“作业”是学习任务，不是交通指示，“可以走的作业”不通。"}, {"text": "数字", "is_correct": false, "explanation": "语义：数字不是传达行动指示的记号，不能表示“可以走”。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材描述人的形体，不能说“可以走的身材”。"}], "explanations": {"信号": "正确：绿灯是允许行走的记号，“可以走的信号”与语境相符。", "作业": "语义：“作业”是学习任务，不是交通指示，“可以走的作业”不通。", "数字": "语义：数字不是传达行动指示的记号，不能表示“可以走”。", "身材": "体貌：身材描述人的形体，不能说“可以走的身材”。"}, "sentence_index": 6, "correct_answer": "信号"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他撑开了那个信号，走进了雨里。", "explanation": "这里应该用〈伞〉。撑开的是伞，信号是传达行动指示的消息或记号，不能撑开。"}, {"text": "他拿出那个信号打开了门。", "explanation": "这里应该用〈钥匙〉。打开门要用钥匙，信号是消息或记号，不能用来开门。"}, {"text": "妈妈织了一个信号送给我。", "explanation": "这里应该用〈毛衣〉。织的是毛衣，信号是消息或记号，不能织。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c895ac1-e207-45a0-ac6b-c297a5c07b84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22814, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这一只信号很清楚，司机都看见了。", "corrected_sentence": "这一个信号很清楚，司机都看见了。", "error_description": "量词“只”多用于动物或成对器物之一，信号应用“个”或“种”，此处应为“这一个信号”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c895ac1-e207-45a0-ac6b-c297a5c07b84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22814, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一座明确的信号。", "corrected_sentence": "这是一种明确的信号。", "error_description": "量词“座”用于山、楼房等大型固定物，信号应用“种”或“个”，此处应为“一种明确的信号”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c895ac1-e207-45a0-ac6b-c297a5c07b84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
