INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22816, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让人看到。", "primary_collocate": null, "pronunciation": "xiǎn shì", "ipa": "ɕiɛn˨˩˦ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "手机屏幕上显示现在是三点。", "target_word": "显示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个数字显示天气会变冷。", "target_word": "显示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电脑显示我的密码错了。", "target_word": "显示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上显示前面有一家医院。", "target_word": "显示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试成绩显示他学得很好。", "target_word": "显示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屏幕上显示着一行红字。", "target_word": "显示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张表显示今年的人数更多了。", "target_word": "显示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电梯里的灯显示我们在五楼。", "target_word": "显示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的笑容显示他很满意。", "target_word": "显示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器上显示出一个大大的“好”字。", "target_word": "显示", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "显示了", "label": "体标（了）"}, {"form": "显示着", "label": "体标（着）"}, {"form": "显示出", "label": "补语"}, {"form": "显示器", "label": "复合"}], "register": "中性", "sense_fingerprint": "动词，屏幕、数据、表格等把信息或情况明显地表现出来让人看见", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca85f957-df35-4d8f-af57-1db695739dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22816, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "显示", "is_correct": true, "explanation": "正确答案：显示 xiǎn shì，让人看到信息或情况。"}, {"text": "现实", "is_correct": false, "explanation": "现实 xiàn shí 与 显示 xiǎn shì 两个音节的声调都不同，意思是客观存在的情况。"}, {"text": "小事", "is_correct": false, "explanation": "小事 xiǎo shì 第一个音节韵母不同（xiǎo 与 xiǎn），意思是小的事情。"}, {"text": "闲事", "is_correct": false, "explanation": "闲事 xián shì 第一个音节声调不同（xián 与 xiǎn），意思是与自己无关的事。"}], "explanations": {"显示": "正确答案：显示 xiǎn shì，让人看到信息或情况。", "现实": "现实 xiàn shí 与 显示 xiǎn shì 两个音节的声调都不同，意思是客观存在的情况。", "小事": "小事 xiǎo shì 第一个音节韵母不同（xiǎo 与 xiǎn），意思是小的事情。", "闲事": "闲事 xián shì 第一个音节声调不同（xián 与 xiǎn），意思是与自己无关的事。"}, "sentence_index": null, "correct_answer": "显示"}, "level_3": {"options": [{"text": "显示", "is_correct": true, "explanation": "正确：“屏幕上显示”指让人看到信息，符合句子的语境。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：屏幕不能唱歌，“屏幕上唱歌现在是三点”说不通。"}, {"text": "散步", "is_correct": false, "explanation": "配价：“散步”是不及物动词，不能带“现在是三点”作宾语，也与屏幕不搭。"}, {"text": "生长", "is_correct": false, "explanation": "搭配：“生长”不能用于屏幕，屏幕不会生长。"}], "explanations": {"显示": "正确：“屏幕上显示”指让人看到信息，符合句子的语境。", "唱歌": "语义：屏幕不能唱歌，“屏幕上唱歌现在是三点”说不通。", "散步": "配价：“散步”是不及物动词，不能带“现在是三点”作宾语，也与屏幕不搭。", "生长": "搭配：“生长”不能用于屏幕，屏幕不会生长。"}, "sentence_index": 0, "correct_answer": "显示"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "博物馆正在显示一批古画。", "explanation": "这里应该用〈展示〉。显示多指通过屏幕或仪表让人看到信息和情况，展示古画等作品要用〈展示〉。"}, {"text": "这个孩子显示了很多朋友。", "explanation": "这里应该用〈有〉。显示指让人看到信息或情况，朋友是人，不能用“显示”，应说“有很多朋友”。"}, {"text": "妈妈每天在厨房里显示很多饭菜。", "explanation": "这里应该用〈做〉。显示指让人看到信息或情况，饭菜是要做出来的实物，应说“做很多饭菜”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c290b81d-0dcb-45a5-b379-91fe24a99a2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22816, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "显示", "is_correct": true, "explanation": "正确答案：显示 xiǎn shì，让人看到信息或情况。"}, {"text": "限时", "is_correct": false, "explanation": "限时 xiàn shí 与 显示 xiǎn shì 两个音节的声调都不同，意思是限定时间。"}, {"text": "现世", "is_correct": false, "explanation": "现世 xiàn shì 第一个音节声调不同（xiàn 与 xiǎn），意思是现在的世界。"}, {"text": "小试", "is_correct": false, "explanation": "小试 xiǎo shì 第一个音节韵母不同（xiǎo 与 xiǎn），意思是稍微试一下。"}], "explanations": {"显示": "正确答案：显示 xiǎn shì，让人看到信息或情况。", "限时": "限时 xiàn shí 与 显示 xiǎn shì 两个音节的声调都不同，意思是限定时间。", "现世": "现世 xiàn shì 第一个音节声调不同（xiàn 与 xiǎn），意思是现在的世界。", "小试": "小试 xiǎo shì 第一个音节韵母不同（xiǎo 与 xiǎn），意思是稍微试一下。"}, "sentence_index": null, "correct_answer": "显示"}, "level_3": {"options": [{"text": "显示", "is_correct": true, "explanation": "正确：“这张表显示”指用表格让人看到信息，符合句子的语境。"}, {"text": "哭泣", "is_correct": false, "explanation": "语义：表格不会哭泣，“这张表哭泣今年的人数”说不通。"}, {"text": "跳舞", "is_correct": false, "explanation": "搭配：“跳舞”不能用于表格，表格不能跳舞。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：表格不会游泳，句子所说的是人数。"}], "explanations": {"显示": "正确：“这张表显示”指用表格让人看到信息，符合句子的语境。", "哭泣": "语义：表格不会哭泣，“这张表哭泣今年的人数”说不通。", "跳舞": "搭配：“跳舞”不能用于表格，表格不能跳舞。", "游泳": "语义：表格不会游泳，句子所说的是人数。"}, "sentence_index": 6, "correct_answer": "显示"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个人显示了很多工作。", "explanation": "这里应该用〈完成〉。显示指让人看到信息或情况，工作是要做完的事，应说“完成很多工作”。"}, {"text": "他的成绩显示了很多钱。", "explanation": "这里应该用〈赚〉。显示用于信息或水平，钱是挣来的，应说“赚了很多钱”。"}, {"text": "他的脚上显示了一个大大的“好”字。", "explanation": "这里“显示”需要屏幕、仪器等载体呈现信息，脚上不能“显示”字，应改用“写”或“画”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c290b81d-0dcb-45a5-b379-91fe24a99a2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
