INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22820, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "累了，想休息。", "primary_collocate": null, "pronunciation": "pí láo", "ipa": "pʰi˧˥ lɑʊ˧˥", "syllable_count": 2, "sentences": [{"text": "我今天太疲劳了，想早点睡。", "target_word": "疲劳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "走了一天路，大家都很疲劳。", "target_word": "疲劳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他看上去很疲劳，应该回家休息。", "target_word": "疲劳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子写完作业，觉得有点疲劳。", "target_word": "疲劳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你疲劳的话，就坐下来休息一会儿。", "target_word": "疲劳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "跑完步以后，我感到很疲劳。", "target_word": "疲劳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈做了一天饭，十分疲劳。", "target_word": "疲劳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他打着哈欠说自己很疲劳。", "target_word": "疲劳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我太疲劳了，不想再看电视了。", "target_word": "疲劳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟玩得很疲劳，躺在沙发上睡着了。", "target_word": "疲劳", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "疲勞", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人累了、想要休息", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b10fc90c-0e14-449a-94f1-3095b8172350') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22820, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "疲劳", "is_correct": true, "explanation": "正确答案。疲劳指累了，想休息。"}, {"text": "皮毛", "is_correct": false, "explanation": "máo（第二声）与 láo（第二声）声母不同（m 与 l），意思是皮毛，不是累。"}, {"text": "皮薄", "is_correct": false, "explanation": "báo（第二声）与 láo 声母不同（b 与 l），意思是皮很薄，不是累。"}, {"text": "皮袍", "is_correct": false, "explanation": "páo（第二声）与 láo 声母不同（p 与 l），意思是毛皮做的长衣，不是累。"}], "explanations": {"疲劳": "正确答案。疲劳指累了，想休息。", "皮毛": "máo（第二声）与 láo（第二声）声母不同（m 与 l），意思是皮毛，不是累。", "皮薄": "báo（第二声）与 láo 声母不同（b 与 l），意思是皮很薄，不是累。", "皮袍": "páo（第二声）与 láo 声母不同（p 与 l），意思是毛皮做的长衣，不是累。"}, "sentence_index": null, "correct_answer": "疲劳"}, "level_3": {"options": [{"text": "疲劳", "is_correct": true, "explanation": "正确答案。“太疲劳了，想早点睡”表示累了想休息，与句意相符。"}, {"text": "精神", "is_correct": false, "explanation": "语义：“太精神了”说明精力旺盛，与“想早点睡”矛盾。"}, {"text": "清醒", "is_correct": false, "explanation": "语义：“太清醒了”与“想早点睡”矛盾，人清醒时不会想睡觉。"}, {"text": "充足", "is_correct": false, "explanation": "搭配：「充足」多修饰睡眠、精力、水分等；「太充足了」表示精力足、不累，与「想早点睡」矛盾。"}], "explanations": {"疲劳": "正确答案。“太疲劳了，想早点睡”表示累了想休息，与句意相符。", "精神": "语义：“太精神了”说明精力旺盛，与“想早点睡”矛盾。", "清醒": "语义：“太清醒了”与“想早点睡”矛盾，人清醒时不会想睡觉。", "充足": "搭配：「充足」多修饰睡眠、精力、水分等；「太充足了」表示精力足、不累，与「想早点睡」矛盾。"}, "sentence_index": 0, "correct_answer": "疲劳"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "听说明天去海边，孩子非常疲劳。", "explanation": "这里应该用〈兴奋〉。疲劳指累，没有力气；对出游的激动要说兴奋。"}, {"text": "一听见雷声，她就疲劳得躲进了被子里。", "explanation": "这里应该用〈害怕〉。疲劳说身体累，不说听到雷声时的恐惧，这种情绪要说害怕。"}, {"text": "他拿到了满分，非常疲劳，逢人就炫耀。", "explanation": "这里应该用〈骄傲〉。疲劳指累、想休息，不指因成绩而自豪，这种心态要说骄傲。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43b210fc-d3d7-441e-83e1-71bbf100a917') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22820, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "疲劳", "is_correct": true, "explanation": "正确答案。“妈妈做了一天饭，十分疲劳”表示累了，与句意相符。"}, {"text": "饱", "is_correct": false, "explanation": "搭配：“饱”多用于吃饭之后，不用来说做饭一天后的状态。"}, {"text": "清爽", "is_correct": false, "explanation": "搭配：“清爽”多指洗澡后或天气，不用来说做了一天饭的人。"}, {"text": "健壮", "is_correct": false, "explanation": "语义：“健壮”指身体强壮有力，与做了一天饭后的状态矛盾，句子不通。"}], "explanations": {"疲劳": "正确答案。“妈妈做了一天饭，十分疲劳”表示累了，与句意相符。", "饱": "搭配：“饱”多用于吃饭之后，不用来说做饭一天后的状态。", "清爽": "搭配：“清爽”多指洗澡后或天气，不用来说做了一天饭的人。", "健壮": "语义：“健壮”指身体强壮有力，与做了一天饭后的状态矛盾，句子不通。"}, "sentence_index": 6, "correct_answer": "疲劳"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家听到这个消息，都非常疲劳，半天说不出话。", "explanation": "这里应该用〈惊讶〉。疲劳指累，没有力气；听到消息后的震惊要说惊讶。"}, {"text": "他第一次上台讲话，腿一直发抖，显得很疲劳。", "explanation": "这里应该用〈紧张〉。疲劳指身体或精神累；上台前的慌乱、发抖要说紧张。"}, {"text": "他拿到了奖学金，疲劳得原地蹦了起来。", "explanation": "这里应该用〈高兴〉。疲劳指累、想休息，不指得到奖学金的喜悦，要说高兴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43b210fc-d3d7-441e-83e1-71bbf100a917') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22820, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "刚跑完马拉松，我疲劳站都站不稳。", "corrected_sentence": "刚跑完马拉松，我疲劳得站都站不稳。", "error_description": "错误：程度补语前漏掉了“得”。正确：“疲劳得站都站不稳”，“得”引出疲劳的程度结果。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43b210fc-d3d7-441e-83e1-71bbf100a917') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22820, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他忙了一下午，很疲劳着，不想再动。", "corrected_sentence": "他忙了一下午，很疲劳，不想再动。", "error_description": "错误：「很疲劳」是形容词直接作谓语的状态描写，后面不能再加持续标记「着」。正确：“很疲劳，不想再动”，去掉「着」即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43b210fc-d3d7-441e-83e1-71bbf100a917') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
