INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22826, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手势或声音告诉别人一个消息。", "primary_collocate": null, "pronunciation": "fā chū xìn hào", "ipa": "fa⁵⁵ ʈʂʰu⁵⁵ ɕin⁵¹ xaʊ̯⁵¹", "syllable_count": 4, "sentences": [{"text": "他对我眨眼，是在发出信号。", "target_word": "发出信号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明挥挥手，向朋友发出信号。", "target_word": "发出信号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈咳了一声，向我发出信号。", "target_word": "发出信号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用手指了指门，向我发出信号，让我先走。", "target_word": "发出信号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到老师来了，同学轻轻咳嗽，发出信号。", "target_word": "发出信号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她拍了拍桌子，向大家发出信号。", "target_word": "发出信号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "导游举起小旗子，向游客发出信号。", "target_word": "发出信号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在台下点点头，向我发出信号：可以开始了。", "target_word": "发出信号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子用哭声向妈妈发出信号，说自己饿了。", "target_word": "发出信号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友在门外敲两下，发出信号。", "target_word": "发出信号", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "發出信號", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用手势或声音向别人示意一个消息", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0206ebc3-9f0d-4d6a-8d06-0de5f27ec0c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22826, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发出信号", "is_correct": true, "explanation": "正确。眨眼是用动作向我示意一个消息，即发出信号。"}, {"text": "收拾行李", "is_correct": false, "explanation": "语义：“收拾行李”指整理东西，与眨眼的示意无关，句子不通。"}, {"text": "唱首歌", "is_correct": false, "explanation": "语义：“唱首歌”需要唱出声音，与眨眼的示意无关，句意不通。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”是及物动词，需要带修理的对象，“是在修理”单独说不成立。"}], "explanations": {"发出信号": "正确。眨眼是用动作向我示意一个消息，即发出信号。", "收拾行李": "语义：“收拾行李”指整理东西，与眨眼的示意无关，句子不通。", "唱首歌": "语义：“唱首歌”需要唱出声音，与眨眼的示意无关，句意不通。", "修理": "搭配：“修理”是及物动词，需要带修理的对象，“是在修理”单独说不成立。"}, "sentence_index": 0, "correct_answer": "发出信号"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "秘书向经理发出信号，说明了会议的结果。", "explanation": "这里应该用〈汇报〉。汇报要用语言详细陈述，“发出信号”只能用手势或声音示意，不能用来说明会议结果。"}, {"text": "学生在讲台上发出信号，背完了整篇课文。", "explanation": "这里应该用〈背诵〉。背诵是把文字记在心里再说出来，“发出信号”只能示意，不能用来背课文。"}, {"text": "他向我发出信号，签了一份合同。", "explanation": "这里应该用〈签署〉。签署是在文件上写下名字，“发出信号”只能用手势或声音示意，不能代替签合同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f66d64-b0b4-42ac-a4f3-dce521f26445') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22826, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发出信号", "is_correct": true, "explanation": "正确。导游举旗子向游客示意，即发出信号。"}, {"text": "擦亮皮鞋", "is_correct": false, "explanation": "语义：“擦亮皮鞋”与举旗示意无关，句意不通。"}, {"text": "吃掉午饭", "is_correct": false, "explanation": "配价：“吃掉”的动作不能朝游客施行，“向游客吃午饭”不通。"}, {"text": "修剪草坪", "is_correct": false, "explanation": "语义：“修剪草坪”是整理草地，与向游客示意无关，句子不通。"}], "explanations": {"发出信号": "正确。导游举旗子向游客示意，即发出信号。", "擦亮皮鞋": "语义：“擦亮皮鞋”与举旗示意无关，句意不通。", "吃掉午饭": "配价：“吃掉”的动作不能朝游客施行，“向游客吃午饭”不通。", "修剪草坪": "语义：“修剪草坪”是整理草地，与向游客示意无关，句子不通。"}, "sentence_index": 6, "correct_answer": "发出信号"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在考试中发出信号，得出了正确的结果。", "explanation": "这里应该用〈计算〉。计算要用数字推算，“发出信号”只能用手势或声音示意，不能用来得出数学结果。"}, {"text": "老师向学生发出信号，说明了这道题的解法。", "explanation": "这里应该用〈讲解〉。讲解要用语言逐步解释，“发出信号”只能示意约定的记号，不能用来讲清解法。"}, {"text": "妈妈向我发出信号，读懂了一封英文信。", "explanation": "这里应该用〈阅读〉。阅读是看懂文字，“发出信号”只能示意，不能用来读懂英文信件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f66d64-b0b4-42ac-a4f3-dce521f26445') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22826, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他从我发出信号，让我先走。", "corrected_sentence": "他向我发出信号，让我先走。", "error_description": "介词错误。“发出信号”的对象要用“向”引出接收信号的人，“从我”说成信号来自我，与“让我先走”的意思相反，应说“向我发出信号”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f66d64-b0b4-42ac-a4f3-dce521f26445') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22826, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "朋友在门外轻轻敲了两下，把我发出信号。", "corrected_sentence": "朋友在门外轻轻敲了两下，向我发出信号。", "error_description": "介词错误。“发出信号”的接收对象要用“向”引出，“把”不能这样引出（“把我”不能作“发出”的对象），应说“向我发出信号”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f66d64-b0b4-42ac-a4f3-dce521f26445') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22828, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "长久", "is_correct": true, "explanation": "正确：“短暂”指时间很短，“长久”指时间很长，二者构成反义关系。"}, {"text": "模糊", "is_correct": false, "explanation": "无关：“模糊”形容不清晰，与时间长短无关。"}, {"text": "嘈杂", "is_correct": false, "explanation": "无关：“嘈杂”形容声音杂乱，与时间长短无关。"}, {"text": "粗糙", "is_correct": false, "explanation": "无关：“粗糙”形容表面不光滑，与时间长短无关。"}], "correct_answer": "长久", "explanations": {"长久": "正确：“短暂”指时间很短，“长久”指时间很长，二者构成反义关系。", "模糊": "无关：“模糊”形容不清晰，与时间长短无关。", "嘈杂": "无关：“嘈杂”形容声音杂乱，与时间长短无关。", "粗糙": "无关：“粗糙”形容表面不光滑，与时间长短无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f66d64-b0b4-42ac-a4f3-dce521f26445') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22828, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "长久", "is_correct": true, "explanation": "正确：“短暂”指时间很短，“长久”指时间很长，二者构成反义关系。"}, {"text": "寒冷", "is_correct": false, "explanation": "无关：“寒冷”形容温度低，与时间长短无关。"}, {"text": "复杂", "is_correct": false, "explanation": "无关：“复杂”形容事物繁多、不简单，与时间长短无关。"}, {"text": "陡峭", "is_correct": false, "explanation": "无关：“陡峭”形容坡度大，与时间长短无关。"}], "correct_answer": "长久", "explanations": {"长久": "正确：“短暂”指时间很短，“长久”指时间很长，二者构成反义关系。", "寒冷": "无关：“寒冷”形容温度低，与时间长短无关。", "复杂": "无关：“复杂”形容事物繁多、不简单，与时间长短无关。", "陡峭": "无关：“陡峭”形容坡度大，与时间长短无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f66d64-b0b4-42ac-a4f3-dce521f26445') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22828, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "表示时间很短，就像玩一会儿就结束了。", "primary_collocate": null, "pronunciation": "duǎn zàn", "ipa": "twan²¹⁴ tsan⁵¹", "syllable_count": 2, "sentences": [{"text": "游戏时间很短暂，一会儿就结束了。", "target_word": "短暂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "烟花只亮了一下，非常短暂。", "target_word": "短暂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下课的休息很短暂，只有十分钟。", "target_word": "短暂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "彩虹很短暂，我们看了一会儿就没了。", "target_word": "短暂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们短暂的玩耍很快就结束了，他们就回家了。", "target_word": "短暂", "complexity_tier": "T3", "furigana": "hái zi men duǎn zàn de wán shuǎ hěn kuài jiù jié shù le, tā men jiù huí jiā le.", "sentence_source": "generated"}, {"text": "假期太短暂了，我还没玩够。", "target_word": "短暂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雪人的生命很短暂，太阳一出来就化了。", "target_word": "短暂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的聚会很短暂，一个小时就散了。", "target_word": "短暂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小鸟在树上短暂地停留，又飞走了。", "target_word": "短暂", "complexity_tier": "T3", "furigana": "xiǎo niǎo zài shù shàng duǎn zàn de tíng liú, yòu fēi zǒu le.", "sentence_source": "generated"}, {"text": "这场比赛很短暂，十分钟就分出了输赢。", "target_word": "短暂", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "短暫", "label": "繁体"}], "register": "中性", "sense_fingerprint": "时间很短，一会儿就结束", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0206ebc3-9f0d-4d6a-8d06-0de5f27ec0c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22828, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "短暂", "is_correct": true, "explanation": "正确：“很短暂”说明时间不长，与后半句“一会儿就结束了”相呼应。"}, {"text": "漫长", "is_correct": false, "explanation": "语义：“漫长”说时间很长，与后半句“一会儿就结束了”相矛盾。"}, {"text": "深刻", "is_correct": false, "explanation": "搭配：“深刻”形容印象、道理等，不能用来形容时间的长短。"}, {"text": "宽敞", "is_correct": false, "explanation": "搭配：“宽敞”形容空间大，不能用来形容“游戏时间”。"}], "explanations": {"短暂": "正确：“很短暂”说明时间不长，与后半句“一会儿就结束了”相呼应。", "漫长": "语义：“漫长”说时间很长，与后半句“一会儿就结束了”相矛盾。", "深刻": "搭配：“深刻”形容印象、道理等，不能用来形容时间的长短。", "宽敞": "搭配：“宽敞”形容空间大，不能用来形容“游戏时间”。"}, "sentence_index": 0, "correct_answer": "短暂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这篇文章很短暂。", "explanation": "这里应该用〈简短〉。短暂说时间的长短，文章篇幅的长短要用“简短”。"}, {"text": "这把尺子很短暂。", "explanation": "这里应该用〈短〉。短暂只用于时间，物体的长短要用“短”。"}, {"text": "他的见识很短暂。", "explanation": "这里应该用〈短浅〉。见识的浅短要用“短浅”，短暂只说时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f66d64-b0b4-42ac-a4f3-dce521f26445') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22828, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "短暂", "is_correct": true, "explanation": "正确：“很短暂”说明生命持续的时间很短，与“太阳一出来就化了”相呼应。"}, {"text": "坚固", "is_correct": false, "explanation": "语义：“坚固”指结实、不易损坏，与“太阳一出来就化了”的结局相矛盾。"}, {"text": "厚实", "is_correct": false, "explanation": "搭配：“厚实”形容物体的厚度，不用来说生命的长短。"}, {"text": "漫长", "is_correct": false, "explanation": "语义：“漫长”说时间很长，与“太阳一出来就化了”的结局相矛盾。"}], "explanations": {"短暂": "正确：“很短暂”说明生命持续的时间很短，与“太阳一出来就化了”相呼应。", "坚固": "语义：“坚固”指结实、不易损坏，与“太阳一出来就化了”的结局相矛盾。", "厚实": "搭配：“厚实”形容物体的厚度，不用来说生命的长短。", "漫长": "语义：“漫长”说时间很长，与“太阳一出来就化了”的结局相矛盾。"}, "sentence_index": 6, "correct_answer": "短暂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这是一份短暂合同。", "explanation": "这里应该用〈短期〉。“短期合同”指期限短，短暂强调事物本身持续的时间很短。"}, {"text": "她的语气很短暂。", "explanation": "这里应该用〈短促〉。短促形容声音、语气急而短，短暂只说时间的长短。"}, {"text": "这根木棍很短暂。", "explanation": "这里应该用〈短〉。短暂只用于时间，木棍的长短要用“短”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f66d64-b0b4-42ac-a4f3-dce521f26445') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22828, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子们短暂地的停下脚步，又继续往前跑。", "corrected_sentence": "孩子们短暂地停下脚步，又继续往前跑。", "error_description": "标记错误。“短暂”后不能同时用“地”和“的”，“短暂地的停下”不通；修饰动词“停下”只用“地”，应写作“短暂地停下脚步”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f66d64-b0b4-42ac-a4f3-dce521f26445') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22828, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在山顶有过一段短暂地停留。", "corrected_sentence": "我们在山顶有过一段短暂的停留。", "error_description": "“一段”后接名词“停留”，“短暂”修饰名词要用“的”。写成“地”后，“短暂地停留”是动词短语，不能接在“一段”后面，句子不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f66d64-b0b4-42ac-a4f3-dce521f26445') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
