INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22830, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "把心思放在一件事上的能力。", "primary_collocate": null, "pronunciation": "zhù yì lì", "ipa": "ʈʂu˥˩ i˥˩ li˥˩", "syllable_count": 3, "sentences": [{"text": "他的注意力都在手机上。", "target_word": "注意力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做作业时，要把注意力放在题目上。", "target_word": "注意力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃饭的时候看电视会分散注意力。", "target_word": "注意力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌很好听，吸引了我的注意力。", "target_word": "注意力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他开会时注意力不集中，一直看窗外。", "target_word": "注意力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的注意力很强，能看三个小时的书。", "target_word": "注意力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早上喝杯咖啡，注意力会好一点儿。", "target_word": "注意力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子累了，注意力就会下降。", "target_word": "注意力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大家集中注意力，听我说。", "target_word": "注意力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面太吵，我没办法集中注意力。", "target_word": "注意力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "把心思放在一件事上的能力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0206ebc3-9f0d-4d6a-8d06-0de5f27ec0c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22830, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "注意力", "is_correct": true, "explanation": "正确。“注意力都在手机上”指心思全放在手机上，符合“注意力”的意思。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”指身体的重量，不能“在手机上”，句意不通。"}, {"text": "食欲", "is_correct": false, "explanation": "语义：“食欲”指想吃东西的欲望，不能放在手机上，句子说不通。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“脾气”不说“在某物上”，“脾气都在手机上”不通。"}], "explanations": {"注意力": "正确。“注意力都在手机上”指心思全放在手机上，符合“注意力”的意思。", "体重": "语义：“体重”指身体的重量，不能“在手机上”，句意不通。", "食欲": "语义：“食欲”指想吃东西的欲望，不能放在手机上，句子说不通。", "脾气": "搭配：“脾气”不说“在某物上”，“脾气都在手机上”不通。"}, "sentence_index": 0, "correct_answer": "注意力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道菜的注意力很鲜，大家都夸好吃。", "explanation": "这里应该用〈味道〉。“鲜”形容味道，注意力指集中心思，不能用来形容菜的味道。"}, {"text": "今天他的注意力很响亮，话特别多。", "explanation": "这里应该用〈嗓门〉。“响亮”形容声音，注意力不能这样形容，应说嗓门大。"}, {"text": "这间房子的注意力有八十平方米。", "explanation": "这里应该用〈面积〉。“八十平方米”是面积的数值，注意力指集中心思，不能用平方米计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f66d64-b0b4-42ac-a4f3-dce521f26445') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22830, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "注意力", "is_correct": true, "explanation": "正确。喝咖啡能提神，所以“注意力会好一点儿”，这里的“注意力”指集中心思的能力。"}, {"text": "视力", "is_correct": false, "explanation": "语义：咖啡与视力无关，“视力会好一点儿”与句中提神的作用不符。"}, {"text": "人气", "is_correct": false, "explanation": "语义：“人气”指受欢迎的程度，喝咖啡不会使它变好，句子不通。"}, {"text": "财产", "is_correct": false, "explanation": "搭配：“好一点儿”说的是状况，“财产”一般说多少、增减，不说“好一点儿”。"}], "explanations": {"注意力": "正确。喝咖啡能提神，所以“注意力会好一点儿”，这里的“注意力”指集中心思的能力。", "视力": "语义：咖啡与视力无关，“视力会好一点儿”与句中提神的作用不符。", "人气": "语义：“人气”指受欢迎的程度，喝咖啡不会使它变好，句子不通。", "财产": "搭配：“好一点儿”说的是状况，“财产”一般说多少、增减，不说“好一点儿”。"}, "sentence_index": 6, "correct_answer": "注意力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他发烧了，注意力高达三十九度。", "explanation": "这里应该用〈体温〉。“三十九度”是体温的数值，注意力指集中心思，不能用度数表示。"}, {"text": "这辆车的注意力很快。", "explanation": "这里应该用〈速度〉。“快”形容速度，注意力不能说“快”。"}, {"text": "这幅画的注意力很温暖。", "explanation": "这里应该用〈色彩〉。“温暖”形容色彩或气氛，注意力指集中心思，不能用来形容画面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f66d64-b0b4-42ac-a4f3-dce521f26445') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22830, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个孩子有一只很强的注意力。", "corrected_sentence": "这个孩子有一种很强的注意力。", "error_description": "量词错误。“注意力”是抽象名词，应用量词“种”，“只”不能用来数注意力。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f66d64-b0b4-42ac-a4f3-dce521f26445') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22830, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "上课时他的注意力很难集中起去。", "corrected_sentence": "上课时他的注意力很难集中起来。", "error_description": "补语错误。“集中”后的趋向补语应为“起来”，“起去”不成词，应说“集中起来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f66d64-b0b4-42ac-a4f3-dce521f26445') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
