INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22836, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "凉爽就是天气不热，很舒服。", "primary_collocate": null, "pronunciation": "liáng shuǎng", "ipa": "ljɑŋ³⁵ ʂwɑŋ²¹⁴", "syllable_count": 2, "sentences": [{"text": "今天天气凉爽，我想出去走走。", "target_word": "凉爽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "九月的北京很凉爽。", "target_word": "凉爽", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "夏天晚上有风，特别凉爽。", "target_word": "凉爽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里的春天不冷也不热，很凉爽。", "target_word": "凉爽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我喜欢凉爽的秋天。", "target_word": "凉爽", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "下午的天气变得凉爽了。", "target_word": "凉爽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山上比城里凉爽。", "target_word": "凉爽", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "空调开了以后，房间里很凉爽。", "target_word": "凉爽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "凉爽的早晨，爷爷在公园里打太极。", "target_word": "凉爽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨后的空气又新鲜又凉爽。", "target_word": "凉爽", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "涼爽", "label": "繁体"}], "register": "中性", "sense_fingerprint": "天气不热，让人觉得舒服", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0206ebc3-9f0d-4d6a-8d06-0de5f27ec0c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22836, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "凉爽", "is_correct": true, "explanation": "正确：“今天天气凉爽”说明天气舒适，与“我想出去走走”相呼应。"}, {"text": "酷寒", "is_correct": false, "explanation": "语义：“酷寒”指极度寒冷，与“想出去走走”的愉快心情不协调。"}, {"text": "暴烈", "is_correct": false, "explanation": "语义：“暴烈”形容猛烈、狂暴，与舒适的天气不相符。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”形容声音，不能用来形容天气。"}], "explanations": {"凉爽": "正确：“今天天气凉爽”说明天气舒适，与“我想出去走走”相呼应。", "酷寒": "语义：“酷寒”指极度寒冷，与“想出去走走”的愉快心情不协调。", "暴烈": "语义：“暴烈”形容猛烈、狂暴，与舒适的天气不相符。", "清脆": "搭配：“清脆”形容声音，不能用来形容天气。"}, "sentence_index": 0, "correct_answer": "凉爽"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试的成绩很凉爽。", "explanation": "这里应该用〈优秀〉。凉爽只形容天气、环境让人舒适，成绩的好坏要用“优秀”。"}, {"text": "这块铁很凉爽。", "explanation": "这里应该用〈冰冷〉。凉爽不用于金属等物体的低温，铁块的冷应说“冰冷”。"}, {"text": "这张桌子很凉爽。", "explanation": "这里应该用〈凉〉。凉爽只用于天气、空气等环境，桌子的温度要用“凉”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f66d64-b0b4-42ac-a4f3-dce521f26445') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22836, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "凉爽", "is_correct": true, "explanation": "正确：“山上比城里凉爽”是常见说法，指山上气温更低、更舒适。"}, {"text": "繁华", "is_correct": false, "explanation": "语义：“繁华”指街市热闹，与“山上”的比较对象不符，且与气温无关。"}, {"text": "精致", "is_correct": false, "explanation": "搭配：“精致”形容制作细巧，不能用来比较地方的气温。"}, {"text": "拥挤", "is_correct": false, "explanation": "语义：“拥挤”指人或物过多、空间紧张，与气温的比较无关。"}], "explanations": {"凉爽": "正确：“山上比城里凉爽”是常见说法，指山上气温更低、更舒适。", "繁华": "语义：“繁华”指街市热闹，与“山上”的比较对象不符，且与气温无关。", "精致": "搭配：“精致”形容制作细巧，不能用来比较地方的气温。", "拥挤": "语义：“拥挤”指人或物过多、空间紧张，与气温的比较无关。"}, "sentence_index": 6, "correct_answer": "凉爽"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "沙漠里的正午很凉爽。", "explanation": "这里应该用〈酷热〉。凉爽指舒适的凉意，正午的炎热应说“酷热”。"}, {"text": "冬天的夜里很凉爽。", "explanation": "这里应该用〈寒冷〉。凉爽表示舒适的凉，冬夜的冷应说“寒冷”。"}, {"text": "他的发型很凉爽。", "explanation": "这里应该用〈清爽〉。凉爽只用于天气、环境，发型整洁利落的感觉要用“清爽”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f66d64-b0b4-42ac-a4f3-dce521f26445') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22836, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今天天气凉爽得，我们去公园吧。", "corrected_sentence": "今天天气凉爽，我们去公园吧。", "error_description": "结构错误。“凉爽得”后须接程度补语（如“凉爽得很”），直接停顿不通，应删去“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f66d64-b0b4-42ac-a4f3-dce521f26445') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22836, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在凉爽地傍晚散步。", "corrected_sentence": "我们在凉爽的傍晚散步。", "error_description": "“凉爽”修饰名词“傍晚”时要用“的”，写成“地”后不能修饰名词，句子结构不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f66d64-b0b4-42ac-a4f3-dce521f26445') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22838, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "升温", "is_correct": true, "explanation": "升温指气温升高，与降温（天气变冷）方向相反，是反义关系。"}, {"text": "下棋", "is_correct": false, "explanation": "下棋是娱乐活动，与降温没有反义关系。"}, {"text": "吃饭", "is_correct": false, "explanation": "吃饭是日常活动，与天气变化无关，不构成反义。"}, {"text": "画画", "is_correct": false, "explanation": "画画是艺术活动，与降温没有反义关系。"}], "correct_answer": "升温", "explanations": {"升温": "升温指气温升高，与降温（天气变冷）方向相反，是反义关系。", "下棋": "下棋是娱乐活动，与降温没有反义关系。", "吃饭": "吃饭是日常活动，与天气变化无关，不构成反义。", "画画": "画画是艺术活动，与降温没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742cd520-0a5e-4792-82d4-d2db45d8b7fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22838, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "升温", "is_correct": true, "explanation": "升温指气温升高，与降温（天气变冷）方向相反，是反义关系。"}, {"text": "睡觉", "is_correct": false, "explanation": "睡觉是生理活动，与降温没有反义关系。"}, {"text": "洗澡", "is_correct": false, "explanation": "洗澡是日常活动，与天气变化无关，不构成反义。"}, {"text": "上课", "is_correct": false, "explanation": "上课是学习活动，与降温没有反义关系。"}], "correct_answer": "升温", "explanations": {"升温": "升温指气温升高，与降温（天气变冷）方向相反，是反义关系。", "睡觉": "睡觉是生理活动，与降温没有反义关系。", "洗澡": "洗澡是日常活动，与天气变化无关，不构成反义。", "上课": "上课是学习活动，与降温没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742cd520-0a5e-4792-82d4-d2db45d8b7fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22838, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "天气变得很冷。", "primary_collocate": null, "pronunciation": "jiàng wēn", "ipa": "tɕjɑŋ˥˩ wən˥", "syllable_count": 2, "sentences": [{"text": "一场大雪以后，城里突然降温了。", "target_word": "降温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十一月以后，南方也开始降温。", "target_word": "降温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冷空气一来，北京马上降温。", "target_word": "降温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天风很大，晚上还要降温。", "target_word": "降温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气突然降温，大家都穿上了厚外套。", "target_word": "降温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家那边已经降温，早上有霜。", "target_word": "降温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个周末降温，别忘了带手套。", "target_word": "降温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最近降温太快，孩子容易感冒。", "target_word": "降温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨晚降温了，今早窗户上有冰。", "target_word": "降温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一降温，街上的人就少了。", "target_word": "降温", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "降温了", "label": "完成体"}, {"form": "降过温", "label": "经历体"}, {"form": "降了温", "label": "离合式"}], "register": "中性", "sense_fingerprint": "降温|天气变冷|动词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8cbebb4-22b2-4457-b7ac-21ebb866bd00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22838, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "降温", "is_correct": true, "explanation": "正确：降温指气温降低，与“一场大雪以后”带来的寒冷一致。"}, {"text": "升温", "is_correct": false, "explanation": "语义：升温是气温上升，与大雪后的寒冷相矛盾。"}, {"text": "发烧", "is_correct": false, "explanation": "搭配：发烧指人的体温升高，城市不能发烧。"}, {"text": "加温", "is_correct": false, "explanation": "语义：加温是使变暖，与大雪后城里变冷相矛盾。"}], "explanations": {"降温": "正确：降温指气温降低，与“一场大雪以后”带来的寒冷一致。", "升温": "语义：升温是气温上升，与大雪后的寒冷相矛盾。", "发烧": "搭配：发烧指人的体温升高，城市不能发烧。", "加温": "语义：加温是使变暖，与大雪后城里变冷相矛盾。"}, "sentence_index": 0, "correct_answer": "降温"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "商场的商品大幅降温了。", "explanation": "这里应该用〈降价〉。降温指温度下降，商品价格下降要用降价，“商品降温”说不通。"}, {"text": "他的脚步降温了。", "explanation": "这里应该用〈减慢〉。降温指温度下降，走路变慢要用减慢。"}, {"text": "这个班的平均分降温了。", "explanation": "这里应该用〈降低〉。降温用于天气和温度，平均分下降要用降低。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742cd520-0a5e-4792-82d4-d2db45d8b7fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22838, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "降温", "is_correct": true, "explanation": "正确：降温指天气变冷，与“别忘了带手套”的保暖提醒一致。"}, {"text": "降价", "is_correct": false, "explanation": "搭配：降价用于商品价格，不用于天气。"}, {"text": "加热", "is_correct": false, "explanation": "搭配：加热用于物体，不说周末加热。"}, {"text": "发热", "is_correct": false, "explanation": "语义：发热是产生热量，与“带手套”保暖的语境相矛盾。"}], "explanations": {"降温": "正确：降温指天气变冷，与“别忘了带手套”的保暖提醒一致。", "降价": "搭配：降价用于商品价格，不用于天气。", "加热": "搭配：加热用于物体，不说周末加热。", "发热": "语义：发热是产生热量，与“带手套”保暖的语境相矛盾。"}, "sentence_index": 6, "correct_answer": "降温"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这支基金昨天降温了。", "explanation": "这里应该用〈下跌〉。降温指温度变低，基金价格下跌要用下跌。"}, {"text": "这家公司的员工降温了。", "explanation": "这里应该用〈减少〉。降温只用于温度，员工人数变少要用减少。"}, {"text": "公司的业绩降温了。", "explanation": "这里应该用〈下滑〉。降温指温度下降，业绩变差要用下滑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742cd520-0a5e-4792-82d4-d2db45d8b7fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22838, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "天气被降温了。", "corrected_sentence": "天气降温了。", "error_description": "错误形式：“天气被降温了”。正确形式：“天气降温了”。原因：表示天气变冷时，“降温”不带受事，不能用“被”构成被动句。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742cd520-0a5e-4792-82d4-d2db45d8b7fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22838, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个周末降温的很快，记得多穿点衣服。", "corrected_sentence": "这个周末降温得很快，记得多穿点衣服。", "error_description": "错误形式：“这个周末降温的很快”。正确形式：“这个周末降温得很快”。原因：“降温”后面的补语要用“得”连接，不能用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742cd520-0a5e-4792-82d4-d2db45d8b7fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22840, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "创造", "is_correct": true, "explanation": "创造指做出从未有过的新东西，与模仿（照着别人的样子做）相反。"}, {"text": "散步", "is_correct": false, "explanation": "散步是日常活动，与模仿没有反义关系。"}, {"text": "聊天", "is_correct": false, "explanation": "聊天是交流活动，与模仿没有反义关系。"}, {"text": "洗澡", "is_correct": false, "explanation": "洗澡是日常活动，与模仿没有反义关系。"}], "correct_answer": "创造", "explanations": {"创造": "创造指做出从未有过的新东西，与模仿（照着别人的样子做）相反。", "散步": "散步是日常活动，与模仿没有反义关系。", "聊天": "聊天是交流活动，与模仿没有反义关系。", "洗澡": "洗澡是日常活动，与模仿没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742cd520-0a5e-4792-82d4-d2db45d8b7fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
