INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22842, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让东西变得不多不少，刚刚好。", "primary_collocate": null, "pronunciation": "tiáo jié", "ipa": "tʰiau˧˥ tɕiɛ˧˥", "syllable_count": 2, "sentences": [{"text": "你可以自己调节空调的温度。", "target_word": "调节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把声音调节得小一点儿。", "target_word": "调节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喝茶来调节心情。", "target_word": "调节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个按钮可以调节灯的亮度。", "target_word": "调节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "身体会自己调节温度。", "target_word": "调节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听音乐能帮你调节情绪。", "target_word": "调节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈调节了一下水的冷热。", "target_word": "调节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我正在调节电视的颜色。", "target_word": "调节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们怎么调节呼吸。", "target_word": "调节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天，我们用机器调节屋里的湿度。", "target_word": "调节", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "调节了", "label": "体标（了）"}, {"form": "调节过", "label": "体标（过）"}, {"form": "调节器", "label": "复合"}, {"form": "自我调节", "label": "复合"}], "register": "中性", "sense_fingerprint": "动词，把温度、声音、情绪等调整到合适的程度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca85f957-df35-4d8f-af57-1db695739dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22842, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "调节", "is_correct": true, "explanation": "正确答案：调节 tiáo jié，使事物的程度适中。"}, {"text": "调解", "is_correct": false, "explanation": "调解 tiáo jiě 与 调节 tiáo jié 第二个音节声调不同（jiě 与 jié），意思是劝说双方和解。"}, {"text": "条街", "is_correct": false, "explanation": "条街 tiáo jiē 与 调节 tiáo jié 第二个音节声调不同（jiē 与 jié），意思是一条街道。"}, {"text": "条件", "is_correct": false, "explanation": "条件 tiáo jiàn 与 调节 tiáo jié 的第二个音节有差别（jiàn 与 jié，多一个鼻音韵尾且声调不同），意思是前提或要求。"}], "explanations": {"调节": "正确答案：调节 tiáo jié，使事物的程度适中。", "调解": "调解 tiáo jiě 与 调节 tiáo jié 第二个音节声调不同（jiě 与 jié），意思是劝说双方和解。", "条街": "条街 tiáo jiē 与 调节 tiáo jié 第二个音节声调不同（jiē 与 jié），意思是一条街道。", "条件": "条件 tiáo jiàn 与 调节 tiáo jié 的第二个音节有差别（jiàn 与 jié，多一个鼻音韵尾且声调不同），意思是前提或要求。"}, "sentence_index": null, "correct_answer": "调节"}, "level_3": {"options": [{"text": "调节", "is_correct": true, "explanation": "正确：“调节空调的温度”指调整到合适的程度，符合语境。"}, {"text": "点燃", "is_correct": false, "explanation": "搭配：“点燃”用于火或可燃物，不能用于“温度”。"}, {"text": "背诵", "is_correct": false, "explanation": "语义：“背诵”是念记文字，“背诵空调的温度”说不通。"}, {"text": "散步", "is_correct": false, "explanation": "配价：“散步”是不及物动词，不能带“温度”作宾语。"}], "explanations": {"调节": "正确：“调节空调的温度”指调整到合适的程度，符合语境。", "点燃": "搭配：“点燃”用于火或可燃物，不能用于“温度”。", "背诵": "语义：“背诵”是念记文字，“背诵空调的温度”说不通。", "散步": "配价：“散步”是不及物动词，不能带“温度”作宾语。"}, "sentence_index": 0, "correct_answer": "调节"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个问题很难，我们应该调节它。", "explanation": "这里应该用〈解决〉。调节指使事物的程度适中，问题要通过〈解决〉来处理。"}, {"text": "他去调节两个人的身高。", "explanation": "这里应该用〈比较〉。身高是固定的，不能调节；“调节”只用于可以调整程度的事物。"}, {"text": "他正在调节那件破损的古董。", "explanation": "这里应该用〈修复〉。调节指调整程度使其刚刚好，破损的古董要用〈修复〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c290b81d-0dcb-45a5-b379-91fe24a99a2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22842, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "调节", "is_correct": true, "explanation": "正确：“调节水的冷热”指把水温调到合适的程度，符合语境。"}, {"text": "切割", "is_correct": false, "explanation": "语义：切割是把物体切开，不能用来调节水的冷热。"}, {"text": "朗读", "is_correct": false, "explanation": "语义：朗读是念出文字，不能用于水的冷热。"}, {"text": "跳跃", "is_correct": false, "explanation": "配价：“跳跃”是不及物动词，不能带“水的冷热”作宾语。"}], "explanations": {"调节": "正确：“调节水的冷热”指把水温调到合适的程度，符合语境。", "切割": "语义：切割是把物体切开，不能用来调节水的冷热。", "朗读": "语义：朗读是念出文字，不能用于水的冷热。", "跳跃": "配价：“跳跃”是不及物动词，不能带“水的冷热”作宾语。"}, "sentence_index": 6, "correct_answer": "调节"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "冬天，我们用湿度计调节屋里的湿度。", "explanation": "这里应该用〈测量〉。湿度计用于测量湿度，不能调节湿度，调节湿度要用加湿器等设备。"}, {"text": "冬天，我们用机器调节屋里的歌曲。", "explanation": "这里应该用〈播放〉。调节用于调整温度、音量等程度，歌曲要说“播放”。"}, {"text": "他被调节到了另一个部门。", "explanation": "这里应该用〈调〉。“调到”指人员调动，调节只用于调整程度，不能用来指调动人员。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c290b81d-0dcb-45a5-b379-91fe24a99a2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22842, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个开关可以调节了风扇的速度。", "corrected_sentence": "这个开关可以调节风扇的速度。", "error_description": "“可以”后面的动词不能再加“了”，“调节了”是错误的，应为“可以调节”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c290b81d-0dcb-45a5-b379-91fe24a99a2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22842, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我正在调节了电视的音量。", "corrected_sentence": "我正在调节电视的音量。", "error_description": "“正在”表示动作进行中，不能与“了”同用；“调节”后多余的“了”应去掉，应说“我正在调节电视的音量”，不能说“我正在调节了电视的音量”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c290b81d-0dcb-45a5-b379-91fe24a99a2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
