INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22844, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让东西开始工作或动起来。", "primary_collocate": null, "pronunciation": "jī huó", "ipa": "tɕi˥ xwo˨˦", "syllable_count": 2, "sentences": [{"text": "新手机买回来后，要先激活。", "target_word": "激活", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请输入激活码，激活这个软件。", "target_word": "激活", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我打电话激活了新银行卡。", "target_word": "激活", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个游戏账号还没激活，你不能用。", "target_word": "激活", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个新电脑要先联网激活，才能使用。", "target_word": "激活", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "点一下这个按钮，就能激活系统。", "target_word": "激活", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张会员卡要在手机上激活才能用。", "target_word": "激活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机激活成功后，你会收到短信。", "target_word": "激活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他忘了激活账号，所以登不进去。", "target_word": "激活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把新电话卡放进手机，然后激活。", "target_word": "激活", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "激活了", "label": "完成体"}, {"form": "激活过", "label": "经验体"}, {"form": "激活码", "label": "复合词"}], "register": "中性", "sense_fingerprint": "使设备、账号、系统等开始工作或进入可用状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd39e035a-dda2-4ec6-9ffc-89dfa7d4a654') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22844, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "激活", "is_correct": true, "explanation": "激活：使手机开始可用，与“要先”搭配，符合句意。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”针对食物，不能用来说手机。"}, {"text": "摔坏", "is_correct": false, "explanation": "语义：摔坏的手机不能用，与“要先”的步骤不符，句意不通。"}, {"text": "丢弃", "is_correct": false, "explanation": "语义：买回来的新手机刚开始使用就丢掉，与常理相反。"}], "explanations": {"激活": "激活：使手机开始可用，与“要先”搭配，符合句意。", "煮": "搭配：“煮”针对食物，不能用来说手机。", "摔坏": "语义：摔坏的手机不能用，与“要先”的步骤不符，句意不通。", "丢弃": "语义：买回来的新手机刚开始使用就丢掉，与常理相反。"}, "sentence_index": 0, "correct_answer": "激活"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "司机一上车就激活了这一天。", "explanation": "这里应该用〈开始〉。激活用于设备、账号、系统等，“这一天”不是这类对象。"}, {"text": "早上的闹钟激活了我。", "explanation": "这里应该用〈唤醒〉。激活指使设备、账号等开始可用，叫醒人要用唤醒。"}, {"text": "夏天到了，他激活了窗户。", "explanation": "这里应该用〈打开〉。激活只用于设备、账号、系统等，开窗户要用打开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c6e4eaf-bbef-40a3-834b-a2f5a9583caa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22844, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "激活", "is_correct": true, "explanation": "激活：让会员卡开始可用，与“才能用”呼应。"}, {"text": "复印", "is_correct": false, "explanation": "搭配：“复印”要用复印机处理纸质材料，不能在手机上复印会员卡。"}, {"text": "删除", "is_correct": false, "explanation": "语义：删除卡片后就无法使用，与“才能用”的意思相反。"}, {"text": "撕掉", "is_correct": false, "explanation": "语义：撕掉会员卡就不能再使用，与“才能用”相矛盾。"}], "explanations": {"激活": "激活：让会员卡开始可用，与“才能用”呼应。", "复印": "搭配：“复印”要用复印机处理纸质材料，不能在手机上复印会员卡。", "删除": "语义：删除卡片后就无法使用，与“才能用”的意思相反。", "撕掉": "语义：撕掉会员卡就不能再使用，与“才能用”相矛盾。"}, "sentence_index": 6, "correct_answer": "激活"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天早上都激活衣服。", "explanation": "这里应该用〈洗〉。激活用于设备、账号、系统，使其开始可用，洗衣服要用洗。"}, {"text": "他用火柴激活了蜡烛。", "explanation": "这里应该用〈点燃〉。激活指使设备、账号等开始可用，点蜡烛要用点燃。"}, {"text": "他用热水激活了冻肉。", "explanation": "这里应该用〈解冻〉。激活指使设备、账号等开始可用，让冻肉恢复常温要用解冻。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c6e4eaf-bbef-40a3-834b-a2f5a9583caa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22844, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我刚买的平板电脑还没激活了。", "corrected_sentence": "我刚买的平板电脑还没激活。", "error_description": "错误：“还没激活了”，“还没”与动词后的“了”不能同时使用。正确：“还没激活”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c6e4eaf-bbef-40a3-834b-a2f5a9583caa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22844, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请先激活这条账号。", "corrected_sentence": "请先激活这个账号。", "error_description": "错误：“这条账号”，“账号”的量词应用“个”，不用“条”。正确：“这个账号”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c6e4eaf-bbef-40a3-834b-a2f5a9583caa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
