INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22846, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "神经元是身体里像小电线一样传递信息的细胞。", "primary_collocate": null, "pronunciation": "shén jīng yuán", "ipa": "ʂən˧˥ tɕiŋ˥˥ ɥæn˧˥", "syllable_count": 3, "sentences": [{"text": "神经元是大脑里很小的细胞。", "target_word": "神经元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人的大脑里有很多神经元。", "target_word": "神经元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "神经元可以把信息传给别的细胞。", "target_word": "神经元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生用显微镜看到了神经元。", "target_word": "神经元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "神经元受伤以后，很难长回来。", "target_word": "神经元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个神经元都像一棵小树。", "target_word": "神经元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡觉的时候，神经元也在工作。", "target_word": "神经元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们看了神经元的图片。", "target_word": "神经元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家正在研究神经元怎么连在一起。", "target_word": "神经元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "神经元之间用电信号传递消息。", "target_word": "神经元", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "神經元", "label": "繁体"}, {"form": "运动神经元", "label": "复合词"}], "register": "中性", "sense_fingerprint": "神经系统中传递信息的细胞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b10fc90c-0e14-449a-94f1-3095b8172350') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22846, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "神经元", "is_correct": true, "explanation": "神经元：神经系统中传递信息的细胞，是“大脑里很小的细胞”，与定义一致。"}, {"text": "肌肉", "is_correct": false, "explanation": "语义：肌肉由肌纤维构成，不属于大脑里的细胞。"}, {"text": "树叶", "is_correct": false, "explanation": "语义：树叶是植物器官，不在大脑里，与句意相悖。"}, {"text": "钥匙", "is_correct": false, "explanation": "搭配：“是……细胞”的主语须是细胞类实体，“钥匙”不能与“细胞”构成判断句。"}], "explanations": {"神经元": "神经元：神经系统中传递信息的细胞，是“大脑里很小的细胞”，与定义一致。", "肌肉": "语义：肌肉由肌纤维构成，不属于大脑里的细胞。", "树叶": "语义：树叶是植物器官，不在大脑里，与句意相悖。", "钥匙": "搭配：“是……细胞”的主语须是细胞类实体，“钥匙”不能与“细胞”构成判断句。"}, "sentence_index": 0, "correct_answer": "神经元"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生用显微镜看到了一只神经元。", "explanation": "这里应该用〈个〉。神经元的量词是“个”，“只”多用于动物，不能用于细胞。"}, {"text": "他一遇到考试，神经元就绷得很紧。", "explanation": "这里表示紧张的感觉，应说“神经绷紧”。神经元是细胞，不用来形容紧张。"}, {"text": "他的神经元很灵活，一下子就想到了办法。", "explanation": "这里应该用〈脑子〉。“脑子灵活”指头脑反应快，神经元是细胞，不这样指头脑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43b210fc-d3d7-441e-83e1-71bbf100a917') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22846, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "神经元", "is_correct": true, "explanation": "神经元：睡眠时大脑中的神经元仍在活动，与句意相符。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：脾气是性格或情绪的表现，不是能够在睡眠中工作的事物。"}, {"text": "镜子", "is_correct": false, "explanation": "语义：镜子是反射光线的器具，不会在睡觉时工作。"}, {"text": "手套", "is_correct": false, "explanation": "搭配：“工作”多用于人或机器，“手套”一般不说“在工作”。"}], "explanations": {"神经元": "神经元：睡眠时大脑中的神经元仍在活动，与句意相符。", "脾气": "语义：脾气是性格或情绪的表现，不是能够在睡眠中工作的事物。", "镜子": "语义：镜子是反射光线的器具，不会在睡觉时工作。", "手套": "搭配：“工作”多用于人或机器，“手套”一般不说“在工作”。"}, "sentence_index": 6, "correct_answer": "神经元"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她长期神经元衰弱，已经有一年睡不好觉了。", "explanation": "这里应该用〈神经衰弱〉。“神经衰弱”是固定说法，指精神疲劳、失眠的病症；神经元是细胞，不能这样组合。"}, {"text": "这孩子神经元兮兮的，老是疑神疑鬼。", "explanation": "这里应该用〈神经兮兮〉。“神经兮兮”形容人过分紧张、疑神疑鬼；神经元是细胞，不能用来形容性格。"}, {"text": "神经元是身体里的神经中枢。", "explanation": "这里应该用〈大脑〉。大脑与脊髓共同构成中枢神经系统，神经元只是构成神经系统的细胞，不能指整个中枢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43b210fc-d3d7-441e-83e1-71bbf100a917') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22846, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "很多神经元们都在工作。", "corrected_sentence": "很多神经元都在工作。", "error_description": "错误形式：“神经元们”；正确形式：“神经元”。“们”只用于指人或拟人的群体，神经元是物体，不加“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43b210fc-d3d7-441e-83e1-71bbf100a917') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22846, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两神经元之间通过突触传递信号。", "corrected_sentence": "两个神经元之间通过突触传递信号。", "error_description": "错误形式：“两神经元”；正确形式：“两个神经元”。数词与“神经元”之间要加量词“个”，不能省略。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43b210fc-d3d7-441e-83e1-71bbf100a917') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
