INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22850, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "研究人们怎么想、怎么感觉、为什么这样做的人。", "primary_collocate": null, "pronunciation": "xīn lǐ xué jiā", "ipa": "ɕin˥ li˨˩˦ ɕɥe˧˥ tɕja˥", "syllable_count": 4, "sentences": [{"text": "心理学家想知道人为什么会害怕。", "target_word": "心理学家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他爸爸是一位心理学家。", "target_word": "心理学家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "心理学家做了一个有趣的实验。", "target_word": "心理学家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位心理学家帮我找到了问题。", "target_word": "心理学家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想问心理学家，人为什么爱睡懒觉。", "target_word": "心理学家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "心理学家会观察人们怎么做决定。", "target_word": "心理学家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视里有一位心理学家在讲话。", "target_word": "心理学家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她当了十年心理学家。", "target_word": "心理学家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "心理学家告诉我们，笑能让人放松。", "target_word": "心理学家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那名心理学家把答案写在纸上。", "target_word": "心理学家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "儿童心理学家", "label": "复合"}], "register": "中性", "sense_fingerprint": "心理学家|研究人怎么想怎么做的人|名词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8cbebb4-22b2-4457-b7ac-21ebb866bd00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22850, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "心理学家", "is_correct": true, "explanation": "心理学家研究人怎么想、为什么这样做，正适合作“想知道”的主语，句意通顺。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱没有思维，不会“想知道”人为什么害怕。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟是无生命的物体，不能“想知道”任何事情。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有思维，不会“想知道”人为什么害怕。"}], "explanations": {"心理学家": "心理学家研究人怎么想、为什么这样做，正适合作“想知道”的主语，句意通顺。", "冰箱": "语义：冰箱没有思维，不会“想知道”人为什么害怕。", "闹钟": "语义：闹钟是无生命的物体，不能“想知道”任何事情。", "石头": "语义：石头没有思维，不会“想知道”人为什么害怕。"}, "sentence_index": 0, "correct_answer": "心理学家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "心理学家给病人做了手术。", "explanation": "这里应该用〈外科医生〉。做手术需要医学训练，心理学家研究人的想法和行为，不做手术。"}, {"text": "心理学家观测到了一颗新的彗星。", "explanation": "这里应该用〈天文学家〉。观测彗星属于天文学，心理学家研究的是人的心理活动。"}, {"text": "心理学家给病人拔了一颗智齿。", "explanation": "这里应该用〈牙医〉。拔牙需要口腔医学的专业技能，心理学家不做这类操作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742cd520-0a5e-4792-82d4-d2db45d8b7fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22850, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "心理学家", "is_correct": true, "explanation": "心理学家可以在电视上讲话，与“电视里有一位……在讲话”的句意相符。"}, {"text": "哑巴", "is_correct": false, "explanation": "语义：哑巴不能说话，与“在讲话”的描述相矛盾。"}, {"text": "植物人", "is_correct": false, "explanation": "语义：植物人没有意识，无法在电视里讲话。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子不会讲话，与“电视里……在讲话”的主语不成立。"}], "explanations": {"心理学家": "心理学家可以在电视上讲话，与“电视里有一位……在讲话”的句意相符。", "哑巴": "语义：哑巴不能说话，与“在讲话”的描述相矛盾。", "植物人": "语义：植物人没有意识，无法在电视里讲话。", "椅子": "语义：椅子不会讲话，与“电视里……在讲话”的主语不成立。"}, "sentence_index": 6, "correct_answer": "心理学家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那位心理学家把车修好了。", "explanation": "这里应该用〈修车师傅〉。修车需要机械技能，心理学家研究人的心理，不做这类工作。"}, {"text": "那位心理学家在工地上砌好了墙。", "explanation": "这里应该用〈泥瓦匠〉。砌墙需要建筑手艺，心理学家研究人的心理，不做这类工作。"}, {"text": "那位心理学家把货物装上了卡车。", "explanation": "这里应该用〈装卸工〉。搬运货物是体力活，心理学家研究人的心理，不做这类工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742cd520-0a5e-4792-82d4-d2db45d8b7fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22850, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这所大学请来了一只心理学家。", "corrected_sentence": "这所大学请来了一名心理学家。", "error_description": "量词错误：“心理学家”指人，应用“名”或“位”，“只”用于动物。错误形式是“一只心理学家”，正确形式是“一名心理学家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742cd520-0a5e-4792-82d4-d2db45d8b7fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22850, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她当过了心理学家，现在在大学教书。", "corrected_sentence": "她当过心理学家，现在在大学教书。", "error_description": "体标重复：经历体“过”与完成体“了”不能同时用于同一动词，应去掉“了”。错误形式是“当过了心理学家”，正确形式是“当过心理学家”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742cd520-0a5e-4792-82d4-d2db45d8b7fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22852, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "疏远", "is_correct": true, "explanation": "“疏远”与“亲近”意义相反，指感情不深、不愿接近，是反义词。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”形容光线充足，与“亲近”不构成反义。"}, {"text": "简单", "is_correct": false, "explanation": "“简单”形容不复杂，与“亲近”没有反义关系。"}, {"text": "柔软", "is_correct": false, "explanation": "“柔软”形容质地不硬，与“亲近”不构成反义。"}], "correct_answer": "疏远", "explanations": {"疏远": "“疏远”与“亲近”意义相反，指感情不深、不愿接近，是反义词。", "明亮": "“明亮”形容光线充足，与“亲近”不构成反义。", "简单": "“简单”形容不复杂，与“亲近”没有反义关系。", "柔软": "“柔软”形容质地不硬，与“亲近”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742cd520-0a5e-4792-82d4-d2db45d8b7fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22852, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "疏远", "is_correct": true, "explanation": "“疏远”与“亲近”意义相反，指感情不深、不愿接近，是反义词。"}, {"text": "迟钝", "is_correct": false, "explanation": "“迟钝”形容反应慢，与“亲近”不构成反义。"}, {"text": "宽大", "is_correct": false, "explanation": "“宽大”形容面积大或待人宽厚，与“亲近”没有反义关系。"}, {"text": "整齐", "is_correct": false, "explanation": "“整齐”形容排列有序，与“亲近”不构成反义。"}], "correct_answer": "疏远", "explanations": {"疏远": "“疏远”与“亲近”意义相反，指感情不深、不愿接近，是反义词。", "迟钝": "“迟钝”形容反应慢，与“亲近”不构成反义。", "宽大": "“宽大”形容面积大或待人宽厚，与“亲近”没有反义关系。", "整齐": "“整齐”形容排列有序，与“亲近”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742cd520-0a5e-4792-82d4-d2db45d8b7fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22852, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "两个人关系好，喜欢在一起。", "primary_collocate": null, "pronunciation": "qīn jìn", "ipa": "tɕʰin˥ tɕin˥˩", "syllable_count": 2, "sentences": [{"text": "他们两个人很亲近，天天一起上学。", "target_word": "亲近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我弟弟和小狗特别亲近，睡觉也在一起。", "target_word": "亲近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这对姐妹从小就亲近，什么都一起做。", "target_word": "亲近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子和爷爷很亲近，总想跟爷爷玩。", "target_word": "亲近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她们俩亲近得像一个人。", "target_word": "亲近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和新同桌越来越亲近了，下课总在一起。", "target_word": "亲近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他和哥哥不太亲近，很少一起玩。", "target_word": "亲近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只猫只和我亲近，不让别人摸。", "target_word": "亲近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新来的同学很快就和大家亲近起来了。", "target_word": "亲近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夫妻俩很亲近，周末总是一起散步。", "target_word": "亲近", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "亲近了", "label": "体标"}, {"form": "親近", "label": "繁体"}], "register": "中性", "sense_fingerprint": "两人感情好、愿意待在一起的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8cbebb4-22b2-4457-b7ac-21ebb866bd00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22852, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "亲近", "is_correct": true, "explanation": "“亲近”指两人感情好、愿意待在一起，与“天天一起上学”相符。"}, {"text": "疏远", "is_correct": false, "explanation": "语义：疏远指关系不好，与“天天一起上学”相矛盾。"}, {"text": "冷清", "is_correct": false, "explanation": "搭配：“冷清”多形容地方或场面，不用来形容两个人的感情。"}, {"text": "生疏", "is_correct": false, "explanation": "语义：生疏指彼此不熟悉，与“天天一起上学”相矛盾。"}], "explanations": {"亲近": "“亲近”指两人感情好、愿意待在一起，与“天天一起上学”相符。", "疏远": "语义：疏远指关系不好，与“天天一起上学”相矛盾。", "冷清": "搭配：“冷清”多形容地方或场面，不用来形容两个人的感情。", "生疏": "语义：生疏指彼此不熟悉，与“天天一起上学”相矛盾。"}, "sentence_index": 0, "correct_answer": "亲近"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们俩的座位亲近。", "explanation": "这里应该用〈挨着〉。亲近形容人与人之间感情好，不用于说座位的位置关系。"}, {"text": "这两个国家的贸易很亲近。", "explanation": "这里应该用〈密切〉。亲近形容人与人之间的感情，贸易往来一般用“密切”。"}, {"text": "春节越来越亲近了。", "explanation": "这里应该用〈临近〉。亲近指两人关系好、喜欢在一起，不能用来说节日快到了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742cd520-0a5e-4792-82d4-d2db45d8b7fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22852, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "亲近", "is_correct": true, "explanation": "“不太亲近”指两人感情不深、不常在一起，与“很少一起玩”相符。"}, {"text": "热闹", "is_correct": false, "explanation": "搭配：“热闹”形容场面，不用来形容两个人的关系。"}, {"text": "陡峭", "is_correct": false, "explanation": "搭配：“陡峭”形容地势，不能用来形容人与人之间的关系。"}, {"text": "锋利", "is_correct": false, "explanation": "语义：锋利指刀具等尖锐，与人际关系无关，句意不通。"}], "explanations": {"亲近": "“不太亲近”指两人感情不深、不常在一起，与“很少一起玩”相符。", "热闹": "搭配：“热闹”形容场面，不用来形容两个人的关系。", "陡峭": "搭配：“陡峭”形容地势，不能用来形容人与人之间的关系。", "锋利": "语义：锋利指刀具等尖锐，与人际关系无关，句意不通。"}, "sentence_index": 6, "correct_answer": "亲近"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "超市亲近学校。", "explanation": "这里应该用〈临近〉。亲近指人与人之间感情好，不用于说超市与学校的位置。"}, {"text": "两个房间亲近。", "explanation": "这里应该用〈相连〉。亲近形容人与人之间的感情，不用于描述房间的位置关系。"}, {"text": "车慢慢亲近了终点。", "explanation": "这里应该用〈接近〉。亲近指人与人之间感情好、愿意待在一起，不用于车辆驶向终点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742cd520-0a5e-4792-82d4-d2db45d8b7fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22852, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两个朋友亲近，周末常一起去公园。", "corrected_sentence": "这两个朋友很亲近，周末常一起去公园。", "error_description": "程度副词缺失：形容词“亲近”作谓语时，前面一般要加程度副词“很”。错误形式是“这两个朋友亲近”，正确形式是“这两个朋友很亲近”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742cd520-0a5e-4792-82d4-d2db45d8b7fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22852, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子和妈妈一直亲近得。", "corrected_sentence": "孩子和妈妈一直亲近得很。", "error_description": "补语错误：“亲近得”后面缺少程度补语。错误形式是“亲近得”，正确形式是“亲近得很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742cd520-0a5e-4792-82d4-d2db45d8b7fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
