INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22854, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "病从一个人身上跑到另一个人身上，让别人也生病。", "primary_collocate": null, "pronunciation": "chuán rǎn", "ipa": "ʈʂʰwan˧˥ ʐan˨˩˦", "syllable_count": 2, "sentences": [{"text": "流感很容易传染。", "target_word": "传染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他感冒了，会传染给你。", "target_word": "传染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种病不会传染，别害怕。", "target_word": "传染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子生病了，要小心别传染给弟弟。", "target_word": "传染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，咳嗽的人要戴口罩，以免传染别人。", "target_word": "传染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手上的细菌也会把疾病传染给别人。", "target_word": "传染", "complexity_tier": "T3", "furigana": "shǒu shang de xì jūn yě huì bǎ jí bìng chuán rǎn gěi bié rén。", "sentence_source": "generated"}, {"text": "妈妈怕我把病传染给同学，让我在家休息。", "target_word": "传染", "complexity_tier": "T3", "furigana": "mā ma pà wǒ bǎ bìng chuán rǎn gěi tóng xué， ràng wǒ zài jiā xiū xi。", "sentence_source": "generated"}, {"text": "这个病通过空气传染。", "target_word": "传染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校里有人发烧，所以大家都很怕传染。", "target_word": "传染", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把感冒传染给了全家人。", "target_word": "传染", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "传染了", "label": "体标"}, {"form": "传染过", "label": "体标"}, {"form": "传染病", "label": "复合词"}, {"form": "传染源", "label": "复合词"}, {"form": "傳染", "label": "繁体"}], "register": "中性", "sense_fingerprint": "疾病从病人传给别人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b10fc90c-0e14-449a-94f1-3095b8172350') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22854, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "传染", "is_correct": true, "explanation": "传染：病从一人身上传到另一人身上，正好符合「流感很容易……」的语境。"}, {"text": "熄灭", "is_correct": false, "explanation": "语义：熄灭指火或光灭掉，不能用来说流感的传播。"}, {"text": "撕裂", "is_correct": false, "explanation": "语义：撕裂指东西被扯开，与「流感很容易」的语境毫不相关。"}, {"text": "通报", "is_correct": false, "explanation": "配价：通报需要带宾语（通报某事），且属于公文用语，「流感很容易通报」不成立。"}], "explanations": {"传染": "传染：病从一人身上传到另一人身上，正好符合「流感很容易……」的语境。", "熄灭": "语义：熄灭指火或光灭掉，不能用来说流感的传播。", "撕裂": "语义：撕裂指东西被扯开，与「流感很容易」的语境毫不相关。", "通报": "配价：通报需要带宾语（通报某事），且属于公文用语，「流感很容易通报」不成立。"}, "sentence_index": 0, "correct_answer": "传染"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的伤口传染了，要去医院。", "explanation": "这里应该用〈感染〉。伤口因细菌发炎用感染；传染指病从一人传给另一人，不用于伤口本身。"}, {"text": "他把这个消息传染给了大家。", "explanation": "这里应该用〈传播〉。消息、知识的扩散用传播；传染多指疾病的传播，比喻时用于情绪、笑声等，不用于消息。"}, {"text": "大火迅速传染到邻居家。", "explanation": "这里应该用〈蔓延〉。火势、灾害的扩展用蔓延；传染指病从一人传给另一人，不用于火势。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43b210fc-d3d7-441e-83e1-71bbf100a917') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22854, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "传染", "is_correct": true, "explanation": "传染：病从我身上传给同学，正好符合「把病……给同学」的语境。"}, {"text": "修理", "is_correct": false, "explanation": "语义：修理指修补器物，不能把病修理给别人。"}, {"text": "收藏", "is_correct": false, "explanation": "搭配：收藏的对象多是物品，不能说收藏病。"}, {"text": "咨询", "is_correct": false, "explanation": "配价：咨询的对象是人或机构（向……咨询），「把病咨询给同学」不成立。"}], "explanations": {"传染": "传染：病从我身上传给同学，正好符合「把病……给同学」的语境。", "修理": "语义：修理指修补器物，不能把病修理给别人。", "收藏": "搭配：收藏的对象多是物品，不能说收藏病。", "咨询": "配价：咨询的对象是人或机构（向……咨询），「把病咨询给同学」不成立。"}, "sentence_index": 6, "correct_answer": "传染"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块地我传染给了朋友。", "explanation": "这里应该用〈转让〉。转让指把财产或权利交给别人，传染只用于疾病。"}, {"text": "他把包裹传染给了朋友。", "explanation": "这里应该用〈寄〉。寄指邮寄物品，传染只用于疾病从人传给人。"}, {"text": "她把礼物传染给了朋友。", "explanation": "这里应该用〈送〉。送礼物是赠予，传染只用于疾病的传播。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43b210fc-d3d7-441e-83e1-71bbf100a917') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22854, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把病传染了同学。", "corrected_sentence": "他把病传染给了同学。", "error_description": "「传染」引出受事者时要用「给」，应说「把病传染给了同学」，不能省略「给」说「传染了同学」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43b210fc-d3d7-441e-83e1-71bbf100a917') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22854, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种病在夏天很容易传染了给孩子。", "corrected_sentence": "这种病在夏天很容易传染给孩子。", "error_description": "「了」不能插在「传染」和「给」之间。应删去「了」，说「很容易传染给孩子」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43b210fc-d3d7-441e-83e1-71bbf100a917') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
