INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22856, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示全部、彻底，没有保留或例外。", "primary_collocate": null, "pronunciation": "wán quán", "ipa": "wan˧˥ tɕʰɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "我完全同意你的看法。", "target_word": "完全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说的话我完全听不懂。", "target_word": "完全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事完全是我的错。", "target_word": "完全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你完全不用担心。", "target_word": "完全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个人完全不一样。", "target_word": "完全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我完全忘了今天是他的生日。", "target_word": "完全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的病已经完全好了。", "target_word": "完全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里完全没有声音。", "target_word": "完全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对这个城市完全不了解。", "target_word": "完全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师讲的我完全明白。", "target_word": "完全", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "完完全全", "label": "重叠"}], "register": "中性", "sense_fingerprint": "毫无保留，百分之百", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13b584fe-81b3-45c5-b43f-c258eb988e16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22856, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "完全", "is_correct": true, "explanation": "完全：表示全部、彻底，修饰“同意”，表达很肯定的态度。"}, {"text": "丝毫", "is_correct": false, "explanation": "搭配：“丝毫”要与否定词连用，如“丝毫不同意”，这里是肯定句。"}, {"text": "根本", "is_correct": false, "explanation": "搭配：“根本”多与否定词连用，说“根本同意”不合语境。"}, {"text": "从不", "is_correct": false, "explanation": "语义：“从不”表示一次都没有，与“同意”的肯定态度相反。"}], "explanations": {"完全": "完全：表示全部、彻底，修饰“同意”，表达很肯定的态度。", "丝毫": "搭配：“丝毫”要与否定词连用，如“丝毫不同意”，这里是肯定句。", "根本": "搭配：“根本”多与否定词连用，说“根本同意”不合语境。", "从不": "语义：“从不”表示一次都没有，与“同意”的肯定态度相反。"}, "sentence_index": 0, "correct_answer": "完全"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他完全快到了。", "explanation": "这里应该用〈几乎〉。完全表示彻底、全部，不表示“差一点”。"}, {"text": "我完全有一个苹果。", "explanation": "这里应该用〈仅〉。完全表示全部、彻底，表示“仅有一个”要用“仅”。"}, {"text": "他完全三岁了。", "explanation": "这里应该用〈刚〉。完全表示全部、彻底，表示“刚满”要用“刚”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd255a78-aea1-4968-8fb6-1b75f37cd5d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22856, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "完全", "is_correct": true, "explanation": "完全：表示彻底、全部，修饰“好”，说明病已经全好了。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”多与否定词连用，“已经从来好了”不合语境。"}, {"text": "始终", "is_correct": false, "explanation": "语义：始终表示一直如此，与“已经好了”的变化相矛盾。"}, {"text": "仍然", "is_correct": false, "explanation": "语义：仍然表示状态没有改变，与“已经好了”相矛盾。"}], "explanations": {"完全": "完全：表示彻底、全部，修饰“好”，说明病已经全好了。", "从来": "搭配：“从来”多与否定词连用，“已经从来好了”不合语境。", "始终": "语义：始终表示一直如此，与“已经好了”的变化相矛盾。", "仍然": "语义：仍然表示状态没有改变，与“已经好了”相矛盾。"}, "sentence_index": 6, "correct_answer": "完全"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我完全明白了一部分。", "explanation": "这里应该用〈只〉。完全表示全部，与“一部分”相矛盾。"}, {"text": "我完全明白了一点。", "explanation": "这里应该用〈稍微〉。完全表示全部，与“一点”相矛盾。"}, {"text": "我完全做了一半作业。", "explanation": "这里应该用〈只〉。完全表示全部，与“一半”相矛盾，表示部分要用“只”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd255a78-aea1-4968-8fb6-1b75f37cd5d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22856, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他完全的理解你的想法。", "corrected_sentence": "他完全理解你的想法。", "error_description": "“完全”修饰动词时要直接放在动词前，不能在中间加“的”。应说“完全理解”，不说“完全的理解”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd255a78-aea1-4968-8fb6-1b75f37cd5d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22856, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是一个完全地陌生人。", "corrected_sentence": "他是一个完全的陌生人。", "error_description": "修饰名词的成分要用“的”，不用“地”。“完全”修饰名词“陌生人”时应说“完全的陌生人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd255a78-aea1-4968-8fb6-1b75f37cd5d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
