INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22862, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70277f0c-921d-42eb-8929-b89d25e8f429') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22862, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "就是一定、不会变的意思。", "primary_collocate": null, "pronunciation": "kěn dìng", "ipa": "kʰən˨˩˦ tiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他肯定会来参加明天的会。", "target_word": "肯定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天这么黑，现在肯定很晚了。", "target_word": "肯定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你这样做，他肯定不高兴。", "target_word": "肯定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别担心，这件事我肯定帮你。", "target_word": "肯定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看这云，下午肯定要下雨。", "target_word": "肯定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这么难的题，他肯定不会做。", "target_word": "肯定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "灯还亮着，他肯定在家。", "target_word": "肯定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他肯定是忘了，所以没有回电话。", "target_word": "肯定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你放心，我肯定准时到。", "target_word": "肯定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她学了十年，肯定说得很好。", "target_word": "肯定", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "表示推断或决心上的一定、必然", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c21dd34c-16ba-43e7-a982-0b6076900aea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22862, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "肯定", "is_correct": true, "explanation": "正确：“肯定会来”表示推断或决心上一定会，符合语境。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”须与否定词连用，如“从来不来”，不能直接用在“会来”前。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：“曾经”指过去，与句中的“明天”冲突。"}, {"text": "刚", "is_correct": false, "explanation": "语义：“刚”表示刚刚发生，与将来的“明天”不能搭配。"}], "explanations": {"肯定": "正确：“肯定会来”表示推断或决心上一定会，符合语境。", "从来": "搭配：“从来”须与否定词连用，如“从来不来”，不能直接用在“会来”前。", "曾经": "语义：“曾经”指过去，与句中的“明天”冲突。", "刚": "语义：“刚”表示刚刚发生，与将来的“明天”不能搭配。"}, "sentence_index": 0, "correct_answer": "肯定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他肯定会来参加明天的会，但概率很低。", "explanation": "这里应该用〈可能〉。“肯定”表示一定，与“概率很低”的不确定语义矛盾；表示不确定时用“可能”。"}, {"text": "他肯定会来，也许不会。", "explanation": "这里应该用〈可能〉。“肯定”表示一定，与后面的“也许不会”自相矛盾；表示不确定时用“可能”。"}, {"text": "他肯定会来参加明天的会，但我不确定。", "explanation": "这里应该用〈也许〉。“肯定”表示一定，与“不确定”的语义相矛盾；表示不确定时用“也许”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70277f0c-921d-42eb-8929-b89d25e8f429') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22862, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "肯定", "is_correct": true, "explanation": "正确：“肯定在家”表示推断一定，与“灯还亮着”的线索相符。"}, {"text": "拿", "is_correct": false, "explanation": "配价：「拿」需带宾语（拿东西），「他拿在家」不成句。"}, {"text": "哭", "is_correct": false, "explanation": "搭配：「哭」不能直接接「在家」，「他哭在家」不成句。"}, {"text": "再", "is_correct": false, "explanation": "搭配：“再”表示重复或继续，不能直接修饰“在家”来表示推断。"}], "explanations": {"肯定": "正确：“肯定在家”表示推断一定，与“灯还亮着”的线索相符。", "拿": "配价：「拿」需带宾语（拿东西），「他拿在家」不成句。", "哭": "搭配：「哭」不能直接接「在家」，「他哭在家」不成句。", "再": "搭配：“再”表示重复或继续，不能直接修饰“在家”来表示推断。"}, "sentence_index": 6, "correct_answer": "肯定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她学了十年，肯定可能说得很好。", "explanation": "这里应该用〈也许〉。“肯定”表示一定，与“可能”的不确定语义矛盾，不能并用。"}, {"text": "她学了十年，肯定说得很好，但我不太确定。", "explanation": "这里应该用〈也许〉。“肯定”表示一定，与“不太确定”的语义相矛盾，表示不确定时用“也许”。"}, {"text": "她学了十年，肯定或许说得很好。", "explanation": "这里应该用〈也许〉。“肯定”表示一定，与“或许”的不确定语义相矛盾，不能并用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70277f0c-921d-42eb-8929-b89d25e8f429') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22862, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她肯定的会同意这个计划。", "corrected_sentence": "她肯定会同意这个计划。", "error_description": "副词“肯定”后不能加“的”，“肯定”直接修饰“会”，应说“肯定会”，不说“肯定的会”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70277f0c-921d-42eb-8929-b89d25e8f429') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22862, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他肯定没了在家。", "corrected_sentence": "他肯定没在家。", "error_description": "“没在家”中“没”直接接“在家”，不能在“没”后加“了”；“没了”只表示“没有了”，不能接“在家”，应说“肯定没在家”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70277f0c-921d-42eb-8929-b89d25e8f429') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22866, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77847b03-2610-4297-853f-69b8a98d0392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
