INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22866, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "concrete", "definition": "里面藏着，比如盒子里有东西。", "primary_collocate": null, "pronunciation": "yùn hán zhe", "ipa": "yn˥˩ xan˧˥ ʈʂɤ", "syllable_count": 3, "sentences": [{"text": "这个神秘的小盒子里蕴含着一份惊喜。", "target_word": "蕴含着", "complexity_tier": "T3", "furigana": "zhè ge shén mì de xiǎo hé zi lǐ yùn hán zhe yí fèn jīng xǐ。", "sentence_source": "generated"}, {"text": "大山深处蕴含着丰富的矿产。", "target_word": "蕴含着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片土地的地下蕴含着大量的石油。", "target_word": "蕴含着", "complexity_tier": "T3", "furigana": "zhè piàn tǔ dì de dì xià yùn hán zhe dà liàng de shí yóu。", "sentence_source": "generated"}, {"text": "海底蕴含着许多人们不知道的宝藏。", "target_word": "蕴含着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "温泉里蕴含着对身体好的矿物质。", "target_word": "蕴含着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块石头里蕴含着一颗漂亮的宝石。", "target_word": "蕴含着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙漠地下蕴含着丰富的水。", "target_word": "蕴含着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座小山里蕴含着很多煤。", "target_word": "蕴含着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每颗蛋的内部都蕴含着一个小生命。", "target_word": "蕴含着", "complexity_tier": "T3", "furigana": "měi kē dàn de nèi bù dōu yùn hán zhe yí gè xiǎo shēng mìng。", "sentence_source": "generated"}, {"text": "这个木箱深处蕴含着奶奶留下的一件旧物。", "target_word": "蕴含着", "complexity_tier": "T3", "furigana": "zhè ge mù xiāng shēn chù yùn hán zhe nǎi nai liú xià de yí jiàn jiù wù。", "sentence_source": "generated"}], "morphological_forms": [{"form": "蕴含", "label": "基本形式"}, {"form": "蕴含了", "label": "体标"}, {"form": "蘊含著", "label": "繁体"}], "register": "书面", "sense_fingerprint": "里面藏有具体的东西或资源", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84185793-b8d0-46b1-818d-128e201d234b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22866, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "宣读着", "is_correct": false, "explanation": "搭配：“宣读”的对象是文件、声明，不能说“宣读一份惊喜”。"}, {"text": "批准着", "is_correct": false, "explanation": "语义：“批准”指同意申请或计划，“惊喜”不是可以被批准的事物，与句意不符。"}, {"text": "蕴含着", "is_correct": true, "explanation": "正确：“蕴含着”表示盒子里面藏有东西，与“神秘的小盒子里”的语境相符。"}, {"text": "消失着", "is_correct": false, "explanation": "配价：“消失”是不及物动词，后面不能直接带“一份惊喜”这样的宾语。"}], "explanations": {"宣读着": "搭配：“宣读”的对象是文件、声明，不能说“宣读一份惊喜”。", "批准着": "语义：“批准”指同意申请或计划，“惊喜”不是可以被批准的事物，与句意不符。", "蕴含着": "正确：“蕴含着”表示盒子里面藏有东西，与“神秘的小盒子里”的语境相符。", "消失着": "配价：“消失”是不及物动词，后面不能直接带“一份惊喜”这样的宾语。"}, "sentence_index": 0, "correct_answer": "蕴含着"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个团队蕴含着十名队员。", "explanation": "这里应该用〈包括〉。蕴含指东西藏在某物内部，说团队由哪些成员组成要用“包括”。"}, {"text": "这座体育馆蕴含着五千名观众。", "explanation": "这里应该用〈容纳〉。蕴含指东西藏在某处，说场地能装下多少人要用“容纳”。"}, {"text": "这家医院蕴含着三十名医生。", "explanation": "这里应该用〈拥有〉。蕴含指东西藏在内部，说医院有多少医生要用“拥有”或“有”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77847b03-2610-4297-853f-69b8a98d0392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22866, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "演奏着", "is_correct": false, "explanation": "搭配：“演奏”的对象是音乐，不能说“演奏丰富的水”。"}, {"text": "饲养着", "is_correct": false, "explanation": "搭配：“饲养”的对象是动物，不能说“饲养丰富的水”。"}, {"text": "舞动着", "is_correct": false, "explanation": "语义：“舞动”指挥动、摆动，与地下水资源的描述不相干。"}, {"text": "蕴含着", "is_correct": true, "explanation": "正确：“蕴含着”表示地下藏有丰富的水，与句子语境相符。"}], "explanations": {"演奏着": "搭配：“演奏”的对象是音乐，不能说“演奏丰富的水”。", "饲养着": "搭配：“饲养”的对象是动物，不能说“饲养丰富的水”。", "舞动着": "语义：“舞动”指挥动、摆动，与地下水资源的描述不相干。", "蕴含着": "正确：“蕴含着”表示地下藏有丰富的水，与句子语境相符。"}, "sentence_index": 6, "correct_answer": "蕴含着"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "墙上蕴含着一幅画。", "explanation": "这里应该用〈挂〉。蕴含指东西藏在内部，挂在墙面上要用“挂”，不能用蕴含。"}, {"text": "窗户上蕴含着一张贺卡。", "explanation": "这里应该用〈贴〉。蕴含指东西藏在内部，贴在窗户表面要用“贴”，不能用蕴含。"}, {"text": "桌上蕴含着一束花。", "explanation": "这里应该用〈摆〉。蕴含指东西藏在里面，放在桌面上要用“摆”，不能用蕴含。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77847b03-2610-4297-853f-69b8a98d0392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22866, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座山的岩层里蕴含了着很多铁矿。", "corrected_sentence": "这座山的岩层里蕴含着很多铁矿。", "error_description": "错误：“蕴含”后面同时用了“了”和“着”两个体标。正确：只用“着”，即“蕴含着”，因为这里表示的是持续存在的状态。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77847b03-2610-4297-853f-69b8a98d0392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22866, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这片戈壁深处蕴含着丰富地石油。", "corrected_sentence": "这片戈壁深处蕴含着丰富的石油。", "error_description": "结构助词错误：“丰富”修饰名词“石油”，应用“的”，不用“地”（“地”用于修饰动词）。正确：“丰富的石油”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77847b03-2610-4297-853f-69b8a98d0392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22868, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "公开", "is_correct": true, "explanation": "「秘密」指不让别人知道，「公开」指让大家都知道，二者是反义关系。"}, {"text": "答案", "is_correct": false, "explanation": "「答案」与「秘密」没有反义关系，二者不构成对立。"}, {"text": "故事", "is_correct": false, "explanation": "「故事」与「秘密」没有反义关系，二者不构成对立。"}, {"text": "礼物", "is_correct": false, "explanation": "「礼物」与「秘密」没有反义关系，二者不构成对立。"}], "correct_answer": "公开", "explanations": {"公开": "「秘密」指不让别人知道，「公开」指让大家都知道，二者是反义关系。", "答案": "「答案」与「秘密」没有反义关系，二者不构成对立。", "故事": "「故事」与「秘密」没有反义关系，二者不构成对立。", "礼物": "「礼物」与「秘密」没有反义关系，二者不构成对立。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70277f0c-921d-42eb-8929-b89d25e8f429') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22868, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "公开", "is_correct": true, "explanation": "「秘密」指不让别人知道，「公开」指让大家都知道，二者是反义关系。"}, {"text": "日记", "is_correct": false, "explanation": "「日记」与「秘密」没有反义关系，二者不构成对立。"}, {"text": "消息", "is_correct": false, "explanation": "「消息」与「秘密」没有反义关系，二者不构成对立。"}, {"text": "窗户", "is_correct": false, "explanation": "「窗户」与「秘密」没有反义关系，二者不构成对立。"}], "correct_answer": "公开", "explanations": {"公开": "「秘密」指不让别人知道，「公开」指让大家都知道，二者是反义关系。", "日记": "「日记」与「秘密」没有反义关系，二者不构成对立。", "消息": "「消息」与「秘密」没有反义关系，二者不构成对立。", "窗户": "「窗户」与「秘密」没有反义关系，二者不构成对立。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70277f0c-921d-42eb-8929-b89d25e8f429') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22868, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "当事人不想让别人知道的事。", "primary_collocate": null, "pronunciation": "mì mì", "ipa": "mi˥˩ mi˥˩", "syllable_count": 2, "sentences": [{"text": "我知道他的一个大秘密。", "target_word": "秘密", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友把秘密告诉了我，我不能说。", "target_word": "秘密", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子也有自己的小秘密。", "target_word": "秘密", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个秘密只有妈妈知道。", "target_word": "秘密", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她怕同事知道这个秘密，一直很小心。", "target_word": "秘密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有守住秘密，第二天大家都知道了。", "target_word": "秘密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你有什么秘密不想让人知道吗？", "target_word": "秘密", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司的秘密不能随便说出去。", "target_word": "秘密", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们约好，永远不说这个秘密。", "target_word": "秘密", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她在信里写下了心里的秘密。", "target_word": "秘密", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "秘密会议", "label": "复合"}], "register": "中性", "sense_fingerprint": "当事人不愿让别人知道的私事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c21dd34c-16ba-43e7-a982-0b6076900aea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22868, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "秘密", "is_correct": true, "explanation": "「一个大秘密」指他不愿让别人知道的事，符合题干语境。"}, {"text": "钥匙", "is_correct": false, "explanation": "量词与语义：「钥匙」用「把」计量，「一个大钥匙」不成句。"}, {"text": "照片", "is_correct": false, "explanation": "搭配：「照片」用「张」计量，不说「一个大照片」。"}, {"text": "信件", "is_correct": false, "explanation": "搭配：「信件」用「封」计量，不说「一个大信件」。"}], "explanations": {"秘密": "「一个大秘密」指他不愿让别人知道的事，符合题干语境。", "钥匙": "量词与语义：「钥匙」用「把」计量，「一个大钥匙」不成句。", "照片": "搭配：「照片」用「张」计量，不说「一个大照片」。", "信件": "搭配：「信件」用「封」计量，不说「一个大信件」。"}, "sentence_index": 0, "correct_answer": "秘密"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "请输入你的登录秘密。", "explanation": "这里应该用〈密码〉。登录时输入的是“密码”，“秘密”指别人不想让人知道的事。"}, {"text": "这座老房子的气氛很秘密。", "explanation": "这里应该用〈神秘〉。形容气氛的隐秘感要用“神秘”；“秘密”作形容词多指不公开的事，搭配“气氛”不自然。"}, {"text": "他藏起了一根秘密，谁也不知道。", "explanation": "这里应该用〈个〉。“根”用于线、绳、刺等细长的东西，“秘密”不能用“根”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70277f0c-921d-42eb-8929-b89d25e8f429') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22868, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "秘密", "is_correct": true, "explanation": "「什么秘密」指别人不知道的事，「不想让人知道」与之相合。"}, {"text": "天气", "is_correct": false, "explanation": "语义：「天气」不是可以隐藏的事情，「你有什么天气不想让人知道」不成立。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：「椅子」是家具，不是需要隐瞒的事，「你有什么椅子不想让人知道」不成立。"}, {"text": "脸色", "is_correct": false, "explanation": "体貌：「脸色」是外露的神情，无法像秘密那样刻意隐藏，与「不想让人知道」不搭。"}], "explanations": {"秘密": "「什么秘密」指别人不知道的事，「不想让人知道」与之相合。", "天气": "语义：「天气」不是可以隐藏的事情，「你有什么天气不想让人知道」不成立。", "椅子": "语义：「椅子」是家具，不是需要隐瞒的事，「你有什么椅子不想让人知道」不成立。", "脸色": "体貌：「脸色」是外露的神情，无法像秘密那样刻意隐藏，与「不想让人知道」不搭。"}, "sentence_index": 6, "correct_answer": "秘密"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她心里藏着一张秘密。", "explanation": "这里应该用〈个〉。“张”用于纸张、桌子等平面的东西，“秘密”用“个”计量。"}, {"text": "他心里揣着一只秘密。", "explanation": "这里应该用〈个〉。“只”用于动物或成对的东西，不用于“秘密”。"}, {"text": "他把一封秘密交给了我。", "explanation": "这里应该用〈个〉。“封”用于信件，“秘密”不能用“封”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70277f0c-921d-42eb-8929-b89d25e8f429') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22868, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把守住了秘密。", "corrected_sentence": "我守住了秘密。", "error_description": "“把”字句要求“把+宾语+动词”，“守住”前不能只加“把”，应说“我守住了秘密”，不说“我把守住了秘密”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70277f0c-921d-42eb-8929-b89d25e8f429') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22868, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她没有告诉任何人这本秘密。", "corrected_sentence": "她没有告诉任何人这个秘密。", "error_description": "“秘密”用“个”计量，“本”用于书籍等，不说“这本秘密”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70277f0c-921d-42eb-8929-b89d25e8f429') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
