INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22870, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让身体或心里不紧张，变得舒服。", "primary_collocate": null, "pronunciation": "fàng sōng", "ipa": "faŋ˥˩ sʊŋ˥", "syllable_count": 2, "sentences": [{"text": "周末我想在家放松放松。", "target_word": "放松", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听着轻音乐，她慢慢放松下来。", "target_word": "放松", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "泡个热水澡，让身体放松一下。", "target_word": "放松", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "假期里我们去海边放松。", "target_word": "放松", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作太累了，他想出去放松一下。", "target_word": "放松", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她躺在沙发上，完全放松了。", "target_word": "放松", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到了朋友家，我一下子放松了。", "target_word": "放松", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他常玩游戏来放松自己。", "target_word": "放松", "complexity_tier": "T3", "furigana": "fàng sōng", "sentence_source": "generated"}, {"text": "喝杯热茶，放松一下心情。", "target_word": "放松", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们常常散步，放松一下。", "target_word": "放松", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "放松了", "label": "体标"}, {"form": "放松过", "label": "体标"}, {"form": "放松放松", "label": "重叠"}, {"form": "放鬆", "label": "繁体"}], "register": "中性", "sense_fingerprint": "休息、玩乐，让自己不紧张而舒服", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8cbebb4-22b2-4457-b7ac-21ebb866bd00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22870, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "放松", "is_correct": true, "explanation": "正确。“周末我想在家放松放松”中的“放松”指让身体或心里不紧张、变得舒服。"}, {"text": "加班", "is_correct": false, "explanation": "语义：周末想在家休息，“加班”与“周末”和“放松”的意思相冲突。"}, {"text": "出差", "is_correct": false, "explanation": "搭配：“在家”与“出差”不搭，出差要离开家。"}, {"text": "比赛", "is_correct": false, "explanation": "语义：比赛是紧张的竞技活动，与“在家放松”的意思相反。"}], "explanations": {"放松": "正确。“周末我想在家放松放松”中的“放松”指让身体或心里不紧张、变得舒服。", "加班": "语义：周末想在家休息，“加班”与“周末”和“放松”的意思相冲突。", "出差": "搭配：“在家”与“出差”不搭，出差要离开家。", "比赛": "语义：比赛是紧张的竞技活动，与“在家放松”的意思相反。"}, "sentence_index": 0, "correct_answer": "放松"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的记性很放松，常常忘事。", "explanation": "这里应该用〈减退〉。记性变差要用“减退”，“放松”指不紧张而舒服，不能用于记性。"}, {"text": "这项运动能放松身体里的能量。", "explanation": "这里应该用〈释放〉。能量要用“释放”，“放松”不能和能量搭配。"}, {"text": "这台电脑很放松，运行起来很慢。", "explanation": "这里应该用〈缓慢〉。机器运行的快慢要用“缓慢”，“放松”不能用于形容机器。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742cd520-0a5e-4792-82d4-d2db45d8b7fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22870, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "放松", "is_correct": true, "explanation": "正确。“我一下子放松了”指到了朋友家后心里不再紧张，变得舒服。"}, {"text": "迟到", "is_correct": false, "explanation": "语义：“迟到”指到得太晚，与“到了朋友家”后心情放松的描述不相符，句意不通。"}, {"text": "出门", "is_correct": false, "explanation": "语义：已经“到了朋友家”，就不能再说“出门”，二者矛盾。"}, {"text": "启程", "is_correct": false, "explanation": "搭配：“启程”指开始出发，常接“去”“前往”，不能用于已经到达之后。"}], "explanations": {"放松": "正确。“我一下子放松了”指到了朋友家后心里不再紧张，变得舒服。", "迟到": "语义：“迟到”指到得太晚，与“到了朋友家”后心情放松的描述不相符，句意不通。", "出门": "语义：已经“到了朋友家”，就不能再说“出门”，二者矛盾。", "启程": "搭配：“启程”指开始出发，常接“去”“前往”，不能用于已经到达之后。"}, "sentence_index": 6, "correct_answer": "放松"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把走路的速度放松了一些。", "explanation": "这里应该用〈放慢〉。速度要用“放慢”，“放松”表示身体或心里不紧张。"}, {"text": "他放松了这次难得的机会。", "explanation": "这里应该用〈放弃〉。机会要用“放弃”，“放松”不能用于机会。"}, {"text": "吃了药以后，他的头痛放松了。", "explanation": "这里应该用〈缓解〉。疼痛的减轻要用“缓解”，“放松”不用于形容疼痛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742cd520-0a5e-4792-82d4-d2db45d8b7fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22870, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他玩很放松。", "corrected_sentence": "他玩得很放松。", "error_description": "错误：“玩很放松”。动词后接描述状态的补语，中间要用“得”连接。正确为“玩得很放松”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742cd520-0a5e-4792-82d4-d2db45d8b7fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22870, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她放松的坐在沙发上。", "corrected_sentence": "她放松地坐在沙发上。", "error_description": "错误：“放松的坐”。修饰动词的状语要用“地”，“的”用于名词前。正确为“放松地坐”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742cd520-0a5e-4792-82d4-d2db45d8b7fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
