INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22872, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "心里清楚，不糊涂。", "primary_collocate": null, "pronunciation": "qīng xǐng", "ipa": "tɕʰiŋ˥ ɕiŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "大家都很激动，只有他一个人很清醒。", "target_word": "清醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遇到大事，我们要保持清醒的头脑。", "target_word": "清醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很清醒，知道这个人不能相信。", "target_word": "清醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "赢了比赛以后，教练仍然很清醒。", "target_word": "清醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对自己的问题看得很清醒。", "target_word": "清醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生气的时候，人很难清醒地想事情。", "target_word": "清醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友的话让我清醒了，我不该再等了。", "target_word": "清醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他头脑清醒，不会相信这些好话。", "target_word": "清醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买东西时要清醒，不要乱花钱。", "target_word": "清醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他清醒地知道，自己做错了。", "target_word": "清醒", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "清醒了", "label": "体标"}, {"form": "清醒地", "label": "状语形式"}], "register": "中性", "sense_fingerprint": "遇事心里明白、不糊涂、不冲动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8cbebb4-22b2-4457-b7ac-21ebb866bd00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22872, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "清醒", "is_correct": true, "explanation": "正确答案。清醒 qīng xǐng 指心里清楚、不糊涂。"}, {"text": "轻信", "is_correct": false, "explanation": "轻信 qīng xìn：第一个音节相同，第二个音节 xìn 与 xǐng 的韵尾不同（in 与 ing），声调也不同，意思是轻易相信。"}, {"text": "轻型", "is_correct": false, "explanation": "轻型 qīng xíng：第一个音节相同，第二个音节 xíng 与 xǐng 只有声调不同，意思是轻便的类型。"}, {"text": "惊醒", "is_correct": false, "explanation": "惊醒 jīng xǐng：声母 j 与 q 不同（不送气与送气），其余相同，意思是受惊后醒来。"}], "explanations": {"清醒": "正确答案。清醒 qīng xǐng 指心里清楚、不糊涂。", "轻信": "轻信 qīng xìn：第一个音节相同，第二个音节 xìn 与 xǐng 的韵尾不同（in 与 ing），声调也不同，意思是轻易相信。", "轻型": "轻型 qīng xíng：第一个音节相同，第二个音节 xíng 与 xǐng 只有声调不同，意思是轻便的类型。", "惊醒": "惊醒 jīng xǐng：声母 j 与 q 不同（不送气与送气），其余相同，意思是受惊后醒来。"}, "sentence_index": null, "correct_answer": "清醒"}, "level_3": {"options": [{"text": "清醒", "is_correct": true, "explanation": "正确。“只有他一个人很清醒”指在众人激动时他仍然冷静明白，“只有”引出对比。"}, {"text": "激动", "is_correct": false, "explanation": "语义：前句已说“大家都很激动”，“只有”要求他与众人不同，再说“很激动”前后矛盾。"}, {"text": "兴奋", "is_correct": false, "explanation": "语义：“兴奋”与“大家都很激动”的状态相同，与“只有他一个人”的对比不符。"}, {"text": "热闹", "is_correct": false, "explanation": "搭配：“热闹”多形容场面，不能说一个人“很热闹”。"}], "explanations": {"清醒": "正确。“只有他一个人很清醒”指在众人激动时他仍然冷静明白，“只有”引出对比。", "激动": "语义：前句已说“大家都很激动”，“只有”要求他与众人不同，再说“很激动”前后矛盾。", "兴奋": "语义：“兴奋”与“大家都很激动”的状态相同，与“只有他一个人”的对比不符。", "热闹": "搭配：“热闹”多形容场面，不能说一个人“很热闹”。"}, "sentence_index": 0, "correct_answer": "清醒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师把这道题讲得很清醒。", "explanation": "这里应该用〈清楚〉。清醒说人遇事心里明白，讲解是否清楚要用“清楚”。"}, {"text": "这盏台灯很清醒，屋里照得很亮。", "explanation": "这里应该用〈明亮〉。灯光的亮度要用“明亮”，“清醒”只用于形容人心里清楚、不糊涂，不能用于灯。"}, {"text": "这句话的意思很清醒。", "explanation": "这里应该用〈明白〉。“意思”是否明白要用“明白”，清醒不能形容话的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742cd520-0a5e-4792-82d4-d2db45d8b7fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22872, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "清醒", "is_correct": true, "explanation": "正确答案。清醒 qīng xǐng 指心里清楚、不糊涂。"}, {"text": "清新", "is_correct": false, "explanation": "清新 qīng xīn：第一个音节相同，第二个音节 xīn 与 xǐng 的韵尾不同（in 与 ing），声调也不同，意思是清爽新鲜。"}, {"text": "情形", "is_correct": false, "explanation": "情形 qíng xíng：两个音节的声调都与清醒不同（qíng 与 qīng，xíng 与 xǐng），意思是情况。"}, {"text": "庆幸", "is_correct": false, "explanation": "庆幸 qìng xìng：两个音节都只有声调不同，意思是为好事感到幸运。"}, {"text": "清洗", "is_correct": false, "explanation": "清洗 qīng xǐ：第二个音节少了韵尾 -ng（xǐ 与 xǐng），其余相同，意思是洗净。"}], "explanations": {"清醒": "正确答案。清醒 qīng xǐng 指心里清楚、不糊涂。", "清新": "清新 qīng xīn：第一个音节相同，第二个音节 xīn 与 xǐng 的韵尾不同（in 与 ing），声调也不同，意思是清爽新鲜。", "情形": "情形 qíng xíng：两个音节的声调都与清醒不同（qíng 与 qīng，xíng 与 xǐng），意思是情况。", "庆幸": "庆幸 qìng xìng：两个音节都只有声调不同，意思是为好事感到幸运。", "清洗": "清洗 qīng xǐ：第二个音节少了韵尾 -ng（xǐ 与 xǐng），其余相同，意思是洗净。"}, "sentence_index": null, "correct_answer": "清醒"}, "level_3": {"options": [{"text": "清醒", "is_correct": true, "explanation": "正确。“朋友的话让我清醒了”指听了朋友的话后头脑转过来、看清了情况，与后句“我不该再等了”的醒悟相符。"}, {"text": "麻木", "is_correct": false, "explanation": "语义：“麻木”指失去感觉，与“让我……了”的触动以及“我不该再等了”的醒悟相反。"}, {"text": "陶醉", "is_correct": false, "explanation": "搭配：“陶醉”通常沉浸于美景或音乐，不能用在“朋友的话让我……了”这一结构中。"}, {"text": "木讷", "is_correct": false, "explanation": "语义：“木讷”形容人反应迟钝、不善言辞，不能说明听了话后的改变和醒悟。"}], "explanations": {"清醒": "正确。“朋友的话让我清醒了”指听了朋友的话后头脑转过来、看清了情况，与后句“我不该再等了”的醒悟相符。", "麻木": "语义：“麻木”指失去感觉，与“让我……了”的触动以及“我不该再等了”的醒悟相反。", "陶醉": "搭配：“陶醉”通常沉浸于美景或音乐，不能用在“朋友的话让我……了”这一结构中。", "木讷": "语义：“木讷”形容人反应迟钝、不善言辞，不能说明听了话后的改变和醒悟。"}, "sentence_index": 6, "correct_answer": "清醒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的歌声很清醒，听得大家都入迷了。", "explanation": "这里应该用〈清亮〉。清亮形容声音明亮、透彻，清醒只用于人的头脑。"}, {"text": "她长得很清醒，皮肤白白的。", "explanation": "这里应该用〈清秀〉。清秀形容相貌清爽秀丽，清醒不能形容长相。"}, {"text": "晚风很清醒，吹在脸上很舒服。", "explanation": "这里应该用〈清凉〉。风的凉爽要用“清凉”，清醒不用于形容风。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742cd520-0a5e-4792-82d4-d2db45d8b7fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22872, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她清醒的看出了这件事的问题。", "corrected_sentence": "她清醒地看出了这件事的问题。", "error_description": "错误：“清醒的看出”。修饰动词的状语要用“地”，“的”用于名词前。正确为“清醒地看出”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742cd520-0a5e-4792-82d4-d2db45d8b7fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22872, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "听了朋友的话，他清醒的很快。", "corrected_sentence": "听了朋友的话，他清醒得很快。", "error_description": "错误：“清醒的很快”。表示程度或结果的补语，要用“得”连接，“的”用于名词前。正确为“清醒得很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742cd520-0a5e-4792-82d4-d2db45d8b7fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22874, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '757b3138-a62b-4602-b9a4-bfcdddc9fd8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22874, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '757b3138-a62b-4602-b9a4-bfcdddc9fd8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22874, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "看起来好像", "primary_collocate": null, "pronunciation": "kàn sì", "ipa": "kʰan⁵¹ sɹ̩⁵¹", "syllable_count": 2, "sentences": [{"text": "天空看似要下雨，路上的人都走得很快。", "target_word": "看似", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他看似很累，一回家就睡了。", "target_word": "看似", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那只狗看似很凶，其实很怕人。", "target_word": "看似", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那座山看似很近，走了两个小时才到。", "target_word": "看似", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她看似三十岁，其实已经五十岁了。", "target_word": "看似", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个箱子看似很轻，搬起来却很重。", "target_word": "看似", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这碗汤看似清淡，喝起来味道很浓。", "target_word": "看似", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他看似在听课，其实正在想别的事。", "target_word": "看似", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件衣服看似很旧，穿着却很舒服。", "target_word": "看似", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室里看似没有人，其实有一个学生在睡觉。", "target_word": "看似", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "外表给人的印象，看起来好像", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd209268f-53f6-4de8-8192-9154cf70cf8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22874, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "看似", "is_correct": true, "explanation": "“看似”表示从外表做出推断，符合天空阴沉、人们走得快的情境。"}, {"text": "打算", "is_correct": false, "explanation": "语义：“打算”要求有意志的主语，天空不能“打算”下雨。"}, {"text": "希望", "is_correct": false, "explanation": "语义：“希望”需要有意愿的主语，句子描述的是天空的样子。"}, {"text": "据说", "is_correct": false, "explanation": "语义：“据说”表示转述听来的传闻，句中说的是说话人对天空的观察，不能用它。"}], "explanations": {"看似": "“看似”表示从外表做出推断，符合天空阴沉、人们走得快的情境。", "打算": "语义：“打算”要求有意志的主语，天空不能“打算”下雨。", "希望": "语义：“希望”需要有意愿的主语，句子描述的是天空的样子。", "据说": "语义：“据说”表示转述听来的传闻，句中说的是说话人对天空的观察，不能用它。"}, "sentence_index": 0, "correct_answer": "看似"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌看似很好听，我听了一遍就喜欢上了。", "explanation": "这里应该用〈听起来〉。看似表示依据外在迹象的推断，而说话人已亲自听过，应直接用〈听起来〉，不能用“看似”。"}, {"text": "老师看似说明天放假，同学们都欢呼起来了。", "explanation": "这里应该用〈据说〉。看似只表示看到的外表印象，别人口头告知的消息不能用它来表示。"}, {"text": "他看似是我的哥哥，我们从小一起长大。", "explanation": "这里应该用〈确实〉。看似只表示外表给人的印象，兄弟关系是确定的事实，用它会显得含糊。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '757b3138-a62b-4602-b9a4-bfcdddc9fd8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22874, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "看似", "is_correct": true, "explanation": "“看似”表示外表印象，与“喝起来味道很浓”形成转折，符合句意。"}, {"text": "是", "is_correct": false, "explanation": "语义：“是”断定汤清淡，与“喝起来味道很浓”直接矛盾。"}, {"text": "觉得", "is_correct": false, "explanation": "配价：“觉得”需要有感知能力的主语，“汤”不能“觉得”清淡。"}, {"text": "变得", "is_correct": false, "explanation": "语义：“变得”表示变化过程，句子描述的是当下的口感，不符。"}], "explanations": {"看似": "“看似”表示外表印象，与“喝起来味道很浓”形成转折，符合句意。", "是": "语义：“是”断定汤清淡，与“喝起来味道很浓”直接矛盾。", "觉得": "配价：“觉得”需要有感知能力的主语，“汤”不能“觉得”清淡。", "变得": "语义：“变得”表示变化过程，句子描述的是当下的口感，不符。"}, "sentence_index": 6, "correct_answer": "看似"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他看似进了房间，我亲眼看见他走进去的。", "explanation": "这里应该用〈显然〉。看似只表示外表给人的印象，亲眼看见的事实不能用它来表示推测。"}, {"text": "我看似在哪儿见过他，却想不起来了。", "explanation": "这里应该用〈好像〉。看似描述从外部看到的样子，说话人对自己记忆的感觉不能用它。"}, {"text": "明天的会议看似在三点举行，通知上写得清清楚楚。", "explanation": "这里应该用〈确定〉。会议时间已写在通知上，是确定的安排，看似只表示外表印象，会让安排显得不确定。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '757b3138-a62b-4602-b9a4-bfcdddc9fd8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22874, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张照片看似了很旧，其实是新拍的。", "corrected_sentence": "这张照片看似很旧，其实是新拍的。", "error_description": "错误形式：“看似了很旧”。正确形式：“看似很旧”。原因：“看似”表示外表印象，后面不能加动态助词“了”，应直接接副词“很”和形容词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '757b3138-a62b-4602-b9a4-bfcdddc9fd8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22874, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条路看似的很近，其实要走一个小时。", "corrected_sentence": "这条路看似很近，其实要走一个小时。", "error_description": "错误形式：“看似的”。正确形式：“看似”。原因：“看似”后不接结构助词“的”，它直接接形容词作谓语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '757b3138-a62b-4602-b9a4-bfcdddc9fd8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
