INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22876, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "很久很久了。", "primary_collocate": null, "pronunciation": "cháng qī yǐ lái", "ipa": "ʈʂʰɑŋ˧˥ tɕʰi˥˥ i˨˩ laɪ˧˥", "syllable_count": 4, "sentences": [{"text": "长期以来，我一直住在这个小城市。", "target_word": "长期以来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长期以来，他都不太爱说话。", "target_word": "长期以来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长期以来，爷爷每天都去公园散步。", "target_word": "长期以来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长期以来，这家人过着平静的生活。", "target_word": "长期以来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们长期以来都是好朋友。", "target_word": "长期以来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长期以来，她一直在学习中文。", "target_word": "长期以来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长期以来，这座城市的空气都很好。", "target_word": "长期以来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长期以来，哥哥一直在这家医院工作。", "target_word": "长期以来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长期以来，弟弟都喜欢踢足球。", "target_word": "长期以来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长期以来，这个班的成绩一直不错。", "target_word": "长期以来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "很久以前开始、至今仍然如此的状态或习惯", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84185793-b8d0-46b1-818d-128e201d234b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22876, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示间或发生，与后面的“一直”相矛盾。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”表示马上、即时，与“一直住在这个小城市”的持续状态不符。"}, {"text": "长期以来", "is_correct": true, "explanation": "正确：“长期以来”表示从过去到现在一直如此，与“我一直住在这个小城市”相符。"}, {"text": "压根儿", "is_correct": false, "explanation": "语域：“压根儿”是口语，强调完全否定，与句中的肯定陈述“一直住”不相容，也不适合书面语境。"}], "explanations": {"偶尔": "语义：“偶尔”表示间或发生，与后面的“一直”相矛盾。", "立刻": "语义：“立刻”表示马上、即时，与“一直住在这个小城市”的持续状态不符。", "长期以来": "正确：“长期以来”表示从过去到现在一直如此，与“我一直住在这个小城市”相符。", "压根儿": "语域：“压根儿”是口语，强调完全否定，与句中的肯定陈述“一直住”不相容，也不适合书面语境。"}, "sentence_index": 0, "correct_answer": "长期以来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "长期以来，我们会经常见面。", "explanation": "这里应该用〈以后〉。长期以来指从过去持续到现在，不能用来说将来的情况。"}, {"text": "长期以来，他才十岁，还不懂事。", "explanation": "这里应该用〈当时〉。长期以来说持续的状态，说某一时刻的情况要用“当时”。"}, {"text": "这几天她长期以来一直很累。", "explanation": "这里应该用〈近来〉。长期以来表示很长时间，说这几天的状况要用“近来”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77847b03-2610-4297-853f-69b8a98d0392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22876, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "马上", "is_correct": false, "explanation": "语义：“马上”表示很快发生，与“长期以来”描述的持续状态相冲突。"}, {"text": "瞬间", "is_correct": false, "explanation": "语义：“瞬间”表示极短的时间，与“空气都很好”所描述的长期状况不符。"}, {"text": "霎时", "is_correct": false, "explanation": "语域：“霎时”是文言色彩较浓的词，表示一刹那，与句中的长期状况相矛盾。"}, {"text": "长期以来", "is_correct": true, "explanation": "正确：“长期以来”表示这座城市的空气长期都很好，与句意相符。"}], "explanations": {"马上": "语义：“马上”表示很快发生，与“长期以来”描述的持续状态相冲突。", "瞬间": "语义：“瞬间”表示极短的时间，与“空气都很好”所描述的长期状况不符。", "霎时": "语域：“霎时”是文言色彩较浓的词，表示一刹那，与句中的长期状况相矛盾。", "长期以来": "正确：“长期以来”表示这座城市的空气长期都很好，与句意相符。"}, "sentence_index": 6, "correct_answer": "长期以来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "长期以来，他马上就要出国了。", "explanation": "这里误用〈长期以来〉的持续义，句中说的是即将发生的事，与“即将、很快”之义相冲突。"}, {"text": "长期以来，我们暂时住在朋友家。", "explanation": "这里误用〈长期以来〉的持续义，句中说的是短期的安排，与“短期”之义相冲突。"}, {"text": "长期以来，城市一夜之间变了模样。", "explanation": "这里误用〈长期以来〉的持续义，句中说的是变化瞬间发生，与“瞬间”之义相冲突。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77847b03-2610-4297-853f-69b8a98d0392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22876, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个城市长期以来了都很安静。", "corrected_sentence": "这个城市长期以来都很安静。", "error_description": "错误：“了”被加在“长期以来”之后。“长期以来”是时间状语，不能带动态助词“了”，应删去。正确：应为“这个城市长期以来都很安静”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77847b03-2610-4297-853f-69b8a98d0392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22876, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家工厂长期以来都在生产过纸张。", "corrected_sentence": "这家工厂长期以来都在生产纸张。", "error_description": "错误：“过”被加在“生产”之后。“在”表示正在进行，与经历体“过”不相容。正确：应删去“过”，即“这家工厂长期以来都在生产纸张”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77847b03-2610-4297-853f-69b8a98d0392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
