INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22878, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "科学界就是做科学研究的人。", "primary_collocate": null, "pronunciation": "kē xué jiè", "ipa": "kʰɤ˥˥ ɕɥe˧˥ tɕje˥˩", "syllable_count": 3, "sentences": [{"text": "科学界的人每天都在做实验。", "target_word": "科学界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学界很多人都爱读书。", "target_word": "科学界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学界欢迎年轻人来工作。", "target_word": "科学界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人在科学界工作了四十年。", "target_word": "科学界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学界的人常常一起讨论问题。", "target_word": "科学界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位记者经常采访科学界的人。", "target_word": "科学界", "complexity_tier": "T3", "furigana": "zhè wèi jìzhě jīngcháng cǎifǎng kē xué jiè de rén", "sentence_source": "generated"}, {"text": "科学界授予他一个大奖。", "target_word": "科学界", "complexity_tier": "T3", "furigana": "kē xué jiè shòuyǔ tā yí gè dàjiǎng", "sentence_source": "generated"}, {"text": "他的研究让科学界的人很高兴。", "target_word": "科学界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学界的人要认真，不能说假话。", "target_word": "科学界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学界选出了今年最好的研究。", "target_word": "科学界", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "做科学研究的人所组成的群体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84185793-b8d0-46b1-818d-128e201d234b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22878, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "科学界", "is_correct": true, "explanation": "正确：指做科学研究的人群，与“做实验”的句意相符。"}, {"text": "氧气", "is_correct": false, "explanation": "语义：氧气是气体，不是人，不能“做实验”。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”是家具，不是人或群体，不能作“……的人”的定语，也无法与“做实验”搭配。"}, {"text": "咖啡", "is_correct": false, "explanation": "搭配：“咖啡”是饮品，不与“……的人每天都在做实验”搭配。"}], "explanations": {"科学界": "正确：指做科学研究的人群，与“做实验”的句意相符。", "氧气": "语义：氧气是气体，不是人，不能“做实验”。", "桌子": "语义：“桌子”是家具，不是人或群体，不能作“……的人”的定语，也无法与“做实验”搭配。", "咖啡": "搭配：“咖啡”是饮品，不与“……的人每天都在做实验”搭配。"}, "sentence_index": 0, "correct_answer": "科学界"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位科学界在医院工作了四十年。", "explanation": "这里应该用〈医生〉。“科学界”指做科学研究的人群体，不能用“这位”指一个人。"}, {"text": "这位老人在科学界散步了四十年。", "explanation": "这里应该用〈公园〉。“科学界”指做科学研究的人，不是可以散步的场所，应说在公园之类的地点散步。"}, {"text": "他在杂志上发表了科学界。", "explanation": "这里应该用〈文章〉。“科学界”指做科学研究的人，不能当作可以发表的作品，发表的是论文或文章。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77847b03-2610-4297-853f-69b8a98d0392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22878, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "科学界", "is_correct": true, "explanation": "正确：科学界作为群体可以授予奖项，与句意相符。"}, {"text": "小狗", "is_correct": false, "explanation": "语义：小狗不能授予奖项，授奖的主体须是机构或群体。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是场所，不能作为授奖的主体。"}, {"text": "老铁", "is_correct": false, "explanation": "语域：“老铁”是网络口语，与“授予”的正式语域不协调。"}], "explanations": {"科学界": "正确：科学界作为群体可以授予奖项，与句意相符。", "小狗": "语义：小狗不能授予奖项，授奖的主体须是机构或群体。", "厨房": "语义：厨房是场所，不能作为授奖的主体。", "老铁": "语域：“老铁”是网络口语，与“授予”的正式语域不协调。"}, "sentence_index": 6, "correct_answer": "科学界"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一座科学界选出了今年最好的研究。", "explanation": "这里不能用量词“座”。“座”用于建筑、山峰等，“科学界”是人群或领域。"}, {"text": "他把科学界放进了冰箱。", "explanation": "这里应该用〈牛奶〉。“科学界”指做科学研究的人群体，不是可以放进冰箱的东西。"}, {"text": "这块科学界选出了今年最好的研究。", "explanation": "这里应该用〈个〉。“块”用于片状物等，“科学界”指做科学研究的人群体，不能用“块”计数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77847b03-2610-4297-853f-69b8a98d0392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22878, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他科学界很有名。", "corrected_sentence": "他在科学界很有名。", "error_description": "错误：漏掉了介词“在”。“科学界”是范围，需要“在”引出，应说“他在科学界很有名”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77847b03-2610-4297-853f-69b8a98d0392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22878, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "科学界们都很忙。", "corrected_sentence": "科学界的人都很忙。", "error_description": "错误在于“们”。“科学界”本身指群体，后面不能再加“们”，应说“科学界的人都很忙”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77847b03-2610-4297-853f-69b8a98d0392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
