INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22886, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "吃下去或喝进去。", "primary_collocate": null, "pronunciation": "shè rù", "ipa": "ʂɤ˥˩ ɻu˥˩", "syllable_count": 2, "sentences": [{"text": "他今天只摄入了一杯牛奶。", "target_word": "摄入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人刚做完手术，不能摄入油腻的东西。", "target_word": "摄入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早上他摄入了一些粥。", "target_word": "摄入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宝宝每天要摄入足够的奶。", "target_word": "摄入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动员比赛前不能摄入太多食物。", "target_word": "摄入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她减肥时每天摄入的食物很少。", "target_word": "摄入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气热，要多摄入一些水。", "target_word": "摄入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷牙不好，只能摄入软的食物。", "target_word": "摄入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "患者术后三天只能摄入流质食物。", "target_word": "摄入", "complexity_tier": "T3", "furigana": "huànzhě shù hòu sān tiān zhǐ néng shèrù liúzhí shíwù", "sentence_source": "generated"}, {"text": "晚上不要摄入太多食物，会睡不好。", "target_word": "摄入", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "摄入了", "label": "完成体"}, {"form": "摄入过", "label": "经历体"}, {"form": "摄入量", "label": "复合词"}], "register": "书面语", "sense_fingerprint": "把食物或饮品吃下去、喝进去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84185793-b8d0-46b1-818d-128e201d234b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22886, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "摄入", "is_correct": true, "explanation": "正确：“摄入”表示把牛奶喝进体内，与“只……了一杯牛奶”相符。"}, {"text": "投资", "is_correct": false, "explanation": "语义：“投资”指投入资金，与喝牛奶无关。"}, {"text": "批准", "is_correct": false, "explanation": "语义：“批准”指同意或许可，不能指饮用一杯牛奶。"}, {"text": "讨论", "is_correct": false, "explanation": "搭配：“讨论”的宾语多为问题、话题，不说“讨论了一杯牛奶”。"}], "explanations": {"摄入": "正确：“摄入”表示把牛奶喝进体内，与“只……了一杯牛奶”相符。", "投资": "语义：“投资”指投入资金，与喝牛奶无关。", "批准": "语义：“批准”指同意或许可，不能指饮用一杯牛奶。", "讨论": "搭配：“讨论”的宾语多为问题、话题，不说“讨论了一杯牛奶”。"}, "sentence_index": 0, "correct_answer": "摄入"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他深深地摄入了一口新鲜空气。", "explanation": "这里应该用〈吸入〉。“摄入”指吃喝或服药进入体内，吸气要说“吸入”。"}, {"text": "他摄入了一场比赛。", "explanation": "这里应该用〈参加〉。“摄入”只用于物质的吸收，不能用于比赛。"}, {"text": "我们摄入了整个博物馆。", "explanation": "这里应该用〈参观〉。“摄入”不能用于地点，参观博物馆要说“参观”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77847b03-2610-4297-853f-69b8a98d0392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22886, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "摄入", "is_correct": true, "explanation": "正确：“摄入”表示喝进水，与“天气热，要多……一些水”的语境相符。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”指书写文字，水不能被书写，与补水无关。"}, {"text": "拍", "is_correct": false, "explanation": "语义：“拍”指拍打，不能用来表示补充水分。"}, {"text": "排放", "is_correct": false, "explanation": "搭配：“排放”多接废水、废气，与“多……一些水”的补水语境不搭。"}], "explanations": {"摄入": "正确：“摄入”表示喝进水，与“天气热，要多……一些水”的语境相符。", "写": "语义：“写”指书写文字，水不能被书写，与补水无关。", "拍": "语义：“拍”指拍打，不能用来表示补充水分。", "排放": "搭配：“排放”多接废水、废气，与“多……一些水”的补水语境不搭。"}, "sentence_index": 6, "correct_answer": "摄入"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他接受了老师的建议，却摄入了它。", "explanation": "这里应该用〈听取〉。“摄入”只用于吃喝、服药等物质，不能用于建议，“却摄入了它”说不通。"}, {"text": "我们摄入了这幅画。", "explanation": "这里应该用〈欣赏〉。“摄入”只表示把物质吃进或喝进去，不能用于画。"}, {"text": "她摄入了很大的压力。", "explanation": "这里应该用〈承受〉。“摄入”不能用于压力，承受压力要说“承受”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77847b03-2610-4297-853f-69b8a98d0392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22886, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他今天只被摄入了一些蔬菜。", "corrected_sentence": "他今天只摄入了一些蔬菜。", "error_description": "错误在于“被”。“摄入”的施事是“他”，“他”不能充当被动句的受事，应去掉“被”。正确：“他今天只摄入了一些蔬菜。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77847b03-2610-4297-853f-69b8a98d0392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22886, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每天只吸入少量的盐。", "corrected_sentence": "他每天只摄入少量的盐。", "error_description": "错误在于动词“吸入”。“吸入”指经呼吸进入体内，盐不能被吸入，应改为“摄入”。正确：“他每天只摄入少量的盐。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77847b03-2610-4297-853f-69b8a98d0392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
