INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22898, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "鼻腔是鼻子里面的小通道，空气从这里通过。", "primary_collocate": null, "pronunciation": "bí qiāng", "ipa": "pi˧˥ tɕʰjɑŋ˥", "syllable_count": 2, "sentences": [{"text": "空气从鼻腔进入身体。", "target_word": "鼻腔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的鼻腔有点干。", "target_word": "鼻腔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鼻腔是鼻子里的通道。", "target_word": "鼻腔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "感冒了，鼻腔被堵住了。", "target_word": "鼻腔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生看了看孩子的鼻腔。", "target_word": "鼻腔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冷风吹进鼻腔，很舒服。", "target_word": "鼻腔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鼻腔里有很多小毛。", "target_word": "鼻腔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的鼻腔里有一点血。", "target_word": "鼻腔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花香飘进鼻腔，我觉得很放松。", "target_word": "鼻腔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吸气时，空气先经过鼻腔。", "target_word": "鼻腔", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "鼻子里面供空气通过的通道", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef4b2287-278a-4737-b987-92485fc5a6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22898, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "鼻腔", "is_correct": true, "explanation": "正确。空气从鼻腔进入身体，鼻腔是呼吸道的通道。"}, {"text": "指甲", "is_correct": false, "explanation": "语义：空气不从指甲进入身体，指甲不是呼吸道。"}, {"text": "脚趾", "is_correct": false, "explanation": "语义：空气不从脚趾进入身体。"}, {"text": "血管", "is_correct": false, "explanation": "搭配：“进入身体”指经呼吸道吸入，“血管”一般与“血液”搭配。"}], "explanations": {"鼻腔": "正确。空气从鼻腔进入身体，鼻腔是呼吸道的通道。", "指甲": "语义：空气不从指甲进入身体，指甲不是呼吸道。", "脚趾": "语义：空气不从脚趾进入身体。", "血管": "搭配：“进入身体”指经呼吸道吸入，“血管”一般与“血液”搭配。"}, "sentence_index": 0, "correct_answer": "鼻腔"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "感冒了，他的一颗鼻腔被堵住了。", "explanation": "这里不能用〈颗〉。颗用于圆粒状的东西，鼻腔应用“个”或“侧”。"}, {"text": "她的一张鼻腔很干净。", "explanation": "这里不能用〈张〉。张用于平面的东西，如桌子、纸，鼻腔应用“个”或“侧”。"}, {"text": "这座鼻腔很深。", "explanation": "这里不能用〈座〉。座用于山、楼等大型固定的东西，鼻腔应用“个”或“侧”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '443f7d88-91de-4998-9682-7cbd7ec12a8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22898, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "鼻腔", "is_correct": true, "explanation": "正确。鼻腔是鼻子里的空腔，里面才会有小毛。"}, {"text": "手掌", "is_correct": false, "explanation": "语义：手掌表面没有毛发，里面不会有小毛。"}, {"text": "膝盖", "is_correct": false, "explanation": "语义：膝盖里不会长小毛。"}, {"text": "胃", "is_correct": false, "explanation": "语义：胃是内脏，里面不长毛发，不会有小毛。"}], "explanations": {"鼻腔": "正确。鼻腔是鼻子里的空腔，里面才会有小毛。", "手掌": "语义：手掌表面没有毛发，里面不会有小毛。", "膝盖": "语义：膝盖里不会长小毛。", "胃": "语义：胃是内脏，里面不长毛发，不会有小毛。"}, "sentence_index": 6, "correct_answer": "鼻腔"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的鼻腔很挺，大家都很羡慕。", "explanation": "这里应该用〈鼻梁〉。鼻梁是外露的部位，形容“挺”要用鼻梁，鼻腔在内部。"}, {"text": "她的鼻腔上沾了一点面粉。", "explanation": "这里应该用〈鼻尖〉。面粉沾在外露的鼻尖上，鼻腔在内部，看不见也摸不到。"}, {"text": "她捏住了自己的鼻腔。", "explanation": "这里应该用〈鼻子〉。捏的是外露的鼻子，鼻腔在内部，无法捏住。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '443f7d88-91de-4998-9682-7cbd7ec12a8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22898, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "吸气时，空气把鼻腔进入喉咙。", "corrected_sentence": "吸气时，空气从鼻腔进入喉咙。", "error_description": "错误：“把鼻腔进入喉咙”，“把”字句不能这样用；表示经由鼻腔这一通道，要用“从”。正确：“从鼻腔进入喉咙”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '443f7d88-91de-4998-9682-7cbd7ec12a8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22898, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "天气一冷，我的鼻腔就堵很厉害。", "corrected_sentence": "天气一冷，我的鼻腔就堵得很厉害。", "error_description": "错误：“堵很厉害”，漏掉了“得”。正确：“堵得很厉害”。“动词+得+程度补语”结构中，“得”不能省。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '443f7d88-91de-4998-9682-7cbd7ec12a8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22900, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "加速", "is_correct": true, "explanation": "反义：“减缓”指速度降低，“加速”指速度加快，二者相对。"}, {"text": "保持", "is_correct": false, "explanation": "无反义关系：“保持”指维持原状，不表示速度的变化。"}, {"text": "停留", "is_correct": false, "explanation": "无反义关系：“停留”指停在某处，与“减缓”不构成反义。"}, {"text": "稳定", "is_correct": false, "explanation": "无反义关系：“稳定”指不变动，不是“减缓”的反义词。"}], "correct_answer": "加速", "explanations": {"加速": "反义：“减缓”指速度降低，“加速”指速度加快，二者相对。", "保持": "无反义关系：“保持”指维持原状，不表示速度的变化。", "停留": "无反义关系：“停留”指停在某处，与“减缓”不构成反义。", "稳定": "无反义关系：“稳定”指不变动，不是“减缓”的反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21c85038-5747-4c20-ac84-49a80cc56e32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22900, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "加快", "is_correct": true, "explanation": "反义：“减缓”指速度降低，“加快”指速度提高，正好相反。"}, {"text": "扩大", "is_correct": false, "explanation": "无反义关系：“扩大”指范围或规模变大，与速度的降低无对立关系。"}, {"text": "维持", "is_correct": false, "explanation": "无反义关系：“维持”指使某种状态不变，不与“减缓”构成反义。"}, {"text": "增长", "is_correct": false, "explanation": "无反义关系：“增长”指数量或规模变大，不与速度的降低构成反义。"}], "correct_answer": "加快", "explanations": {"加快": "反义：“减缓”指速度降低，“加快”指速度提高，正好相反。", "扩大": "无反义关系：“扩大”指范围或规模变大，与速度的降低无对立关系。", "维持": "无反义关系：“维持”指使某种状态不变，不与“减缓”构成反义。", "增长": "无反义关系：“增长”指数量或规模变大，不与速度的降低构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21c85038-5747-4c20-ac84-49a80cc56e32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22900, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让速度或程度变小、变慢。", "primary_collocate": null, "pronunciation": "jiǎn huǎn", "ipa": "tɕjɛn˨˩˦ xwan˨˩˦", "syllable_count": 2, "sentences": [{"text": "司机踩了刹车，减缓了车速。", "target_word": "减缓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药能减缓他的疼痛。", "target_word": "减缓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上有减速带，能减缓车速。", "target_word": "减缓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府想减缓房价上涨的速度。", "target_word": "减缓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多种树可以减缓沙漠扩大的速度。", "target_word": "减缓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生用药减缓了病情的发展。", "target_word": "减缓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看到前面有人，就减缓了脚步。", "target_word": "减缓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的护肤品能减缓皮肤衰老。", "target_word": "减缓", "complexity_tier": "T3", "furigana": "hǎo de hù fū pǐn néng jiǎn huǎn pí fū shuāi lǎo", "sentence_source": "generated"}, {"text": "老师放慢说话，减缓了课堂的节奏。", "target_word": "减缓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厚厚的雪减缓了救援车的速度。", "target_word": "减缓", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "减缓了", "label": "体标"}, {"form": "減緩", "label": "繁体"}], "register": "书面", "sense_fingerprint": "使某事物的速度或程度变小变慢（及物）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25dc1047-0180-45c4-a535-02dddfb4af73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22900, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "减缓", "is_correct": true, "explanation": "“踩了刹车”与“减缓了车速”因果一致，符合句意。"}, {"text": "加快", "is_correct": false, "explanation": "语义：踩刹车是为了降低车速，说“加快”与刹车的目的相反。"}, {"text": "增加", "is_correct": false, "explanation": "语义：踩刹车是为了降低车速，“增加”车速与句意相反。"}, {"text": "提高", "is_correct": false, "explanation": "语义：“提高车速”与“踩了刹车”矛盾，句意应是车速下降。"}], "explanations": {"减缓": "“踩了刹车”与“减缓了车速”因果一致，符合句意。", "加快": "语义：踩刹车是为了降低车速，说“加快”与刹车的目的相反。", "增加": "语义：踩刹车是为了降低车速，“增加”车速与句意相反。", "提高": "语义：“提高车速”与“踩了刹车”矛盾，句意应是车速下降。"}, "sentence_index": 0, "correct_answer": "减缓"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校想减缓学生的人数。", "explanation": "这里应该用〈减少〉。减缓用于速度或程度，人数减少要用“减少”。"}, {"text": "他想减缓这篇文章的字数，删掉了三段。", "explanation": "这里应该用〈删减〉。减缓强调速度或程度，删减文字要用“删减”。"}, {"text": "他想减缓这次旅行的出发日期。", "explanation": "这里应该用〈推迟〉。减缓不用于日期的延后，推迟出发要用“推迟”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21c85038-5747-4c20-ac84-49a80cc56e32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22900, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "减缓", "is_correct": true, "explanation": "“看到前面有人”之后放慢脚步，符合句意。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”表示不再坚持，与放慢脚步的意思不同。"}, {"text": "减弱", "is_correct": false, "explanation": "语义：“减弱”指力量、强度变小，不指速度变慢。"}, {"text": "抬高", "is_correct": false, "explanation": "搭配：“抬高”多用于物体的高度，不说“抬高脚步”。"}], "explanations": {"减缓": "“看到前面有人”之后放慢脚步，符合句意。", "放弃": "语义：“放弃”表示不再坚持，与放慢脚步的意思不同。", "减弱": "语义：“减弱”指力量、强度变小，不指速度变慢。", "抬高": "搭配：“抬高”多用于物体的高度，不说“抬高脚步”。"}, "sentence_index": 6, "correct_answer": "减缓"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的钱减缓了一半。", "explanation": "这里应该用〈花掉〉。减缓用于速度或程度，钱的减少要用“花掉”。"}, {"text": "他把体重减缓到了五十公斤。", "explanation": "这里应该用〈减轻〉。体重减少要用“减轻”，减缓不用于体重。"}, {"text": "他把房间减缓成了一间小屋。", "explanation": "这里应该用〈缩小〉。减缓不用于空间大小的改变，房间变小要用“缩小”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21c85038-5747-4c20-ac84-49a80cc56e32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22900, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "路上有积雪，司机慢慢减缓得车速。", "corrected_sentence": "路上有积雪，司机慢慢减缓了车速。", "error_description": "错误形式：减缓得车速；正确形式：减缓了车速。动词后带宾语表示动作完成，应用“了”，“得”不能接在动词后引出宾语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21c85038-5747-4c20-ac84-49a80cc56e32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22900, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "前面有施工，司机把车速减缓出来了。", "corrected_sentence": "前面有施工，司机把车速减缓了。", "error_description": "补语错误：“减缓”后接“出来”不通，直接说“把车速减缓了”即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21c85038-5747-4c20-ac84-49a80cc56e32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
