INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22902, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "嘴巴里面的地方，有牙齿和舌头。", "primary_collocate": null, "pronunciation": "kǒu qiāng", "ipa": "kʰoʊ̯˨˩ t͡ɕʰjɑŋ˥", "syllable_count": 2, "sentences": [{"text": "口腔里有牙齿和舌头。", "target_word": "口腔", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我的口腔很干，想喝水。", "target_word": "口腔", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他喝了热茶，口腔有点儿烫。", "target_word": "口腔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请张开嘴，我看看你的口腔。", "target_word": "口腔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子的口腔里有一颗小牙。", "target_word": "口腔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吃了辣菜，我的口腔很热。", "target_word": "口腔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "口腔里的舌头可以帮我们说话。", "target_word": "口腔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种药要含在口腔里慢慢化开。", "target_word": "口腔", "complexity_tier": "T3", "furigana": "kǒuqiāng", "sentence_source": "generated"}, {"text": "刷牙以后，我的口腔很清爽。", "target_word": "口腔", "complexity_tier": "T3", "furigana": "kǒuqiāng", "sentence_source": "generated"}, {"text": "医生说我的口腔很健康。", "target_word": "口腔", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "口腔溃疡", "label": "复合"}, {"form": "口腔科", "label": "复合"}], "register": "中性", "sense_fingerprint": "口腔：嘴巴里面有牙齿和舌头的地方（日常浅显义）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bf78d8d-1b55-43c3-ab25-4cc6f914996e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22902, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "口腔", "is_correct": true, "explanation": "正确。口腔指嘴里有牙齿和舌头的地方，与句意一致。"}, {"text": "胃", "is_correct": false, "explanation": "语义：胃不在嘴里，不长牙齿和舌头，与句意不符。"}, {"text": "耳朵", "is_correct": false, "explanation": "搭配：耳朵里没有牙齿，“耳朵里有牙齿和舌头”说不通。"}, {"text": "鼻子", "is_correct": false, "explanation": "语义：鼻子里不长牙齿，舌头也不在鼻子里，与句意冲突。"}], "explanations": {"口腔": "正确。口腔指嘴里有牙齿和舌头的地方，与句意一致。", "胃": "语义：胃不在嘴里，不长牙齿和舌头，与句意不符。", "耳朵": "搭配：耳朵里没有牙齿，“耳朵里有牙齿和舌头”说不通。", "鼻子": "语义：鼻子里不长牙齿，舌头也不在鼻子里，与句意冲突。"}, "sentence_index": 0, "correct_answer": "口腔"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他伸出口腔，让医生检查。", "explanation": "这里应该用〈舌头〉。伸出的是舌头，口腔是空腔，不能伸出。"}, {"text": "他的口腔掉了，很疼。", "explanation": "这里应该用〈牙齿〉。牙齿会脱落，口腔是整个空腔，不会掉。"}, {"text": "他把钥匙放进口腔里。", "explanation": "这里应该用〈口袋〉。钥匙要放进口袋，口腔是嘴里的空腔，放不下钥匙。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff11a5a9-5807-4f92-84e1-243e87b3e6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22902, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "口腔", "is_correct": true, "explanation": "正确。舌头位于口腔内，“口腔里的舌头”指向的正是口腔。"}, {"text": "手", "is_correct": false, "explanation": "语义：舌头不在手里，“手里的舌头”与句意不符。"}, {"text": "脚", "is_correct": false, "explanation": "语义：舌头不长在脚上，“脚里的舌头”说不通。"}, {"text": "眼睛", "is_correct": false, "explanation": "语义：舌头不在眼睛里，也不能帮我们说话，与句意冲突。"}], "explanations": {"口腔": "正确。舌头位于口腔内，“口腔里的舌头”指向的正是口腔。", "手": "语义：舌头不在手里，“手里的舌头”与句意不符。", "脚": "语义：舌头不长在脚上，“脚里的舌头”说不通。", "眼睛": "语义：舌头不在眼睛里，也不能帮我们说话，与句意冲突。"}, "sentence_index": 6, "correct_answer": "口腔"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他抿紧口腔，不说话。", "explanation": "这里应该用〈嘴唇〉。“抿”是嘴唇的动作，口腔在里面，看不见也抿不了。"}, {"text": "吃完饭，我的口腔很饱。", "explanation": "这里应该用〈胃〉。“饱”指胃吃足的感觉，口腔不会饱。"}, {"text": "他戴上口腔，出门了。", "explanation": "这里应该用〈耳机〉。“戴”用于可以戴在身上的物品，口腔是身体器官，不能戴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff11a5a9-5807-4f92-84e1-243e87b3e6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22902, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "吃完饭后，我的口腔有点的干。", "corrected_sentence": "吃完饭后，我的口腔有点干。", "error_description": "错误：“有点的干”。正确：应说“有点干”，“有点”后面直接接形容词，中间不加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff11a5a9-5807-4f92-84e1-243e87b3e6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22902, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "漱口以后，我的一颗口腔很清爽。", "corrected_sentence": "漱口以后，我的口腔很清爽。", "error_description": "错误：“我的一颗口腔”。正确：应说“我的口腔”，去掉量词“一颗”。“颗”用于圆小的东西，口腔不用“颗”计量。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff11a5a9-5807-4f92-84e1-243e87b3e6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
