INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22908, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "东西变凉了。", "primary_collocate": null, "pronunciation": "lěng què", "ipa": "ləŋ˨˩ t͡ɕʰɥɛ˥˩", "syllable_count": 2, "sentences": [{"text": "汤冷却了，不太好喝。", "target_word": "冷却", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "饭菜冷却以后，味道不好。", "target_word": "冷却", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "热水冷却得很慢。", "target_word": "冷却", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "咖啡放了很久，已经冷却了。", "target_word": "冷却", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "铁块从炉子里拿出来，慢慢冷却。", "target_word": "冷却", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "等牛奶冷却以后，再给宝宝喝。", "target_word": "冷却", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天黑以后，沙地很快就冷却下来。", "target_word": "冷却", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火山停止喷发后，岩浆慢慢冷却了。", "target_word": "冷却", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "热茶放在桌上，一会儿就冷却了。", "target_word": "冷却", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冷却着的铁块不能马上摸。", "target_word": "冷却", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "冷却了", "label": "体标"}, {"form": "冷却着", "label": "体标"}, {"form": "冷却下来", "label": "复合"}, {"form": "冷卻", "label": "繁体"}], "register": "中性", "sense_fingerprint": "冷却：（不及物）热的东西自己变凉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bf78d8d-1b55-43c3-ab25-4cc6f914996e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22908, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "冷却", "is_correct": true, "explanation": "正确。汤变凉了，与“不太好喝”的语境一致。"}, {"text": "研究", "is_correct": false, "explanation": "语义：汤不能被研究，“汤研究了，不太好喝”与句意冲突。"}, {"text": "搬运", "is_correct": false, "explanation": "语义：搬运指移动物体，与汤的温度变化无关，句意不通。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：汤不能被翻译，“汤翻译了”说不通。"}], "explanations": {"冷却": "正确。汤变凉了，与“不太好喝”的语境一致。", "研究": "语义：汤不能被研究，“汤研究了，不太好喝”与句意冲突。", "搬运": "语义：搬运指移动物体，与汤的温度变化无关，句意不通。", "翻译": "语义：汤不能被翻译，“汤翻译了”说不通。"}, "sentence_index": 0, "correct_answer": "冷却"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的名字慢慢冷却了。", "explanation": "这里应该用〈淡出〉。“冷却”指温度下降；名字逐渐被人遗忘应说“淡出”。"}, {"text": "这首歌的音量慢慢冷却了。", "explanation": "这里应该用〈减小〉。“冷却”指温度下降；音量的降低应说“减小”。"}, {"text": "这个学生的成绩慢慢冷却了。", "explanation": "这里应该用〈下降〉。“冷却”指温度下降，成绩的下降要用“下降”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff11a5a9-5807-4f92-84e1-243e87b3e6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22908, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冷却", "is_correct": true, "explanation": "正确。天黑后沙地温度下降，与“天黑以后”的语境一致。"}, {"text": "发光", "is_correct": false, "explanation": "语义：沙地在天黑后不会发光，与“冷”的语境冲突。"}, {"text": "生长", "is_correct": false, "explanation": "语义：沙地不会生长，与句意不符。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：沙地不能游泳，“沙地游泳下来”说不通。"}], "explanations": {"冷却": "正确。天黑后沙地温度下降，与“天黑以后”的语境一致。", "发光": "语义：沙地在天黑后不会发光，与“冷”的语境冲突。", "生长": "语义：沙地不会生长，与句意不符。", "游泳": "语义：沙地不能游泳，“沙地游泳下来”说不通。"}, "sentence_index": 6, "correct_answer": "冷却"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个月的工资冷却了。", "explanation": "这里应该用〈减少〉。“冷却”指温度下降；工资的减少应说“减少”，不能说“冷却”。"}, {"text": "他的字迹慢慢冷却了。", "explanation": "这里应该用〈模糊〉。“冷却”指温度下降；字迹变淡应说“模糊”。"}, {"text": "疼痛冷却了。", "explanation": "这里应该用〈消退〉。“冷却”指温度下降，疼痛减轻要用“消退”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff11a5a9-5807-4f92-84e1-243e87b3e6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22908, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "汤已经冷却了着。", "corrected_sentence": "汤已经冷却了。", "error_description": "错误：“冷却了着”。正确：应说“冷却了”，“了”和“着”不能同时用在同一个动词后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff11a5a9-5807-4f92-84e1-243e87b3e6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22908, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "粥煮好后放在桌上，慢慢冷却下了。", "corrected_sentence": "粥煮好后放在桌上，慢慢冷却下来了。", "error_description": "错误：“冷却下了”。正确：应说“冷却下来了”。“冷却下来”是固定说法，表示由热变凉、由高降到低；“冷却下”不是通用说法，应使用“下来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff11a5a9-5807-4f92-84e1-243e87b3e6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
