INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22910, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "有效就是做一件事，得到了想要的结果。", "primary_collocate": null, "pronunciation": "yǒu xiào", "ipa": "jou˨˩˦ ɕjau˥˩", "syllable_count": 2, "sentences": [{"text": "这种药对感冒很有效。", "target_word": "有效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的办法很有效，我们进步得很快。", "target_word": "有效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个复习方法很有效，他的成绩提高了不少。", "target_word": "有效", "complexity_tier": "T3", "furigana": "zhè ge fù xí fāng fǎ hěn yǒu xiào，tā de chéngjì tígāo le bù shǎo。", "sentence_source": "generated"}, {"text": "他试了很多方法，只有这个有效。", "target_word": "有效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多运动是有效的减肥方法。", "target_word": "有效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次会议开得很有效，大家都满意。", "target_word": "有效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种办法对你的失眠真的有效吗？", "target_word": "有效", "complexity_tier": "T3", "furigana": "zhè zhǒng bànfǎ duì nǐ de shīmián zhēnde yǒu xiào ma？", "sentence_source": "generated"}, {"text": "听力练习对学语言特别有效。", "target_word": "有效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你觉得哪种方法最有效？", "target_word": "有效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "药很有效，他吃了一次就不疼了。", "target_word": "有效", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "有效期", "label": "复合词"}], "register": "中性", "sense_fingerprint": "方法、药物等能得到想要的结果，有作用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d813a3-5c7c-4c35-a022-bcb120b67276') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22910, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有效", "is_correct": true, "explanation": "「有效」表示这种药对感冒有作用，符合句意。"}, {"text": "懒", "is_correct": false, "explanation": "语义：「懒」形容人不勤快，不能用来说药对病的作用。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：「热闹」形容场面喧哗，与药的作用无关。"}, {"text": "高", "is_correct": false, "explanation": "搭配：「高」说的是高度，不能用来说药的效果。"}], "explanations": {"有效": "「有效」表示这种药对感冒有作用，符合句意。", "懒": "语义：「懒」形容人不勤快，不能用来说药对病的作用。", "热闹": "语义：「热闹」形容场面喧哗，与药的作用无关。", "高": "搭配：「高」说的是高度，不能用来说药的效果。"}, "sentence_index": 0, "correct_answer": "有效"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很有效，工作又快又好。", "explanation": "这里应该用〈能干〉。「有效」用于方法、药物等，不用于形容人。"}, {"text": "这把椅子很有效。", "explanation": "这里应该用〈舒服〉。「有效」指达到预期结果，不用于形容椅子是否舒适。"}, {"text": "这条裙子很有效。", "explanation": "这里应该用〈好看〉。「有效」用于方法、药物等，不用于形容衣服的样子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc0cc312-6c8a-4816-81d1-52075941a40b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22910, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有效", "is_correct": true, "explanation": "「有效」问的是这种办法治失眠的效果，符合句意。"}, {"text": "冷清", "is_correct": false, "explanation": "语义：「冷清」形容场面不热闹，不能用来问办法的效果。"}, {"text": "甜", "is_correct": false, "explanation": "语义：「甜」描述味道，与治疗失眠的效果无关。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：「胖」描述体形，不能用于失眠的治疗效果。"}], "explanations": {"有效": "「有效」问的是这种办法治失眠的效果，符合句意。", "冷清": "语义：「冷清」形容场面不热闹，不能用来问办法的效果。", "甜": "语义：「甜」描述味道，与治疗失眠的效果无关。", "胖": "体貌：「胖」描述体形，不能用于失眠的治疗效果。"}, "sentence_index": 6, "correct_answer": "有效"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的眼睛很有效。", "explanation": "这里应该用〈敏锐〉。「有效」不用于形容身体器官。"}, {"text": "这首歌很有效。", "explanation": "这里应该用〈好听〉。「有效」指达到想要的结果，不用于评价歌曲。"}, {"text": "这个城市很有效。", "explanation": "这里应该用〈繁华〉。「有效」不用于形容地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc0cc312-6c8a-4816-81d1-52075941a40b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22910, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个方法把感冒有效。", "corrected_sentence": "这个方法对感冒有效。", "error_description": "错误：「有效」后面的对象要用「对」引出，不能用「把」。「把」字句需要动词，「有效」是形容词，不能用于「把」字句。错误形式是「把感冒有效」，正确形式是「对感冒有效」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc0cc312-6c8a-4816-81d1-52075941a40b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22910, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个办法的有效很好。", "corrected_sentence": "这个办法的有效性很好。", "error_description": "错误：「有效」作名词使用时要加「性」，「有效」直接作主语不成立。正确：应为「有效性」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc0cc312-6c8a-4816-81d1-52075941a40b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
