INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22912, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "对危险或不好的事情很注意的能力。", "primary_collocate": null, "pronunciation": "jǐng jué xìng", "ipa": "tɕiŋ˨˩˦ tɕɥɛ˧˥ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "出门在外，要有警觉性。", "target_word": "警觉性", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的警觉性很高，马上发现有人跟着他。", "target_word": "警觉性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小孩子缺少警觉性，容易上当。", "target_word": "警觉性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈教女儿提高警觉性，不要随便开门。", "target_word": "警觉性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "猫的警觉性比狗还高。", "target_word": "警觉性", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "晚上一个人走路，警觉性要高一点。", "target_word": "警觉性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察的警觉性让他躲过了危险。", "target_word": "警觉性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有警觉性的人，容易遇到麻烦。", "target_word": "警觉性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他睡着了，但警觉性还在。", "target_word": "警觉性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人接到陌生电话，警觉性很重要。", "target_word": "警觉性", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "警覺性", "label": "繁体"}], "register": "中性", "sense_fingerprint": "警觉性|对危险或坏事很注意的能力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef4b2287-278a-4737-b987-92485fc5a6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22912, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "警觉性", "is_correct": true, "explanation": "正确：“要有警觉性”指对危险保持注意，符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不是出门时应具备的素质，“要有颜色”句意不通。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”是身体条件，不能说“要有身高”。"}, {"text": "形状", "is_correct": false, "explanation": "语义：“形状”不是出门时应具备的素质，句意不通。"}], "explanations": {"警觉性": "正确：“要有警觉性”指对危险保持注意，符合句意。", "颜色": "语义：“颜色”不是出门时应具备的素质，“要有颜色”句意不通。", "身高": "体貌：“身高”是身体条件，不能说“要有身高”。", "形状": "语义：“形状”不是出门时应具备的素质，句意不通。"}, "sentence_index": 0, "correct_answer": "警觉性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的警觉性很好，很喜欢交朋友。", "explanation": "这里应该用〈性格〉。“警觉性”指对危险的注意能力，不指性格，也与交朋友无关。"}, {"text": "孩子上课时警觉性很集中。", "explanation": "这里应该用〈注意力〉。“集中”用于注意力，“警觉性”指对危险的察觉，不说“警觉性很集中”。"}, {"text": "他把警觉性借给了朋友。", "explanation": "这里应该用〈传授〉（如“把经验传授给朋友”）。“借”的对象应是可以归还的东西，“警觉性”是个人的心理特性，不能借给别人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '443f7d88-91de-4998-9682-7cbd7ec12a8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22912, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "警觉性", "is_correct": true, "explanation": "正确：“警察的警觉性”指对危险的察觉，正是这种察觉让他躲过了危险。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”是人的外形，不能使人躲过危险。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”与躲避危险无关，句意不通。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”不能帮助人躲过危险，句意不通。"}], "explanations": {"警觉性": "正确：“警察的警觉性”指对危险的察觉，正是这种察觉让他躲过了危险。", "身材": "体貌：“身材”是人的外形，不能使人躲过危险。", "价格": "语义：“价格”与躲避危险无关，句意不通。", "味道": "语义：“味道”不能帮助人躲过危险，句意不通。"}, "sentence_index": 6, "correct_answer": "警觉性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的汉语警觉性很高。", "explanation": "这里应该用〈水平〉。“警觉性”指对危险的察觉，不能用来形容语言能力。"}, {"text": "他的警觉性很暴躁。", "explanation": "这里应该用〈脾气〉。“暴躁”形容人的情绪，不能用来形容“警觉性”。"}, {"text": "他的警觉性很好，背课文从来没忘过。", "explanation": "这里应该用〈记忆〉。“警觉性”指对危险的注意能力，不指记住课文的能力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '443f7d88-91de-4998-9682-7cbd7ec12a8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22912, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个年轻人不有警觉性，容易上当。", "corrected_sentence": "这个年轻人没有警觉性，容易上当。", "error_description": "错误：“有”的否定形式要说“没有”，不能说“不有”。正确：“没有警觉性”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '443f7d88-91de-4998-9682-7cbd7ec12a8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22912, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老人的警觉性比以前提高很了。", "corrected_sentence": "老人的警觉性比以前提高了。", "error_description": "错误：“提高很了”，程度副词“很”不能插在动词“提高”和“了”之间。正确：“提高了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '443f7d88-91de-4998-9682-7cbd7ec12a8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
