INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22914, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "意思很深，很长久。", "primary_collocate": null, "pronunciation": "shēn cháng", "ipa": "ʂən˥ ʈʂʰɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这首诗寓意深长，很多人喜欢读。", "target_word": "深长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的这句话含意深长，我没有看懂。", "target_word": "深长", "complexity_tier": "T3", "furigana": "shēn cháng", "sentence_source": "generated"}, {"text": "这个故事的含意深长，孩子还不太懂。", "target_word": "深长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长的讲话寓意深长，大家听得很认真。", "target_word": "深长", "complexity_tier": "T3", "furigana": "shēn cháng", "sentence_source": "generated"}, {"text": "这幅画的寓意深长，让人看了又看。", "target_word": "深长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他慢慢地说：“你会明白的。”这话含意深长。", "target_word": "深长", "complexity_tier": "T3", "furigana": "shēn cháng", "sentence_source": "generated"}, {"text": "这本书的书名很短，但寓意深长。", "target_word": "深长", "complexity_tier": "T3", "furigana": "shēn cháng", "sentence_source": "generated"}, {"text": "奶奶的话简单，却含意深长。", "target_word": "深长", "complexity_tier": "T3", "furigana": "shēn cháng", "sentence_source": "generated"}, {"text": "她留下了一句含意深长的话。", "target_word": "深长", "complexity_tier": "T3", "furigana": "shēn cháng", "sentence_source": "generated"}, {"text": "这个电影的名字寓意深长。", "target_word": "深长", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "形容话语、故事、寓意含义深刻耐人寻味", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef4b2287-278a-4737-b987-92485fc5a6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22914, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "深长", "is_correct": true, "explanation": "正确答案。深长指含意深远、耐人寻味。"}, {"text": "生长", "is_correct": false, "explanation": "shēng（后鼻音 -ng）与 shēn（前鼻音 -n）韵母不同，意思是生长（指植物或人的发育）。"}, {"text": "深重", "is_correct": false, "explanation": "chóng（-ong）与 cháng（-ang）韵母不同，意思是深重（程度深、分量大）。"}, {"text": "深藏", "is_correct": false, "explanation": "cáng 与 cháng 仅声母 c/ch 不同，意思是深深地藏起来。"}], "explanations": {"深长": "正确答案。深长指含意深远、耐人寻味。", "生长": "shēng（后鼻音 -ng）与 shēn（前鼻音 -n）韵母不同，意思是生长（指植物或人的发育）。", "深重": "chóng（-ong）与 cháng（-ang）韵母不同，意思是深重（程度深、分量大）。", "深藏": "cáng 与 cháng 仅声母 c/ch 不同，意思是深深地藏起来。"}, "sentence_index": null, "correct_answer": "深长"}, "level_3": {"options": [{"text": "深长", "is_correct": true, "explanation": "正确。寓意深长指含义深远、耐人寻味，与“很多人喜欢读”相符。"}, {"text": "高大", "is_correct": false, "explanation": "搭配：“高大”描写人或物的体型，不用来修饰“寓意”。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”形容声音，“寓意”不能清脆。"}, {"text": "瘦长", "is_correct": false, "explanation": "体貌：“瘦长”描写外形，“寓意”是抽象内容，不能瘦长。"}], "explanations": {"深长": "正确。寓意深长指含义深远、耐人寻味，与“很多人喜欢读”相符。", "高大": "搭配：“高大”描写人或物的体型，不用来修饰“寓意”。", "清脆": "搭配：“清脆”形容声音，“寓意”不能清脆。", "瘦长": "体貌：“瘦长”描写外形，“寓意”是抽象内容，不能瘦长。"}, "sentence_index": 0, "correct_answer": "深长"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这部电影的票价十分深长，观众看得很过瘾。", "explanation": "这里应该用〈便宜〉。深长指含意深远，不能用来形容价格高低；价格低要用便宜。"}, {"text": "这道数学题非常深长，我花了很久才弄懂。", "explanation": "这里应该用〈深奥〉。深长指含意深远，不用来形容学问或题目难懂。"}, {"text": "这场地震给当地带来了深长的灾难。", "explanation": "这里应该用〈深重〉。深重指灾难、损失的程度很重，深长不用于此。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '443f7d88-91de-4998-9682-7cbd7ec12a8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22914, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "深长", "is_correct": true, "explanation": "正确。句中“但”转折，前半句说书名短，后半句说寓意深长。"}, {"text": "短小", "is_correct": false, "explanation": "搭配：“短小”说篇幅，不说“寓意短小”。"}, {"text": "响亮", "is_correct": false, "explanation": "搭配：“响亮”形容声音，不修饰“寓意”。"}, {"text": "瘦小", "is_correct": false, "explanation": "体貌：“瘦小”描写外形，“寓意”不能瘦小。"}], "explanations": {"深长": "正确。句中“但”转折，前半句说书名短，后半句说寓意深长。", "短小": "搭配：“短小”说篇幅，不说“寓意短小”。", "响亮": "搭配：“响亮”形容声音，不修饰“寓意”。", "瘦小": "体貌：“瘦小”描写外形，“寓意”不能瘦小。"}, "sentence_index": 6, "correct_answer": "深长"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们沿着深长的沟壑走了很久。", "explanation": "这里的〈深长〉用来形容沟壑的空间深度和长度，但“深长”只用于意思、含意等抽象事物，不能描述有形的地貌。"}, {"text": "这道深长的裂缝从山顶一直延伸到山脚。", "explanation": "这里的〈深长〉用来形容裂缝的空间深度和长度，但“深长”只用于意思、含意等抽象事物，不能描述有形的裂缝。"}, {"text": "火车穿过了一条深长的隧道。", "explanation": "这里的〈深长〉用来形容隧道的空间深度和长度，但“深长”只用于意思、含意等抽象事物，不能描述有形的隧道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '443f7d88-91de-4998-9682-7cbd7ec12a8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22914, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这篇散文的寓意深不长，读后让人觉得平淡。", "corrected_sentence": "这篇散文的寓意深长，读后让人觉得平淡。", "error_description": "错误：“深不长”，否定词“不”插进了词语“深长”中间。“深长”是一个不可拆分的词，“不”不能插入其中。正确：“深长”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '443f7d88-91de-4998-9682-7cbd7ec12a8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22914, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这封信的字里行间含意得深长，让人回味无穷。", "corrected_sentence": "这封信的字里行间含意深长，让人回味无穷。", "error_description": "错误：“含意得深长”，多加了“得”。正确：“含意深长”。“得”只接在动词后引出补语，“含意”后直接接形容词作谓语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '443f7d88-91de-4998-9682-7cbd7ec12a8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
