INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22916, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "血液是身体里流动的红色液体，帮助运送营养和氧气。", "primary_collocate": null, "pronunciation": "xuè yè", "ipa": "ɕɥɛ˥˩ jɛ˥˩", "syllable_count": 2, "sentences": [{"text": "身体里流着红色的血液。", "target_word": "血液", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "血液把氧气送到身体各处。", "target_word": "血液", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "食物里的营养通过血液送到全身。", "target_word": "血液", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "受伤以后，伤口流出了很多血液。", "target_word": "血液", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生说他的血液检查结果正常。", "target_word": "血液", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "献血就是把自己的一点血液给病人。", "target_word": "血液", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气冷的时候，手脚的血液流得慢。", "target_word": "血液", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蚊子叮人是为了吸一点血液。", "target_word": "血液", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "心跳停了，血液就不能流动了。", "target_word": "血液", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "护士用针从手臂抽出少量血液。", "target_word": "血液", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一滴血液", "label": "量词"}], "register": "书面", "sense_fingerprint": "血液|身体里流动的红色液体，运送营养和氧气", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bf78d8d-1b55-43c3-ab25-4cc6f914996e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22916, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "墨水", "is_correct": false, "explanation": "语义：墨水不是人体里的液体，身体里不会流着墨水。"}, {"text": "血液", "is_correct": true, "explanation": "正确：血液是身体里流动的红色液体，与句意相合。"}, {"text": "颜料", "is_correct": false, "explanation": "语义：颜料用于绘画，不会在身体里流动。"}, {"text": "玫瑰", "is_correct": false, "explanation": "搭配：“流”不与“玫瑰”搭配，花不会在身体里流动。"}], "explanations": {"墨水": "语义：墨水不是人体里的液体，身体里不会流着墨水。", "血液": "正确：血液是身体里流动的红色液体，与句意相合。", "颜料": "语义：颜料用于绘画，不会在身体里流动。", "玫瑰": "搭配：“流”不与“玫瑰”搭配，花不会在身体里流动。"}, "sentence_index": 0, "correct_answer": "血液"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "护士抽了一条血液做检查。", "explanation": "量词：〈条〉用于细长的东西，血液是液体，应说“一管血液”或“一些血液”。"}, {"text": "他把血液挂在墙上当装饰。", "explanation": "语义：血液在身体里流动，不能挂在墙上当装饰，这里的用法不合常理。"}, {"text": "他每天都要给血液浇水。", "explanation": "语义：血液是体内的液体，不能像植物那样浇水，“浇水”与血液搭配错误。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff11a5a9-5807-4f92-84e1-243e87b3e6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22916, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "河水", "is_correct": false, "explanation": "语义：手脚里流动的是血液，不是河水，句意不通。"}, {"text": "石油", "is_correct": false, "explanation": "语义：石油不是人体内的液体，手脚里不会流石油。"}, {"text": "血液", "is_correct": true, "explanation": "正确：天冷时手脚的血液流得慢，这是常见的说法，与句意相合。"}, {"text": "脚印", "is_correct": false, "explanation": "搭配：“流”不与“脚印”搭配，脚印不会流动。"}], "explanations": {"河水": "语义：手脚里流动的是血液，不是河水，句意不通。", "石油": "语义：石油不是人体内的液体，手脚里不会流石油。", "血液": "正确：天冷时手脚的血液流得慢，这是常见的说法，与句意相合。", "脚印": "搭配：“流”不与“脚印”搭配，脚印不会流动。"}, "sentence_index": 6, "correct_answer": "血液"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用血液擦了桌子。", "explanation": "语义：擦桌子要用抹布或湿布，血液是体内的液体，不能作为清洁工具。"}, {"text": "他在花瓶里装了一些血液。", "explanation": "语义：花瓶里应该装水或插花，血液是体内的液体，不能用来装花瓶。"}, {"text": "他把血液装进书包去上学。", "explanation": "语义：血液在血管里循环，不能像物品一样装进书包。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff11a5a9-5807-4f92-84e1-243e87b3e6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22916, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "护士从他的手指取了一颗血液。", "corrected_sentence": "护士从他的手指取了一滴血液。", "error_description": "错误形式“一颗血液”，正确形式“一滴血液”。“颗”用于颗粒状或圆形的小物，血液应以“滴”计量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff11a5a9-5807-4f92-84e1-243e87b3e6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22916, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "天气冷的时候，血液流的很慢。", "corrected_sentence": "天气冷的时候，血液流得很慢。", "error_description": "错误形式“流的很慢”，正确形式“流得很慢”。表示动作程度的补语前要用结构助词“得”，不用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff11a5a9-5807-4f92-84e1-243e87b3e6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
