INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22920, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "很重要，能决定事情的结果。", "primary_collocate": null, "pronunciation": "guān jiàn", "ipa": "kwan⁵⁵ tɕjɛn⁵¹", "syllable_count": 2, "sentences": [{"text": "这是最关键的一步。", "target_word": "关键", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "考试前，睡好觉很关键。", "target_word": "关键", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个问题非常关键。", "target_word": "关键", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "比赛的关键时刻到了。", "target_word": "关键", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在关键的时候帮了我。", "target_word": "关键", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次机会对他很关键。", "target_word": "关键", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "关键的问题是我们没有钱。", "target_word": "关键", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听懂这句话很关键。", "target_word": "关键", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "在关键时刻，他没有放弃。", "target_word": "关键", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个电话很关键，请你接一下。", "target_word": "关键", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "关键词", "label": "复合"}], "register": "中性", "sense_fingerprint": "极其重要，决定结果的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0e621cd-3813-46e8-abfa-9d13f45d7637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22920, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "关键", "is_correct": true, "explanation": "关键：很重要、能决定结果，与“最……的一步”搭配自然。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”形容味道，不能用来形容一步。"}, {"text": "咸", "is_correct": false, "explanation": "语义：“咸”形容味道，不能用来形容一步。"}, {"text": "美味", "is_correct": false, "explanation": "搭配：“美味”修饰食物，不能与“步”搭配。"}], "explanations": {"关键": "关键：很重要、能决定结果，与“最……的一步”搭配自然。", "甜": "语义：“甜”形容味道，不能用来形容一步。", "咸": "语义：“咸”形容味道，不能用来形容一步。", "美味": "搭配：“美味”修饰食物，不能与“步”搭配。"}, "sentence_index": 0, "correct_answer": "关键"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他拿着关键开了门。", "explanation": "这里应该用〈钥匙〉。关键指重要的部分，不指开门的钥匙。"}, {"text": "他很关键地笑了。", "explanation": "这里应该用〈得意〉。关键是形容词，指重要，不用来形容笑的样子。"}, {"text": "他的心情很关键。", "explanation": "这里应该用〈紧张〉。关键用于事情或问题，不用来描述心情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17b07f93-993b-4a70-ab75-5a37f3853925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22920, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "关键", "is_correct": true, "explanation": "关键：指重要、起决定作用的，与“……的问题”搭配自然。"}, {"text": "绿色", "is_correct": false, "explanation": "语义：“绿色”指颜色，不能用来形容问题。"}, {"text": "好吃", "is_correct": false, "explanation": "语义：“好吃”形容食物味道，不能修饰问题。"}, {"text": "胖", "is_correct": false, "explanation": "搭配：“胖”形容人或动物的体型，不能修饰问题。"}], "explanations": {"关键": "关键：指重要、起决定作用的，与“……的问题”搭配自然。", "绿色": "语义：“绿色”指颜色，不能用来形容问题。", "好吃": "语义：“好吃”形容食物味道，不能修饰问题。", "胖": "搭配：“胖”形容人或动物的体型，不能修饰问题。"}, "sentence_index": 6, "correct_answer": "关键"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只小狗很关键。", "explanation": "这里应该用〈可爱〉。关键说事情的重要性，不用来形容动物的样子。"}, {"text": "我的汤很关键，太咸了。", "explanation": "这里应该用〈好喝〉。关键说事情的重要性，不用来形容味道。"}, {"text": "这些树很关键，长得很高。", "explanation": "这里应该用〈高大〉。关键不用来形容植物的外形。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17b07f93-993b-4a70-ab75-5a37f3853925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22920, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次谈判对双方都很关键地。", "corrected_sentence": "这次谈判对双方都很关键。", "error_description": "错误形式：“很关键地”。正确形式：“很关键”。“关键”作谓语时，后面不加“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17b07f93-993b-4a70-ab75-5a37f3853925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22920, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次面试对我很关键地。", "corrected_sentence": "这次面试对我很关键。", "error_description": "错误形式：“很关键地”。正确形式：“很关键”。“关键”作谓语时，后面不加“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17b07f93-993b-4a70-ab75-5a37f3853925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
