INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22922, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让热的东西变凉。", "primary_collocate": null, "pronunciation": "sàn rè", "ipa": "san˥˩ ʐɤ˥˩", "syllable_count": 2, "sentences": [{"text": "刚做好的饭要放一会儿散热。", "target_word": "散热", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "热汤放在窗边散热。", "target_word": "散热", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把热水倒进大杯子里散热。", "target_word": "散热", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蛋糕出炉后要先散热再吃。", "target_word": "散热", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "铁锅太烫了，让它先散热。", "target_word": "散热", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打开盖子，汤很快就散热了。", "target_word": "散热", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把牛奶放在桌上散热。", "target_word": "散热", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刚烧好的水需要散热。", "target_word": "散热", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "热饭菜放在盘子里更容易散热。", "target_word": "散热", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "炒好的菜先别盖盖子，让它散热。", "target_word": "散热", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "散热器", "label": "复合"}, {"form": "散熱", "label": "繁体"}], "register": "中性", "sense_fingerprint": "散热：让热的东西变凉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7740042-aad1-4fe5-9bfb-71d5cfaf9712') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22922, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "加热", "is_correct": false, "explanation": "语义：饭刚做好，本来就是热的，句中要的是让它变凉，不是再加热。"}, {"text": "煮", "is_correct": false, "explanation": "语义：饭已经做好，不能再“放一会儿煮”，句中的语境是等它降温。"}, {"text": "散热", "is_correct": true, "explanation": "散热：让热的东西散出热量而变凉，这里指刚做好的饭放一会儿降温。"}, {"text": "烤", "is_correct": false, "explanation": "搭配：“烤”用于需要加热成熟的食材，与“刚做好的饭”不搭，“放一会儿烤”说不通。"}], "explanations": {"加热": "语义：饭刚做好，本来就是热的，句中要的是让它变凉，不是再加热。", "煮": "语义：饭已经做好，不能再“放一会儿煮”，句中的语境是等它降温。", "散热": "散热：让热的东西散出热量而变凉，这里指刚做好的饭放一会儿降温。", "烤": "搭配：“烤”用于需要加热成熟的食材，与“刚做好的饭”不搭，“放一会儿烤”说不通。"}, "sentence_index": 0, "correct_answer": "散热"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "下了一场大雨，天气终于散热了。", "explanation": "这里应该用〈降温〉。散热指热的东西自己放出热量而变凉，天气转凉要用降温。"}, {"text": "他这两天一直散热，还得去医院看看。", "explanation": "这里应该用〈发热〉。散热是热的物体放出热量，人生病体温升高要说发热。"}, {"text": "冬天我们围着火炉散热。", "explanation": "这里应该用〈取暖〉。散热的主语是放出热量的物体，人靠火炉暖和要说取暖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7041e5ae-641a-4e84-b391-c822496737a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22922, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "煎", "is_correct": false, "explanation": "语义：牛奶不能被“煎”，放在桌上也没有加热，句中要的是它慢慢变凉。"}, {"text": "冷藏", "is_correct": false, "explanation": "搭配：冷藏需要冰箱等设备，不能只是放在桌上。"}, {"text": "蒸", "is_correct": false, "explanation": "语义：蒸需要水汽加热，牛奶放在桌上不会被“蒸”，句中要的是慢慢变凉。"}, {"text": "散热", "is_correct": true, "explanation": "散热：让热的东西散出热量而变凉，这里指牛奶放在桌上慢慢降温。"}], "explanations": {"煎": "语义：牛奶不能被“煎”，放在桌上也没有加热，句中要的是它慢慢变凉。", "冷藏": "搭配：冷藏需要冰箱等设备，不能只是放在桌上。", "蒸": "语义：蒸需要水汽加热，牛奶放在桌上不会被“蒸”，句中要的是慢慢变凉。", "散热": "散热：让热的东西散出热量而变凉，这里指牛奶放在桌上慢慢降温。"}, "sentence_index": 6, "correct_answer": "散热"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这一会儿，我的热情都散热了。", "explanation": "这里的“散”是消散、减退的意思，指感情慢慢减弱；“散热”只指热的物体放出热量，不能用于感情。"}, {"text": "他脾气很热，最近终于散热了。", "explanation": "这里说的是性情急躁、怒气冲冲后又慢慢平息，“散热”只用于热的物体放出热量，不能用来形容怒气平息。"}, {"text": "这盘菜的香味慢慢散热了。", "explanation": "这里的“散”是“散发、传开”的意思，气味慢慢扩散开来；“散热”指热的物体放出热量，不能用于气味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7041e5ae-641a-4e84-b391-c822496737a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22922, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "锅刚从炉子上拿下来，要把它散热再洗。", "corrected_sentence": "锅刚从炉子上拿下来，要等它散热再洗。", "error_description": "句式错误：“散热”是不及物动词，“把它”不能作它的宾语，“把它散热”不成立，应说“等它散热”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7041e5ae-641a-4e84-b391-c822496737a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22922, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "刚出锅的汤要先散热的才能喝。", "corrected_sentence": "刚出锅的汤要先散热才能喝。", "error_description": "多出“的”：“要先散热才能喝”中“散热”直接作谓语，其后加“的”使句子不通，应说“先散热才能喝”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7041e5ae-641a-4e84-b391-c822496737a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
