INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22924, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "区域就是一块地方。", "primary_collocate": null, "pronunciation": "qū yù", "ipa": "tɕʰy˥ y˥˩", "syllable_count": 2, "sentences": [{"text": "孩子们在游戏区域玩球。", "target_word": "区域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个区域是给客人坐的。", "target_word": "区域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院里这个区域只有医生能进。", "target_word": "区域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在黄线外的区域等车。", "target_word": "区域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里有一个安静的阅读区域。", "target_word": "区域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把东西放在了这个区域。", "target_word": "区域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房是做饭的区域。", "target_word": "区域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商场的食品区域在一楼。", "target_word": "区域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块区域只能走路，不能骑车。", "target_word": "区域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校分出了一个运动区域。", "target_word": "区域", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "块", "label": "量词"}, {"form": "區域", "label": "繁体"}], "register": "中性", "sense_fingerprint": "区域：一块地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7740042-aad1-4fe5-9bfb-71d5cfaf9712') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22924, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人口", "is_correct": false, "explanation": "语义：人口是人数，不是可以玩球的场地，「在游戏人口玩球」说不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是气象状况，不能作为玩球的地方。"}, {"text": "区域", "is_correct": true, "explanation": "区域指一块地方，「游戏区域」是孩子们玩球的场地，与语境相符。"}, {"text": "区划", "is_correct": false, "explanation": "语域：区划是行政用语，在口语中描述玩球场地不自然。"}], "explanations": {"人口": "语义：人口是人数，不是可以玩球的场地，「在游戏人口玩球」说不通。", "天气": "语义：天气是气象状况，不能作为玩球的地方。", "区域": "区域指一块地方，「游戏区域」是孩子们玩球的场地，与语境相符。", "区划": "语域：区划是行政用语，在口语中描述玩球场地不自然。"}, "sentence_index": 0, "correct_answer": "区域"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个区域很重，我一个人搬不动。", "explanation": "这里应该用〈箱子〉。区域指空间范围，不能说「很重」；有分量、搬得动的是箱子。"}, {"text": "这首歌的区域很美，大家都爱听。", "explanation": "这里应该用〈旋律〉。区域指空间或地方，形容歌曲好听要说旋律，不能说「区域很美」。"}, {"text": "我家门口有一条区域。", "explanation": "量词错误：区域应用「个」「块」等量词，「条」不能用于区域。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7041e5ae-641a-4e84-b391-c822496737a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22924, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "时间", "is_correct": false, "explanation": "语义：时间是时段，不是可以做饭的空间，「厨房是做饭的时间」说不通。"}, {"text": "故事", "is_correct": false, "explanation": "语义：故事是叙述性的作品，「厨房是做饭的故事」语义不通。"}, {"text": "区域", "is_correct": true, "explanation": "区域指一块地方，厨房是专门做饭的地方，与语境相符。"}, {"text": "版图", "is_correct": false, "explanation": "语域：版图偏书面，指领土范围，不用于说明厨房的功能。"}], "explanations": {"时间": "语义：时间是时段，不是可以做饭的空间，「厨房是做饭的时间」说不通。", "故事": "语义：故事是叙述性的作品，「厨房是做饭的故事」语义不通。", "区域": "区域指一块地方，厨房是专门做饭的地方，与语境相符。", "版图": "语域：版图偏书面，指领土范围，不用于说明厨房的功能。"}, "sentence_index": 6, "correct_answer": "区域"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他轻轻推开了区域。", "explanation": "这里应该用〈门〉。区域指空间，不能被推开；推开的是具体的门。"}, {"text": "这句话的区域很深，我没听懂。", "explanation": "这里应该用〈意思〉。区域指空间，句子的含义要用意思，不能说「区域很深」。"}, {"text": "他的区域很开朗，大家都喜欢和他聊天。", "explanation": "这里应该用〈性格〉。区域指空间，形容人的性格要用性格，不能说「区域很开朗」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7041e5ae-641a-4e84-b391-c822496737a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22924, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公园里有一条专门的游戏区域。", "corrected_sentence": "公园里有一块专门的游戏区域。", "error_description": "量词错误：「区域」应用「块」「个」等量词，不用「条」。「条」用于河、路等长条形事物。正确说法是「一块专门的游戏区域」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7041e5ae-641a-4e84-b391-c822496737a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22924, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "车站划出了两候车区域。", "corrected_sentence": "车站划出了两块候车区域。", "error_description": "量词缺失：数词「两」后面要加量词，应说「两块候车区域」，不能直接说「两候车区域」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7041e5ae-641a-4e84-b391-c822496737a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
