INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22926, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让事情变得不多不少刚刚好。", "primary_collocate": null, "pronunciation": "tiáo kòng", "ipa": "tʰjaʊ³⁵ kʰʊŋ⁵¹", "syllable_count": 2, "sentences": [{"text": "政府想调控房价。", "target_word": "调控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空调会自动调控房间的温度。", "target_word": "调控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生用药物调控他的血糖。", "target_word": "调控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家调控粮食的价格。", "target_word": "调控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器能调控水的多少。", "target_word": "调控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学会调控自己的心情很重要。", "target_word": "调控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人调控着水池里的水位。", "target_word": "调控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行调控钱的多少,让物价稳定。", "target_word": "调控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人体通过出汗调控体温，保持稳定。", "target_word": "调控", "complexity_tier": "T3", "furigana": "rén tǐ tōngguò chū hàn tiáokòng tǐwēn, bǎochí wěndìng.", "sentence_source": "generated"}, {"text": "公司用新办法调控生产的速度。", "target_word": "调控", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "调控了", "label": "体标"}, {"form": "调控着", "label": "体标"}], "register": "书面", "sense_fingerprint": "调节并控制使其适度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fef3691-c05f-4979-b766-4af9a742d3ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22926, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "调控", "is_correct": true, "explanation": "正确：“调控”表示调节到适当程度，符合“政府想调控房价”的意思。"}, {"text": "调动", "is_correct": false, "explanation": "搭配：“调动”多用于人员、资源，不能用来说“调动房价”。"}, {"text": "上涨", "is_correct": false, "explanation": "配价：“上涨”是不及物动词，不能带宾语“房价”，“想上涨房价”不成立。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”表示赏识或喜爱，“政府想欣赏房价”说不通。"}], "explanations": {"调控": "正确：“调控”表示调节到适当程度，符合“政府想调控房价”的意思。", "调动": "搭配：“调动”多用于人员、资源，不能用来说“调动房价”。", "上涨": "配价：“上涨”是不及物动词，不能带宾语“房价”，“想上涨房价”不成立。", "欣赏": "语义：“欣赏”表示赏识或喜爱，“政府想欣赏房价”说不通。"}, "sentence_index": 0, "correct_answer": "调控"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他调控了我的邀请。", "explanation": "这里应该用〈拒绝〉。“调控”用于数量、温度、水平等可调节的对象，不能用于“邀请”。"}, {"text": "这个问题很简单，我一下子就调控了它。", "explanation": "这里应该用〈解决〉。“调控”是调节到适当程度，不表示消除问题。"}, {"text": "他调控了一只猫。", "explanation": "这里应该用〈养〉。“调控”用于可调节的数量或状态，不能用于动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57b75a7c-a155-452c-a492-ca710e44ce91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22926, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "调控", "is_correct": true, "explanation": "正确：“调控”表示调节到适当程度，“调控着水位”指工人在调节水位。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象要是可以饮用的东西，不能说“喝水位”。"}, {"text": "挖", "is_correct": false, "explanation": "搭配：“挖”的对象是具体的物体，不能说“挖水位”。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指唱歌，工人唱着水位的说法没有意义。"}], "explanations": {"调控": "正确：“调控”表示调节到适当程度，“调控着水位”指工人在调节水位。", "喝": "搭配：“喝”的对象要是可以饮用的东西，不能说“喝水位”。", "挖": "搭配：“挖”的对象是具体的物体，不能说“挖水位”。", "唱": "语义：“唱”指唱歌，工人唱着水位的说法没有意义。"}, "sentence_index": 6, "correct_answer": "调控"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师调控了这篇文章。", "explanation": "这里应该用〈赞美〉。“调控”用于可调节的数量或状态，不能用于文章。"}, {"text": "我们调控你的到来。", "explanation": "这里应该用〈欢迎〉。“调控”是调节程度，不能用于“到来”。"}, {"text": "警察正在调控这起案件。", "explanation": "这里应该用〈调查〉。“调控”是调节到适当程度，不能用于查明案件的事实。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57b75a7c-a155-452c-a492-ca710e44ce91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22926, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府会调控了粮价。", "corrected_sentence": "政府会调控粮价。", "error_description": "“了”表示已经完成，与“会”表示的将来或可能矛盾。“会调控了粮价”错误，应为“会调控粮价”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57b75a7c-a155-452c-a492-ca710e44ce91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22926, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把水温调控刚刚好。", "corrected_sentence": "他把水温调控得刚刚好。", "error_description": "补语“刚刚好”前面需要“得”。“调控刚刚好”缺少“得”，错误，应为“调控得刚刚好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57b75a7c-a155-452c-a492-ca710e44ce91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
