INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22928, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "处理器是电脑或手机里负责计算和控制的核心部件。", "primary_collocate": null, "pronunciation": "chǔ lǐ qì", "ipa": "tʂʰu˨˩˦ li˨˩˦ tɕʰi˥˩", "syllable_count": 3, "sentences": [{"text": "这台电脑的处理器很快。", "target_word": "处理器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "处理器太旧，电脑开机很慢。", "target_word": "处理器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了一块新的处理器。", "target_word": "处理器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机的处理器越好，游戏越流畅。", "target_word": "处理器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "处理器热了，电脑会自己变慢。", "target_word": "处理器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想换一个更快的处理器。", "target_word": "处理器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个处理器是哪个公司做的？", "target_word": "处理器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "处理器就像电脑的大脑。", "target_word": "处理器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作人员给电脑装上了处理器。", "target_word": "处理器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块处理器每秒能算很多次。", "target_word": "处理器", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "块", "label": "量词"}, {"form": "處理器", "label": "繁体"}], "register": "中性", "sense_fingerprint": "电脑或手机里负责运算和控制的核心部件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7740042-aad1-4fe5-9bfb-71d5cfaf9712') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22928, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "外壳", "is_correct": false, "explanation": "语义：外壳是机身的外部，没有快慢之分，句中说的是运算速度。"}, {"text": "包装", "is_correct": false, "explanation": "搭配：“很快”不搭配“包装”，包装不说快慢。"}, {"text": "音箱", "is_correct": false, "explanation": "语义：音箱负责发声，“很快”指运算或响应，不适用于音箱。"}, {"text": "处理器", "is_correct": true, "explanation": "处理器：电脑中负责运算的核心部件，“很快”指它的运算速度快。"}], "explanations": {"外壳": "语义：外壳是机身的外部，没有快慢之分，句中说的是运算速度。", "包装": "搭配：“很快”不搭配“包装”，包装不说快慢。", "音箱": "语义：音箱负责发声，“很快”指运算或响应，不适用于音箱。", "处理器": "处理器：电脑中负责运算的核心部件，“很快”指它的运算速度快。"}, "sentence_index": 0, "correct_answer": "处理器"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个处理器的屏幕很大，看电影很清楚。", "explanation": "这里应该用〈显示器〉。屏幕和画面由显示器负责，处理器只负责运算。"}, {"text": "这块处理器充一次电能用两天。", "explanation": "这里应该用〈电池〉。充电和续航靠电池，处理器是运算部件，不能充电。"}, {"text": "这台电脑的处理器太小，装不下这么多照片。", "explanation": "这里应该用〈硬盘〉。存放照片要靠硬盘，处理器负责运算，不负责存放。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7041e5ae-641a-4e84-b391-c822496737a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22928, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "作业", "is_correct": false, "explanation": "语义：作业是学生完成的任务，不是公司生产出来的东西。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：天气不是公司制造的，不能说“是哪个公司做的”。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是任何公司做出来的，句中问的是一件产品。"}, {"text": "处理器", "is_correct": true, "explanation": "处理器：电脑中的核心部件，这里问的是它由哪家公司生产。"}], "explanations": {"作业": "语义：作业是学生完成的任务，不是公司生产出来的东西。", "天气": "搭配：天气不是公司制造的，不能说“是哪个公司做的”。", "空气": "语义：空气不是任何公司做出来的，句中问的是一件产品。", "处理器": "处理器：电脑中的核心部件，这里问的是它由哪家公司生产。"}, "sentence_index": 6, "correct_answer": "处理器"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块处理器可以拿来做家具，颜色很好看。", "explanation": "处理器是电脑里的芯片，不是家具材料，句中把它的用途说错了。"}, {"text": "他是一名处理器，每天负责整理档案。", "explanation": "“处理器”是电脑中的部件，不能用来指人，句中把它当作职业名称，用法是错的。"}, {"text": "妈妈把牛奶放进这块处理器里保鲜。", "explanation": "这里应该用〈冰箱〉。处理器是电脑里的芯片，不能用来保鲜食物，保鲜要靠冰箱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7041e5ae-641a-4e84-b391-c822496737a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22928, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我给电脑换了一双新处理器。", "corrected_sentence": "我给电脑换了一个新处理器。", "error_description": "量词错误：“处理器”用“个”或“块”，“双”用于成对的东西，不能用于处理器。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7041e5ae-641a-4e84-b391-c822496737a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22928, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想买一个的新处理器。", "corrected_sentence": "我想买一个新处理器。", "error_description": "结构错误：数量词“一个”与修饰语“新”之间不能加“的”，应说“一个新处理器”，不说“一个的新处理器”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7041e5ae-641a-4e84-b391-c822496737a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
