INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22934, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "东西变得太烫了，会让人不舒服。", "primary_collocate": null, "pronunciation": "guò rè", "ipa": "kuo˥˩ ʐɤ˥˩", "syllable_count": 2, "sentences": [{"text": "这杯水过热，小心烫嘴。", "target_word": "过热", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗澡水不要过热，会烫伤皮肤。", "target_word": "过热", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汤过热了，等一会儿再喝。", "target_word": "过热", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宝宝的牛奶不能过热。", "target_word": "过热", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个暖手宝过热了，我拿不住。", "target_word": "过热", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电热水壶过热了，会自动断电。", "target_word": "过热", "complexity_tier": "T3", "furigana": "guò rè", "sentence_source": "generated"}, {"text": "房间里的暖气过热，我睡不着。", "target_word": "过热", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳下的椅子过热，不能坐。", "target_word": "过热", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咖啡过热，我喝了一口就放下了。", "target_word": "过热", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的奶瓶过热了，要等凉一点再给他。", "target_word": "过热", "complexity_tier": "T3", "furigana": "guò rè", "sentence_source": "generated"}], "morphological_forms": [{"form": "过热了", "label": "体标"}, {"form": "過熱", "label": "繁体"}], "register": "中性", "sense_fingerprint": "饮食或物品太烫，让人接触时不舒服", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7740042-aad1-4fe5-9bfb-71d5cfaf9712') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22934, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "过热", "is_correct": true, "explanation": "“过热”指东西太烫，与“小心烫嘴”相符。"}, {"text": "变凉", "is_correct": false, "explanation": "语义：水变凉了就不烫嘴，与“小心烫嘴”的提醒矛盾。"}, {"text": "结冰", "is_correct": false, "explanation": "语义：水结冰后不会烫嘴，句中的提醒无法成立。"}, {"text": "降温", "is_correct": false, "explanation": "搭配：水的温度下降一般说“变凉”，“降温”多用于气温和体温，且与“小心烫嘴”矛盾。"}], "explanations": {"过热": "“过热”指东西太烫，与“小心烫嘴”相符。", "变凉": "语义：水变凉了就不烫嘴，与“小心烫嘴”的提醒矛盾。", "结冰": "语义：水结冰后不会烫嘴，句中的提醒无法成立。", "降温": "搭配：水的温度下降一般说“变凉”，“降温”多用于气温和体温，且与“小心烫嘴”矛盾。"}, "sentence_index": 0, "correct_answer": "过热"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的作文过热，老师看了很满意。", "explanation": "这里应该用〈生动〉。过热只描述温度，形容作文的好坏要说生动。"}, {"text": "他每天工作过热，身体都累坏了。", "explanation": "这里应该用〈过度〉。过热只指东西太烫，工作过分要说“过度”。"}, {"text": "这个小店的服务员过热，客人都很喜欢。", "explanation": "这里应该用〈热情〉。过热只描述东西的温度，形容人的态度要说“热情”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7041e5ae-641a-4e84-b391-c822496737a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22934, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "过热", "is_correct": true, "explanation": "“过热”指暖气太烫，与“我睡不着”的原因相符。"}, {"text": "结冰", "is_correct": false, "explanation": "语义：暖气不会结冰，与暖气的用途矛盾。"}, {"text": "融化", "is_correct": false, "explanation": "语义：暖气是金属设备，不会融化，与句意不合。"}, {"text": "点火", "is_correct": false, "explanation": "搭配：暖气一般说“开”或“打开”，不说“点火”。"}], "explanations": {"过热": "“过热”指暖气太烫，与“我睡不着”的原因相符。", "结冰": "语义：暖气不会结冰，与暖气的用途矛盾。", "融化": "语义：暖气是金属设备，不会融化，与句意不合。", "点火": "搭配：暖气一般说“开”或“打开”，不说“点火”。"}, "sentence_index": 6, "correct_answer": "过热"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道数学题过热，我一看就会做。", "explanation": "这里应该用〈简单〉。过热只描述温度，形容题目的难易要说简单。"}, {"text": "他一听到好消息，就过热起来。", "explanation": "这里应该用〈兴奋〉。过热指东西的温度，人的情绪激动要说“兴奋”。"}, {"text": "这首歌的鼓点很过热，听得人心慌。", "explanation": "这里应该用〈强烈〉。过热只描述温度，鼓点、声音的力度要说“强烈”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7041e5ae-641a-4e84-b391-c822496737a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22934, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这锅粥过热着，先放凉再吃。", "corrected_sentence": "这锅粥过热了，先放凉再吃。", "error_description": "“过热”表示变化后的结果，后面要用“了”，不能用“着”。错误形式是“过热着”，正确形式是“过热了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7041e5ae-641a-4e84-b391-c822496737a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22934, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台电暖器用久了容易过热着，要定期检查。", "corrected_sentence": "这台电暖器用久了容易过热，要定期检查。", "error_description": "体标错误：“过热”表示变化后的结果，后面不能加“着”，应说“容易过热”，错误形式是“过热着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7041e5ae-641a-4e84-b391-c822496737a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
