INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22936, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff11a5a9-5807-4f92-84e1-243e87b3e6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22936, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "大脑里一个很小的地方，它管着身体很多重要的事情，比如饿不饿、冷不冷。", "primary_collocate": null, "pronunciation": "xià qiū nǎo", "ipa": "ɕja˥˩ tɕʰjoʊ˥ naʊ˨˩˦", "syllable_count": 3, "sentences": [{"text": "下丘脑是大脑里很小的一个地方。", "target_word": "下丘脑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气太冷时，下丘脑会让身体发抖。", "target_word": "下丘脑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你饿的时候，下丘脑会告诉你要吃饭。", "target_word": "下丘脑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下丘脑管着冷和热的感觉。", "target_word": "下丘脑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "口渴了就想喝水，这是下丘脑的作用。", "target_word": "下丘脑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师在课上讲了下丘脑的作用。", "target_word": "下丘脑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书上有一张下丘脑的图。", "target_word": "下丘脑", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "下丘脑虽然小，但是很重要。", "target_word": "下丘脑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "生病发烧时，下丘脑的工作也会变化。", "target_word": "下丘脑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们的心情好不好，也和下丘脑有关。", "target_word": "下丘脑", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "下丘腦", "label": "繁体"}], "register": "书面", "sense_fingerprint": "下丘脑|大脑里很小的地方，管着饿、冷等身体大事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bf78d8d-1b55-43c3-ab25-4cc6f914996e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22936, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "心脏", "is_correct": false, "explanation": "语义：心脏位于胸腔，不在大脑里，与“大脑里很小的一个地方”不符。"}, {"text": "下丘脑", "is_correct": true, "explanation": "正确：下丘脑是大脑里很小的一个区域，与句子描述相合。"}, {"text": "胃", "is_correct": false, "explanation": "语义：胃是消化器官，不在大脑里，句子说的是大脑中的地方。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“体温”是一个数值，不是地方，不能与“一个地方”搭配。"}], "explanations": {"心脏": "语义：心脏位于胸腔，不在大脑里，与“大脑里很小的一个地方”不符。", "下丘脑": "正确：下丘脑是大脑里很小的一个区域，与句子描述相合。", "胃": "语义：胃是消化器官，不在大脑里，句子说的是大脑中的地方。", "体温": "搭配：“体温”是一个数值，不是地方，不能与“一个地方”搭配。"}, "sentence_index": 0, "correct_answer": "下丘脑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "下丘脑管着人的思考和记忆。", "explanation": "这里应该用〈大脑〉。思考和记忆是大脑整体的功能；下丘脑只管饥饿、体温等，不负责思考和记忆。"}, {"text": "下丘脑负责身体的平衡。", "explanation": "这里应该用〈小脑〉。平衡由小脑负责；下丘脑主要管体温和饥饿。"}, {"text": "下丘脑分泌生长激素。", "explanation": "这里应该用〈脑垂体〉。生长激素由脑垂体分泌；下丘脑是通过释放激素来调控脑垂体的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff11a5a9-5807-4f92-84e1-243e87b3e6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22936, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "理由", "is_correct": false, "explanation": "语义：“理由”是抽象的说明，不能画成图，“一张理由的图”说不通。"}, {"text": "下丘脑", "is_correct": true, "explanation": "正确：下丘脑可以画成图，“书上有一张下丘脑的图”自然通顺。"}, {"text": "道理", "is_correct": false, "explanation": "语义：“道理”是抽象的，不能画成图，“一张道理的图”说不通。"}, {"text": "愿望", "is_correct": false, "explanation": "语义：“愿望”是心里的想法，不能画成图，“一张愿望的图”说不通。"}], "explanations": {"理由": "语义：“理由”是抽象的说明，不能画成图，“一张理由的图”说不通。", "下丘脑": "正确：下丘脑可以画成图，“书上有一张下丘脑的图”自然通顺。", "道理": "语义：“道理”是抽象的，不能画成图，“一张道理的图”说不通。", "愿望": "语义：“愿望”是心里的想法，不能画成图，“一张愿望的图”说不通。"}, "sentence_index": 6, "correct_answer": "下丘脑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生说他的一只下丘脑有些异常。", "explanation": "这里应该用〈个〉。下丘脑是不成对的器官，“只”多用于动物或成对的器官。"}, {"text": "书上画着一片下丘脑的样子。", "explanation": "这里应该用〈个〉。“片”用于平而薄的东西，下丘脑是立体结构，应用“个”。"}, {"text": "老师指着模型里的一根下丘脑讲解。", "explanation": "这里应该用〈个〉。“根”用于细长的东西，下丘脑不是细长结构，应用“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff11a5a9-5807-4f92-84e1-243e87b3e6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22936, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "下丘脑非常很小，却很重要。", "corrected_sentence": "下丘脑非常小，却很重要。", "error_description": "错误形式“非常很小”，正确形式“非常小”。“非常”和“很”都是程度副词，不能同时修饰同一个形容词，只用其一。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff11a5a9-5807-4f92-84e1-243e87b3e6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22936, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在课本上找到了这只下丘脑的位置。", "corrected_sentence": "我们在课本上找到了这个下丘脑的位置。", "error_description": "错误形式“这只下丘脑”，正确形式“这个下丘脑”。下丘脑是不成对的器官，量词应用“个”，“只”多用于动物或成对的器官。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff11a5a9-5807-4f92-84e1-243e87b3e6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22938, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "停止", "is_correct": true, "explanation": "停止：与“运行”意思相反，指机器、程序停下来不再工作。"}, {"text": "写字", "is_correct": false, "explanation": "写字：同为动词，但与“运行”没有反义或近义关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "唱歌：同为动词，但与“运行”没有反义或近义关系。"}, {"text": "种树", "is_correct": false, "explanation": "种树：同为动词，但与“运行”没有反义或近义关系。"}], "correct_answer": "停止", "explanations": {"停止": "停止：与“运行”意思相反，指机器、程序停下来不再工作。", "写字": "写字：同为动词，但与“运行”没有反义或近义关系。", "唱歌": "唱歌：同为动词，但与“运行”没有反义或近义关系。", "种树": "种树：同为动词，但与“运行”没有反义或近义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c6e4eaf-bbef-40a3-834b-a2f5a9583caa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22938, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "停止", "is_correct": true, "explanation": "停止：与“运行”意思相反，指程序、机器停下来不再工作。"}, {"text": "读书", "is_correct": false, "explanation": "读书：同为动词，但与“运行”没有反义或近义关系。"}, {"text": "切菜", "is_correct": false, "explanation": "切菜：同为动词，但与“运行”没有反义或近义关系。"}, {"text": "穿衣", "is_correct": false, "explanation": "穿衣：同为动词，但与“运行”没有反义或近义关系。"}], "correct_answer": "停止", "explanations": {"停止": "停止：与“运行”意思相反，指程序、机器停下来不再工作。", "读书": "读书：同为动词，但与“运行”没有反义或近义关系。", "切菜": "切菜：同为动词，但与“运行”没有反义或近义关系。", "穿衣": "穿衣：同为动词，但与“运行”没有反义或近义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c6e4eaf-bbef-40a3-834b-a2f5a9583caa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22938, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "东西动起来，开始工作。", "primary_collocate": null, "pronunciation": "yùn xíng", "ipa": "yn˥˩ ɕiŋ˨˦", "syllable_count": 2, "sentences": [{"text": "这台电脑运行得很快。", "target_word": "运行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地铁早上五点半开始运行。", "target_word": "运行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "软件正在运行，请等一下。", "target_word": "运行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个程序在旧手机上不能运行。", "target_word": "运行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "机器运行时声音很大。", "target_word": "运行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电脑运行太慢，我想换一台。", "target_word": "运行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个系统已经运行了三年。", "target_word": "运行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火车运行得很平稳，我睡着了。", "target_word": "运行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂的机器二十四小时运行着。", "target_word": "运行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "关掉别的软件，手机才会运行得快一点。", "target_word": "运行", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "运行了", "label": "完成体"}, {"form": "运行着", "label": "持续体"}, {"form": "运行过", "label": "经验体"}, {"form": "運行", "label": "繁体"}], "register": "中性", "sense_fingerprint": "机器、软件、系统等开动并持续工作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd39e035a-dda2-4ec6-9ffc-89dfa7d4a654') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22938, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "运行", "is_correct": true, "explanation": "运行：指机器、软件开动并持续工作，与“这台电脑”搭配。"}, {"text": "飞", "is_correct": false, "explanation": "语义：电脑不会飞，“飞得很快”说的是飞行的东西。"}, {"text": "游", "is_correct": false, "explanation": "搭配：“游”指在水里移动，不能用来形容电脑。"}, {"text": "咳嗽", "is_correct": false, "explanation": "语义：咳嗽是人的动作，电脑不能咳嗽。"}], "explanations": {"运行": "运行：指机器、软件开动并持续工作，与“这台电脑”搭配。", "飞": "语义：电脑不会飞，“飞得很快”说的是飞行的东西。", "游": "搭配：“游”指在水里移动，不能用来形容电脑。", "咳嗽": "语义：咳嗽是人的动作，电脑不能咳嗽。"}, "sentence_index": 0, "correct_answer": "运行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他运行得很快。", "explanation": "这里应该用〈跑〉。运行指机器、软件开动工作，不能用于人的跑步。"}, {"text": "同学们运行了一场辩论。", "explanation": "这里应该用〈举行〉。运行指机器、软件、系统开动工作，辩论要用举行。"}, {"text": "这股花香在屋子里运行。", "explanation": "这里应该用〈散发〉。运行指机器、软件、系统开动工作，花香在屋子里扩散要用散发。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c6e4eaf-bbef-40a3-834b-a2f5a9583caa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22938, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "运行", "is_correct": true, "explanation": "运行：指系统开动并持续工作，与“三年”呼应。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：系统不能结婚，与“已经……了三年”的意思不符。"}, {"text": "生长", "is_correct": false, "explanation": "搭配：“生长”多用于植物、动物，不能用来说系统。"}, {"text": "毕业", "is_correct": false, "explanation": "语义：系统不会毕业，句意不通。"}], "explanations": {"运行": "运行：指系统开动并持续工作，与“三年”呼应。", "结婚": "语义：系统不能结婚，与“已经……了三年”的意思不符。", "生长": "搭配：“生长”多用于植物、动物，不能用来说系统。", "毕业": "语义：系统不会毕业，句意不通。"}, "sentence_index": 6, "correct_answer": "运行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会议正在运行。", "explanation": "这里应该用〈进行〉。运行指机器、软件、系统开动工作，会议要用进行。"}, {"text": "小狗在草地上运行。", "explanation": "这里应该用〈奔跑〉。运行指机器、系统的持续工作，动物的跑要用奔跑。"}, {"text": "他运行了窗户。", "explanation": "这里应该用〈打开〉。运行用于机器、系统，窗户要用打开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c6e4eaf-bbef-40a3-834b-a2f5a9583caa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22938, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台机器运行了得很平稳。", "corrected_sentence": "这台机器运行得很平稳。", "error_description": "错误：“运行了得”，动词带“得”补语时，“了”不能插在动词和“得”之间。正确：“运行得很平稳”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c6e4eaf-bbef-40a3-834b-a2f5a9583caa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22938, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这套系统一直运行的很稳定。", "corrected_sentence": "这套系统一直运行得很稳定。", "error_description": "错误：补语前的结构助词用了“的”，应为“得”。动词后带程度补语“很稳定”时要用“得”。正确：“运行得很稳定”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c6e4eaf-bbef-40a3-834b-a2f5a9583caa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
