INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22944, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "身体里像小豆子一样的一堆细胞。", "primary_collocate": null, "pronunciation": "hé tuán", "ipa": "xɤ˧˥ tʰwan˧˥", "syllable_count": 2, "sentences": [{"text": "核团像一小堆豆子。", "target_word": "核团", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "身体里有很多核团。", "target_word": "核团", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "核团是一堆小小的细胞。", "target_word": "核团", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "脑袋里有核团，也有神经。", "target_word": "核团", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生用机器看到了这个核团。", "target_word": "核团", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个核团在脑袋的深处。", "target_word": "核团", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "书上画着一个红色的核团。", "target_word": "核团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个核团的大小都不一样。", "target_word": "核团", "complexity_tier": "T3", "furigana": "měi gè hé tuán de dà xiǎo dōu bù yī yàng", "sentence_source": "generated"}, {"text": "老师说核团很小，眼睛看不见。", "target_word": "核团", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个核团看起来像一颗豆子。", "target_word": "核团", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "核團", "label": "繁体"}], "register": "中性", "sense_fingerprint": "身体里像小豆子的一堆细胞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee052b8c-9e6c-48f8-b11a-3507e31e09ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22944, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "核团", "is_correct": true, "explanation": "正确答案：核团 hé tuán，指身体里像小豆子一样的一堆细胞。"}, {"text": "和谈", "is_correct": false, "explanation": "tán（第二声）与 tuán（第二声）只差韵母中的 u，意思是和谈。"}, {"text": "河豚", "is_correct": false, "explanation": "tún（第二声）与 tuán（第二声）只差韵母中的 a，意思是河豚，一种鱼。"}, {"text": "河源", "is_correct": false, "explanation": "yuán（第二声）与 tuán（第二声）声母不同，意思是河流的源头。"}], "explanations": {"核团": "正确答案：核团 hé tuán，指身体里像小豆子一样的一堆细胞。", "和谈": "tán（第二声）与 tuán（第二声）只差韵母中的 u，意思是和谈。", "河豚": "tún（第二声）与 tuán（第二声）只差韵母中的 a，意思是河豚，一种鱼。", "河源": "yuán（第二声）与 tuán（第二声）声母不同，意思是河流的源头。"}, "sentence_index": null, "correct_answer": "核团"}, "level_3": {"options": [{"text": "核团", "is_correct": true, "explanation": "正确：核团是一小堆细胞，与“像一小堆豆子”相符。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子是大型建筑，不可能像一小堆豆子。"}, {"text": "声音", "is_correct": false, "explanation": "体貌：声音没有形状，不能像一小堆豆子那样有可见的形态。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车是交通工具，与一小堆豆子的小而圆的形态不符。"}], "explanations": {"核团": "正确：核团是一小堆细胞，与“像一小堆豆子”相符。", "房子": "语义：房子是大型建筑，不可能像一小堆豆子。", "声音": "体貌：声音没有形状，不能像一小堆豆子那样有可见的形态。", "汽车": "语义：汽车是交通工具，与一小堆豆子的小而圆的形态不符。"}, "sentence_index": 0, "correct_answer": "核团"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "脑袋里有一只核团，也有神经。", "explanation": "这里应该用〈个〉。核团是一小堆细胞，量词用“个”；“只”多指动物或成对器官中的一个。"}, {"text": "脑袋里有一条核团，也有神经。", "explanation": "这里应该用〈个〉。“条”用于细长的东西，核团不能用“条”来数。"}, {"text": "脑袋里有一张核团，也有神经。", "explanation": "这里应该用〈个〉。“张”用于平面的东西，核团不能用“张”来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084f3689-d866-4b50-a040-33b42f394f48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22944, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "核团", "is_correct": true, "explanation": "正确：画中的红色团状物可以是一个核团，句意成立。"}, {"text": "星期", "is_correct": false, "explanation": "体貌：星期没有颜色，无法被画成红色的东西。"}, {"text": "数学", "is_correct": false, "explanation": "语义：数学是学科，不是可以被画出红色的具体物体。"}, {"text": "声音", "is_correct": false, "explanation": "体貌：声音没有形状和颜色，无法被画成一个红色的物体。"}], "explanations": {"核团": "正确：画中的红色团状物可以是一个核团，句意成立。", "星期": "体貌：星期没有颜色，无法被画成红色的东西。", "数学": "语义：数学是学科，不是可以被画出红色的具体物体。", "声音": "体貌：声音没有形状和颜色，无法被画成一个红色的物体。"}, "sentence_index": 6, "correct_answer": "核团"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个核团是我们班的篮球队。", "explanation": "这里的“核团”指由人组成的篮球队，但核团只指身体里像小豆子一样的一堆细胞，不指人群。"}, {"text": "这个核团是老师分给我们的研究小组。", "explanation": "这里的“核团”指一个研究小组，但核团是细胞的聚集，不能用来指人组成的小组。"}, {"text": "这个核团在学校的合唱比赛中得了奖。", "explanation": "这里的“核团”指一支参赛的合唱团，但核团是细胞的聚集，不能用来指人组成的团体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084f3689-d866-4b50-a040-33b42f394f48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22944, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个核团们圆圆的，很小。", "corrected_sentence": "这个核团圆圆的，很小。", "error_description": "“们”只用于指人或拟人的群体，核团是一小堆细胞，不能加“们”。错误在“核团们”，正确为“这个核团”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084f3689-d866-4b50-a040-33b42f394f48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22944, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个核团大不，像一颗豆子。", "corrected_sentence": "这个核团不大，像一颗豆子。", "error_description": "语序错误：形容词的否定应说“不大”，“大不”不能单独成立。错误在“大不”，正确为“不大”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084f3689-d866-4b50-a040-33b42f394f48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
