INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22950, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "疑核是脑子里一个很小的部分，帮助听声音和吞咽。", "primary_collocate": null, "pronunciation": "yí hé", "ipa": "i³⁵ xɤ³⁵", "syllable_count": 2, "sentences": [{"text": "疑核是脑子里一个很小的部分。", "target_word": "疑核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "疑核帮助我们吞咽食物。", "target_word": "疑核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "疑核也和听声音有关系。", "target_word": "疑核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在图上指出了疑核。", "target_word": "疑核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "喝水的时候，疑核在帮助你吞咽。", "target_word": "疑核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "疑核受伤后，病人吞咽会很难。", "target_word": "疑核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上说，疑核在脑子的下面。", "target_word": "疑核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生给我们看了疑核的图片。", "target_word": "疑核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "疑核太小了，用眼睛几乎看不见。", "target_word": "疑核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想知道疑核怎么帮助人吞咽。", "target_word": "疑核", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "脑子里很小的部分，帮助听声音和吞咽", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee052b8c-9e6c-48f8-b11a-3507e31e09ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22950, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "疑核", "is_correct": true, "explanation": "脑子里帮助听声音和吞咽的小部分，即正确答案。"}, {"text": "议和", "is_correct": false, "explanation": "yì（第四声）与 yí（第二声）声调不同，意思是为停战而谈判。"}, {"text": "梨核", "is_correct": false, "explanation": "lí（l-）与 yí（零声母）声母不同，意思是梨子中间的核。"}, {"text": "棋盒", "is_correct": false, "explanation": "qí（q-）与 yí（零声母）声母不同，意思是装棋子的小盒。"}], "explanations": {"疑核": "脑子里帮助听声音和吞咽的小部分，即正确答案。", "议和": "yì（第四声）与 yí（第二声）声调不同，意思是为停战而谈判。", "梨核": "lí（l-）与 yí（零声母）声母不同，意思是梨子中间的核。", "棋盒": "qí（q-）与 yí（零声母）声母不同，意思是装棋子的小盒。"}, "sentence_index": null, "correct_answer": "疑核"}, "level_3": {"options": [{"text": "疑核", "is_correct": true, "explanation": "正确：疑核确是脑子里一个很小的部分，符合句意。"}, {"text": "心脏", "is_correct": false, "explanation": "语义：心脏在胸腔里，不在脑子里。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆是建筑，不是脑子里的部分。"}, {"text": "大海", "is_correct": false, "explanation": "搭配：“很小的部分”不能修饰大海，大海是很大的整体。"}], "explanations": {"疑核": "正确：疑核确是脑子里一个很小的部分，符合句意。", "心脏": "语义：心脏在胸腔里，不在脑子里。", "图书馆": "语义：图书馆是建筑，不是脑子里的部分。", "大海": "搭配：“很小的部分”不能修饰大海，大海是很大的整体。"}, "sentence_index": 0, "correct_answer": "疑核"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "脑子里有很多疑核，各管一件事。", "explanation": "这里应该用〈脑区〉。疑核是一个特定核团的名称，不能泛指脑中的各个区域。"}, {"text": "我的疑核有点疼，去看了医生。", "explanation": "这里应该用〈喉咙〉。疑核在脑干中，人体感觉不到它的疼痛，不能这样描述。"}, {"text": "老师指着一只疑核说，这里负责吞咽。", "explanation": "这里应该用〈个〉。“只”多指动物或成对器官中的一个，疑核一般作为单个结构计量，用“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084f3689-d866-4b50-a040-33b42f394f48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22950, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "疑核", "is_correct": true, "explanation": "正确：疑核的位置在脑子下部，符合“在脑子的下面”。"}, {"text": "篮球", "is_correct": false, "explanation": "语义：篮球是体育器材，不是脑中结构，与解剖语境不符。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车是交通工具，不在脑子里。"}, {"text": "钢铁", "is_correct": false, "explanation": "搭配：“在…的下面”指空间中的部位，“钢铁”是材料，不能这样组合。"}], "explanations": {"疑核": "正确：疑核的位置在脑子下部，符合“在脑子的下面”。", "篮球": "语义：篮球是体育器材，不是脑中结构，与解剖语境不符。", "汽车": "语义：汽车是交通工具，不在脑子里。", "钢铁": "搭配：“在…的下面”指空间中的部位，“钢铁”是材料，不能这样组合。"}, "sentence_index": 6, "correct_answer": "疑核"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他买了一个疑核送给弟弟。", "explanation": "这里应该用〈玩具〉。疑核是人体内的结构，不能购买，也不能作为礼物。"}, {"text": "小朋友把疑核拿在手里玩。", "explanation": "这里应该用〈皮球〉。疑核在脑干中，不能拿在手里玩耍。"}, {"text": "妈妈每天都陪疑核去散步。", "explanation": "这里应该用〈小狗〉。疑核不会行走，不能被人牵着散步。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084f3689-d866-4b50-a040-33b42f394f48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22950, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我以前在书上看过过疑核。", "corrected_sentence": "我以前在书上看过疑核。", "error_description": "“过”重复错误：经历体标记“过”只需一个，应紧跟动词，写作“看过疑核”，不能写成“看过过疑核”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084f3689-d866-4b50-a040-33b42f394f48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22950, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他终于找到了疑核地位置。", "corrected_sentence": "他终于找到了疑核的位置。", "error_description": "结构助词错误：修饰名词“位置”应用“的”，不能用“地”（“地”用于修饰动词或形容词），应说“疑核的位置”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084f3689-d866-4b50-a040-33b42f394f48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
