INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22952, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "大脑里有一条像带子的地方。", "primary_collocate": null, "pronunciation": "kòu dài huí", "ipa": "kʰou˥˩ tai˥˩ xuei˧˥", "syllable_count": 3, "sentences": [{"text": "扣带回像一条带子，在大脑里面。", "target_word": "扣带回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图上这条弯弯的带子就是扣带回。", "target_word": "扣带回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师指着大脑图，说这里是扣带回。", "target_word": "扣带回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "扣带回在大脑中间，形状像带子。", "target_word": "扣带回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能在大脑模型里找到扣带回吗？", "target_word": "扣带回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "扣带回是大脑里的一个小地方。", "target_word": "扣带回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他画了大脑中间那条像带子的结构，叫扣带回。", "target_word": "扣带回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "扣带回很长，绕着大脑中间走。", "target_word": "扣带回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们今天学习大脑里的扣带回。", "target_word": "扣带回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大脑里这个地方叫扣带回，像一条带子。", "target_word": "扣带回", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "前扣带回", "label": "复合"}, {"form": "扣帶回", "label": "繁体"}], "register": "中性", "sense_fingerprint": "大脑里形状像带子的一个部位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3dced0e1-ca52-4764-bae4-ec3acb1be799') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22952, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "扣带回", "is_correct": true, "explanation": "正确：扣带回位于大脑里面，形状像带子，与句中描述一致。"}, {"text": "脊髓", "is_correct": false, "explanation": "语义：脊髓位于脊柱内，不在大脑里面，与“在大脑里面”矛盾。"}, {"text": "心脏", "is_correct": false, "explanation": "语义：心脏不在大脑里，也不是带状结构，与句中两个条件都不符。"}, {"text": "肺", "is_correct": false, "explanation": "体貌：肺呈海绵状，不像带子，与“形状像带子”的描述不符。"}], "explanations": {"扣带回": "正确：扣带回位于大脑里面，形状像带子，与句中描述一致。", "脊髓": "语义：脊髓位于脊柱内，不在大脑里面，与“在大脑里面”矛盾。", "心脏": "语义：心脏不在大脑里，也不是带状结构，与句中两个条件都不符。", "肺": "体貌：肺呈海绵状，不像带子，与“形状像带子”的描述不符。"}, "sentence_index": 0, "correct_answer": "扣带回"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生切开了一只扣带回，看它的形状。", "explanation": "这里量词用错。“只”多用于动物或成对的部位，扣带回是大脑里的脑区，应数“个”。"}, {"text": "医生切开了一颗扣带回，看它的形状。", "explanation": "这里量词用错。“颗”用于小而圆的东西，扣带回是带状的脑区，应数“个”。"}, {"text": "医生切开了一把扣带回，看它的形状。", "explanation": "这里量词用错。“把”用于有柄或可握的物件，扣带回是脑区，应数“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a49a86c0-0524-4da3-81cd-5fb83a331079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
